pub fn captured_clock(snapshot: Option<&semio_framework_plugin::WindowTransientSnapshot>, window_id: &str) -> Option<Fem2dPlaybackClock> {
    snapshot.filter(|snapshot| snapshot.window_id() == window_id && snapshot.window_kind_id() == WINDOW_KIND_ID).and_then(|snapshot| snapshot.get::<Fem2dResultsWindowTransientOwner>()).and_then(|state| state.clock)
}
