    if let Some(json) = payload.status_json.as_mut() {
        *json = store::pack_rt::scene_field_json_text(json)?;
    }
    if let Some(json) = payload.computing_json.as_mut() {
        *json = store::pack_rt::scene_field_json_text(json)?;
    }
    if let Some(json) = payload.capabilities_json.as_mut() {
