        projection: GltfCameraProjection::Orthographic(GltfOrthographic { xmag: 1.0, ymag: 1.0, zfar: 10.0, znear: 0.1, extensions: None, extras: None }),
        name: Some("ortho-cam".into()),
        extensions: None,
        extras: None,
