    #[cfg(not(target_arch = "wasm32"))]
    fn cancel_interaction_future_reservation(&self) -> bool {
        match self.0.completions.try_lock() {
            Ok(mut completions) => completions.cancel_interaction_reservation(),
            Err(std::sync::TryLockError::Poisoned(error)) => error.into_inner().cancel_interaction_reservation(),
            Err(std::sync::TryLockError::WouldBlock) => false,
        }
    }

    #[cfg(not(target_arch = "wasm32"))]
    fn try_take_abandoned_frame_maintenance(&self) -> Option<FrameMaintenanceRefusal> {
        let (generation, owner) = self.0.frame_maintenance_executions.try_take_abandoned()?;
        let _ = self.0.frame_maintenance.release(generation);
        Some(FrameMaintenanceRefusal { owner, reservation_live: false })
    }

    #[cfg(not(target_arch = "wasm32"))]
    fn try_take_abandoned_frame_deferred(&self) -> Option<FrameDeferredExecutionOwner> {
        let (_, owner) = self.0.frame_deferred_executions.try_take_abandoned()?;
        owner.try_take()
    }

    #[cfg(not(target_arch = "wasm32"))]
    fn spawn_interaction_reserved<F>(&self, _key: Option<&'static str>, future: F)
    where
        F: Future<Output = AppInteractionState> + Send + 'static,
    {
        let mailbox = self.clone();
        let revision = mailbox.0.next_revision.fetch_add(1, Ordering::Relaxed);
        spawn_app_task(async move {
            let interaction = future.await;
            mailbox.0.finish(returned_completion(revision, RuntimeApply::RestoreInteraction(Some(interaction))));
        });
    }

    #[cfg(not(target_arch = "wasm32"))]
    fn spawn_dispatch_reserved<F>(&self, future: F)
    where
        F: Future<Output = (AppInteractionState, RuntimeDispatchCursor)> + Send + 'static,
    {
        let mailbox = self.clone();
        let revision = mailbox.0.next_revision.fetch_add(1, Ordering::Relaxed);
        spawn_app_task(async move {
            let (interaction, cursor) = future.await;
            mailbox.0.finish(returned_completion(revision, RuntimeApply::ResumeDispatch { interaction: Some(interaction), cursor: Some(cursor) }));
        });
    }

    #[cfg(not(target_arch = "wasm32"))]
    fn try_spawn_frame_deferred_reserved(&self, owner: FrameDeferredExecutionOwner) -> Result<(), FrameDeferredExecutionOwner> {
        let Some(generation) = owner.generation() else { return Err(owner) };
        let cell = Arc::new(FrameExecutionOwnerCell::new(owner));
        let registry = self.0.frame_deferred_executions.clone();
        if registry.try_publish(generation, cell.clone()).is_err() {
            return Err(cell.try_take().expect("rejected frame deferred owner remains available"));
        }
        let mailbox = self.clone();
        let revision = mailbox.0.next_revision.fetch_add(1, Ordering::Relaxed);
        let execution = FrameDeferredExecutionEnvelope::new(mailbox.clone(), registry, generation, revision);
        spawn_app_task(async move {
            let Some(mut execution) = execution.begin() else {
                mailbox.record_frame_fault("frame deferred exact owner was unavailable");
                return;
            };
            let Some(work) = execution.owner_mut().and_then(|owner| owner.work.take()) else {
                mailbox.record_frame_fault("frame deferred exact work owner was unavailable");
                return;
            };
            match work {
                FrameDeferredWork::ShellMaintenance => {}
                FrameDeferredWork::PumpSync => {
                    let Some(interaction) = execution.owner_mut().and_then(|owner| owner.interaction.as_mut()) else { return };
                    interaction.shell.pump_sync_events().await;
                }
                FrameDeferredWork::Action(action) => {
                    if action.cancelled {
                        action.cancel();
                    } else {
                        let receipt = action.receipt;
                        let mut receipt_owner = FrameActionReceiptOwner { receipt };
                        let result = {
                            let Some(interaction) = execution.owner_mut().and_then(|owner| owner.interaction.as_mut()) else { return };
                            interaction.shell.dispatch_gesture_action(action.descriptor).await
                        };
                        match result {
                            Ok(()) => receipt_owner.settle(engine_canvas::TextEditorActionOutcome::Accepted),
                            Err(error) => {
                                receipt_owner.settle(engine_canvas::TextEditorActionOutcome::Refused(&error));
                                let Some(owner) = execution.owner_mut() else { return };
                                if let Some(receipt) = receipt {
                                    if receipt.abort_correlation_on_error {
                                        owner.cursor.as_mut().map(|cursor| cursor.actions.cancel_correlation(receipt.token));
                                    }
                                }
                                if let Some(interaction) = owner.interaction.as_mut() {
                                    log_debug(&format!("[TRACE] frame deferred action failed: {error}"));
                                    interaction.shell.note_dispatch_fault(&error);
                                }
                            }
                        }
                    }
                }
                FrameDeferredWork::FlushTutorial => {
                    let Some(interaction) = execution.owner_mut().and_then(|owner| owner.interaction.as_mut()) else { return };
                    interaction.shell.tutorial_flush_pending_document_ops().await;
                }
                FrameDeferredWork::Settle => {
                    let Some(interaction) = execution.owner_mut().and_then(|owner| owner.interaction.as_mut()) else { return };
                    interaction.shell.settle_pump_step().await;
                }
            }
            if !execution.finish() {
                mailbox.record_frame_fault("frame deferred execution handback faulted");
            }
        });
        Ok(())
    }

    #[cfg(not(target_arch = "wasm32"))]
    fn try_spawn_frame_maintenance_reserved(&self, owner: FrameMaintenanceOwner) -> Result<(), FrameMaintenanceRefusal> {
        let Some(generation) = owner.generation() else {
            return Err(FrameMaintenanceRefusal { owner: Arc::new(FrameExecutionOwnerCell::new(owner)), reservation_live: true });
        };
        let cell = Arc::new(FrameExecutionOwnerCell::new(owner));
        if !self.0.frame_maintenance.try_reserve(generation) {
            return Err(FrameMaintenanceRefusal { owner: cell, reservation_live: true });
        }
        let registry = self.0.frame_maintenance_executions.clone();
        if registry.try_publish(generation, cell.clone()).is_err() {
            let _ = self.0.frame_maintenance.release(generation);
            return Err(FrameMaintenanceRefusal { owner: cell, reservation_live: true });
        }
        let mailbox = self.clone();
        let revision = mailbox.0.next_revision.fetch_add(1, Ordering::Relaxed);
        let worker_pool = renderer_worker_pool();
        let execution = FrameMaintenanceExecutionEnvelope::new(mailbox.clone(), registry.clone(), generation, revision);
        let job: semio_framework_async::Job = Box::new(move || {
            let Some(mut execution) = execution.begin() else {
                mailbox.record_frame_fault("frame maintenance exact owner pair was incomplete");
                return;
            };
            let stale;
            {
                let Some(owner) = execution.owner_mut() else {
                    mailbox.record_frame_fault("frame maintenance execution lost its exact owner");
                    return;
                };
                let FrameMaintenanceOwner { interaction, cursor, deadline_ms } = owner;
                let (Some(interaction), Some(cursor)) = (interaction.as_mut(), cursor.as_mut()) else {
                    mailbox.record_frame_fault("frame maintenance exact owner pair was incomplete");
                    return;
                };
                let cancelled = cursor.cancel.is_cancelled_now();
                stale = !mailbox.0.frame_maintenance.is_live(generation) || mailbox.0.presentation_authority.witness_for(generation).is_none();
                let deadline_exceeded = deadline_ms.is_none_or(|deadline| worker_pool.now_ms() > deadline);
                if let Some(fault) = frame_maintenance_terminal_fault(cancelled, stale, deadline_exceeded) {
                    cursor.begin_close();
                    interaction.frame_fault = Some(fault.to_string());
                } else {
                    cursor.shell_maintenance = interaction.shell.advance_chrome_maintenance_step();
                    if cursor.shell_maintenance {
                        cursor.phase = 0;
                    }
                    if deadline_ms.is_some_and(|deadline| worker_pool.now_ms() > deadline) {
                        interaction.frame_fault = Some("frame maintenance bounded field exceeded its deadline".to_string());
                        cursor.begin_close();
                    }
                }
                if !mailbox.0.frame_maintenance.release(generation) && !stale {
                    interaction.frame_fault = Some("frame maintenance authority release faulted".to_string());
                    cursor.begin_close();
                }
            }
            if !execution.finish() {
                mailbox.record_frame_fault("frame maintenance execution handback faulted");
            }
        });
        match renderer_worker_pool().try_submit(semio_framework_async::Lane::Io, job) {
            Ok(()) => Ok(()),
            Err(error) => {
                let reclaimed = registry.reclaim_rejected(generation, cell);
                drop(error.into_job());
                let _ = self.0.frame_maintenance.release(generation);
                Err(FrameMaintenanceRefusal { owner: reclaimed, reservation_live: true })
            }
        }
    }

    #[cfg(target_arch = "wasm32")]
    fn spawn_frame_maintenance_reserved<F>(&self, future: F)
    where
        F: Future<Output = (AppInteractionState, FrameDeferredCursor)> + 'static,
    {
        self.spawn_frame_deferred_reserved(future);
    }

    #[cfg(target_arch = "wasm32")]
    fn spawn_frame_deferred_reserved<F>(&self, future: F)
    where
        F: Future<Output = (AppInteractionState, FrameDeferredCursor)> + 'static,
    {
        let mailbox = self.clone();
        let revision = mailbox.0.next_revision.fetch_add(1, Ordering::Relaxed);
        spawn_app_task(async move {
            let (interaction, cursor) = future.await;
            mailbox.0.finish(returned_completion(revision, RuntimeApply::ResumeFrameDeferred { interaction: Some(interaction), cursor: Some(cursor) }));
        });
    }

    #[cfg(target_arch = "wasm32")]
    fn spawn_dispatch_reserved<F>(&self, future: F)
    where
        F: Future<Output = (AppInteractionState, RuntimeDispatchCursor)> + 'static,
    {
        let mailbox = self.clone();
        let revision = mailbox.0.next_revision.fetch_add(1, Ordering::Relaxed);
        spawn_app_task(async move {
            let (interaction, cursor) = future.await;
            mailbox.0.finish(returned_completion(revision, RuntimeApply::ResumeDispatch { interaction: Some(interaction), cursor: Some(cursor) }));
        });
    }

    /// 📮️ Applies at most ONE completion, and never lets a live interaction checkout stall the queue.
    ///
    /// 🩸️ This used to read only the HEAD and refuse the whole turn without popping while that head
    /// wanted the checked-out interaction state. Two things then went wrong at once on the browser:
    /// every completion behind it stalled — including work that needed no interaction at all — and,
    /// because the only caller was ONE phase of a frame build (`🧵️frame-job` `ApplyPending`), a build
    /// that parked on `!interaction_available()` held its session forever and no LATER build ever ran
    /// that phase again. Input reached `WindowDelegate::handle_event` and was enqueued, and
    /// `dispatch_normalized_event` was never reached (ticket 26/09/09/PROCEDURAL-3D-END-TO-END,
    /// `📓️wgpu-server-input-present-2026-09-13.md` §5.2). The pump is now driven from EVERY frame-build
    /// advance, the queue admits work that needs no state past work that does, and a checkout that
    /// with no owner left to return it publishes a typed fault naming its site instead of freezing in
    /// silence — while a checkout that merely takes a long time defers, however long it takes.
    /// 📮️ The HOST TICK's own bounded share of the mailbox.
    ///
    /// ⚖️ The frame build pumps the mailbox from every advance, but a build cannot always run — while
    /// the interaction state is checked out there is nothing to build, and the completion that brings
    /// it home lives in this queue. Pumping here as well is what makes "`DispatchEvents` and `Resize`
    /// are applied within the next frame" true unconditionally, independently of any build's lifetime.
    pub(crate) fn pump_pending_applies(&self, credits: u32) -> u32 {
        let mut applied = 0;
        while applied < credits && self.apply_pending_step() {
            applied += 1;
        }
        applied
    }

    fn restore_presenter_interaction_step(&self) -> PresenterInteractionStep {
        let Ok(mut runtime) = self.try_lock() else { return PresenterInteractionStep::RuntimeLock };
        if runtime.interaction_available() {
            return PresenterInteractionStep::Ready;
        }
        let (index, owner_outstanding) = {
            let queue = self.0.completions.lock().expect("runtime completion mailbox lock");
            (queue.first_interaction_restoration(), queue.interaction_owner_outstanding())
        };
        if let Some(index) = index {
            let Some(mut completion) = self.0.completions.lock().expect("runtime completion mailbox lock").take_at(index) else {
                return PresenterInteractionStep::Waiting { site: runtime.checkout.site().unwrap_or("unknown"), request: shell::host_io_request_trace_label() };
            };
            let complete = completion.apply.restore_interaction_only(&mut runtime);
            completion.restores_interaction = false;
            if !complete {
                self.0.completions.lock().expect("runtime completion mailbox lock").restore_at(index, completion);
            }
            return PresenterInteractionStep::Restored;
        }
        #[cfg(not(target_arch = "wasm32"))]
        if let Some(mut refusal) = runtime.pending_frame_maintenance_refusal.take() {
            if refusal.reservation_live {
                let cancelled = self.0.completions.lock().expect("runtime completion mailbox lock").cancel_interaction_reservation();
                if !cancelled {
                    runtime.pending_frame_maintenance_refusal = Some(refusal);
                    return PresenterInteractionStep::RuntimeLock;
                }
                refusal.reservation_live = false;
            }
            let Some(mut owner) = refusal.try_take() else {
                runtime.pending_frame_maintenance_refusal = Some(refusal);
                return PresenterInteractionStep::RuntimeLock;
            };
            let Some((interaction, cursor)) = owner.take_pair() else {
                if let Err(owner) = refusal.owner.try_restore(owner) {
                    refusal.owner = Arc::new(FrameExecutionOwnerCell::new(owner));
                }
                runtime.pending_frame_maintenance_refusal = Some(refusal);
                return PresenterInteractionStep::RuntimeLock;
            };
            if runtime.pending_frame_deferred.is_some() {
                owner.interaction = Some(interaction);
                owner.cursor = Some(cursor);
                if let Err(owner) = refusal.owner.try_restore(owner) {
                    refusal.owner = Arc::new(FrameExecutionOwnerCell::new(owner));
                }
                runtime.pending_frame_maintenance_refusal = Some(refusal);
                return PresenterInteractionStep::RuntimeLock;
            }
            runtime.return_interaction(interaction);
            runtime.pending_frame_deferred = Some(cursor);
            return PresenterInteractionStep::Restored;
        }
        #[cfg(not(target_arch = "wasm32"))]
        if runtime.pending_frame_deferred.is_none() {
            if let Some(mut owner) = self.try_take_abandoned_frame_deferred() {
                owner.cancel_current();
                let Some((interaction, cursor)) = owner.take_pair() else { return PresenterInteractionStep::RuntimeLock };
                runtime.return_interaction(interaction);
                runtime.pending_frame_deferred = Some(cursor);
                return PresenterInteractionStep::Restored;
            }
        }
        if owner_outstanding {
            PresenterInteractionStep::Waiting { site: runtime.checkout.site().unwrap_or("unknown"), request: shell::host_io_request_trace_label() }
        } else {
            PresenterInteractionStep::Abandoned
        }
    }

    /// 🎟️ On native the owner may also be a frame-maintenance refusal this runtime is still holding:
    /// the reservation is already cancelled and the state lives inside the refusal's owner cell, so
    /// the mailbox alone cannot see it.
    ///
    /// 🩺️ Once per abandoned episode, and the episode is what QUARANTINES the surface — the overlay
    /// is the only place this used to appear, and a probe reads the console, not the canvas.
    fn apply_pending_step(&self) -> bool {
        let Ok(mut runtime) = self.try_lock() else {
            log_debug_once_per_transition("apply-lock", true, "[TRACE] apply_pending_step blocked: runtime mutex is held");
            return false;
        };
        log_debug_once_per_transition("apply-lock", false, "[TRACE] apply_pending_step: runtime mutex acquired again");
        let available = runtime.interaction_available();
        let queue = self.0.completions.lock().expect("runtime completion mailbox lock");
        let head_requires_interaction = queue.head_requires_interaction();
        let owner_outstanding = queue.interaction_owner_outstanding();
        let index = queue.first_applicable(available);
        drop(queue);
        #[cfg(not(target_arch = "wasm32"))]
        let owner_outstanding = owner_outstanding || runtime.pending_frame_maintenance_refusal.is_some();
        let admission = runtime.checkout.admit(head_requires_interaction, available, owner_outstanding);
        let blocked = matches!(admission, runtime_mailbox_core::InteractionCheckoutStep::Deferred | runtime_mailbox_core::InteractionCheckoutStep::Abandoned);
        log_debug_once_per_transition(
            "apply-interaction",
            blocked,
            &if blocked {
                format!("[TRACE] apply_pending_step blocked: head needs the interaction state, checked out at {:?} for {} opportunities", runtime.checkout.site(), runtime.checkout.opportunities())
            } else {
                "[TRACE] apply_pending_step: interaction state is available again".to_string()
            },
        );
        if let Some((site, opportunities)) = runtime.checkout.take_abandoned_notice() {
            log_debug(&format!("[TRACE] frame fault recorded: runtime interaction checkout at {site} has no owner left to return it after {opportunities} apply opportunities"));
            let mut slot = self.0.frame_fault.lock().expect("runtime frame fault lock");
            if slot.is_none() {
                *slot = Some(format!("runtime interaction checkout at {site} has no owner left to return it after {opportunities} apply opportunities"));
            }
        }
        let Some(index) = index else { return false };
        let Some(mut completion) = self.0.completions.lock().expect("runtime completion mailbox lock").take_at(index) else { return false };
        if let Some(key) = completion.key {
            let mut applied = self.0.applied_revisions.lock().expect("runtime completion revisions lock");
            if applied.get(key).is_some_and(|revision| *revision >= completion.revision) {
                return true;
            }
            applied.insert(key, completion.revision);
        }
        let handle = self.downgrade();
        if completion.apply.apply_step(&mut runtime, &handle) {
            return true;
        }
        self.0.completions.lock().expect("runtime completion mailbox lock").restore_at(index, completion);
        false
    }
}

/// 🪪️ Weak address for submitting owned work and returning serial completions without retaining
/// `AppRuntime` or a mutex guard across suspension.
type AppHandle = std::sync::Weak<RuntimeMailboxInner>;

//#endregion 📮️RuntimeMailbox

//#region 🎮️AppInteractionState

const TEXT_STREAM_CAPACITY: usize = 64;

#[derive(Clone, Copy)]
struct AppTextStream {
    id: u64,
    token: ui_contract::TextIngressToken,
}

struct AppRuntime {
    atlas: FontAtlas,
    icons: IconAtlas,
    /// 🔁️ In-flight bounded icon re-rasterisation after a post-boot density change — see
    /// `icon_atlas::IconAtlasRebuild`. `None` while the atlas already matches the surface density.
    icon_rebuild: Option<crate::icon_atlas::IconAtlasRebuild>,
    /// 📐️ The surface scale factor `icons` was rasterised at, so an ordinary window drag (same
    /// density) never starts a rebuild.
    icon_raster_scale: f32,
    interaction: Option<AppInteractionState>,
    checkout: runtime_mailbox_core::InteractionCheckoutLedger,
    draw: DrawList,
    overlay: DrawList,
    pending_frame_deferred: Option<FrameDeferredCursor>,
    /// 🧾️ Every action a frame's authorities MINT, owned by the runtime and never by the frame
    /// candidate that minted it.
    ///
    /// 🩸️ It used to be a field of [`FrameTransaction`], handed down through [`FrameBuildCursor`],
    /// [`AppFrameAfterChrome`] and [`FrameFinishCursor`] and only reaching this runtime at
    /// [`FrameFinishPhase::Complete`]. A frame candidate is DISCARDABLE by construction — 655
    /// supersessions in one 140 s session on 6118 — and `AppFrameTransactionStep::Superseded` drops
    /// the whole transaction without retiring it, so an action `take_action_step` had already taken
    /// OUT of the bounded input authority was destroyed with it: measured as a retained rename whose
    /// `renameGeneration` commit reached `AppFrameTransactionPhase::InputEvents` and was superseded
    /// 1 ms later, never installed, never dispatched, never even retired
    /// (ticket 26/09/09/PROCEDURAL-3D-END-TO-END, `📓️wgpu-deferred-action-commit-2026-09-13.md`).
    /// A user's commit is SESSION state, not frame state; the frame only borrows it at install.
    frame_actions: FrameActionOwners,
    #[cfg(not(target_arch = "wasm32"))]
    pending_frame_maintenance_refusal: Option<FrameMaintenanceRefusal>,
    #[cfg(not(target_arch = "wasm32"))]
    plugin_modules_root: std::path::PathBuf,
    #[cfg(not(target_arch = "wasm32"))]
    native_plugin_mtimes: std::collections::HashMap<std::path::PathBuf, std::time::SystemTime>,
    #[cfg(not(target_arch = "wasm32"))]
    native_hot_swap_scan: Option<RendererIoHandle>,
    #[cfg(not(target_arch = "wasm32"))]
    native_hot_swap_modified: Option<semio_framework_os_services::NativeModifiedSet>,
    #[cfg(not(target_arch = "wasm32"))]
    native_hot_swap_cursor: usize,
    #[cfg(not(target_arch = "wasm32"))]
    native_reload_pending: bool,
}

pub(crate) struct AppInteractionState {
    shell: ShellState,
    input: InputState<ActionDescriptor>,
    theme: Theme,
    theme_dark: bool,
    last_pointer_x: f32,
    last_pointer_y: f32,
    pointer_down: bool,
    pointer_button: i16,
    /// 🎯️ The layer that owns the pointer SEQUENCE in flight — set on the press from
    /// [`ShellState::pointer_owner_at`] and cleared on the release. React gets this from the DOM: the
    /// element a `pointerdown` resolved to receives the whole gesture, so a press that landed on
    /// chrome keeps every move and the release away from the canvas underneath it, whatever the
    /// pointer travels over in between.
    pointer_capture: PointerCapture,
    modifiers: PointerModifiers,
    space_pressed: bool,
    wheel_zoom_deadline_ms: f64,
    text_streams: [Option<AppTextStream>; TEXT_STREAM_CAPACITY],
    text_fault: Option<String>,
    frame_fault: Option<String>,
    text_cancel_pending: bool,
    last_sync_pump_ms: f64,
}

impl std::ops::Deref for AppRuntime {
    type Target = AppInteractionState;

    fn deref(&self) -> &Self::Target {
        self.interaction.as_ref().expect("runtime interaction state is worker-owned")
    }
}

impl std::ops::DerefMut for AppRuntime {
    fn deref_mut(&mut self) -> &mut Self::Target {
        self.interaction.as_mut().expect("runtime interaction state is worker-owned")
    }
}

impl AppRuntime {
    fn interaction_available(&self) -> bool {
        self.interaction.is_some()
    }

    /// 📐️ The one resize the runtime owns: the content root moves in LOGICAL pixels and the glyph
    /// atlas — the only layout-facing owner that legitimately cares about device density — is
    /// re-pointed at the new scale factor. `set_raster_scale` is a no-op when the scale is
    /// unchanged, so an ordinary window drag never drops a single cached glyph; a display change
    /// does, and the atlas re-rasterises crisp at the new density on the next frame.
    /// Shadows the `Deref` route into [`AppInteractionState::resize`] deliberately.
    fn resize(&mut self, logical_width: f32, logical_height: f32, scale_factor: f32) {
        self.atlas.set_raster_scale(scale_factor);
        self.begin_icon_raster(scale_factor);
        if let Some(interaction) = self.interaction.as_mut() {
            interaction.resize(logical_width, logical_height, scale_factor);
        }
    }

    /// 🔁️ Arms a bounded icon re-rasterisation when `scale_factor` lands on a different atlas CELL
    /// size than the icons were rasterised at. Cell size, not raw scale: the atlas quantises the
    /// factor (`icon_cell_size` rounds and clamps to 3×), so a fractional resize that quantises the
    /// same way must not throw away 250 good rasterisations. The glyph atlas already re-rasterises
    /// lazily on the same event; this closes the icon half (ticket 26/09/17 packet W2k, W1g gap 1).
    fn begin_icon_raster(&mut self, scale_factor: f32) {
        if !scale_factor.is_finite() || scale_factor <= 0.0 {
            return;
        }
        let pending = crate::icon_atlas::IconAtlasRebuild::new(scale_factor);
        if pending.cell_size() == crate::icon_atlas::IconAtlasRebuild::new(self.icon_raster_scale).cell_size() {
            return;
        }
        self.icon_rebuild = Some(pending);
    }

    /// 🔁️ Spends one bounded slice on the in-flight icon rebuild. Answers the finished atlas exactly
    /// once, on the step that completes it, so the caller installs and re-uploads it.
    fn drive_icon_raster_step(&mut self) -> Option<IconAtlas> {
        let rebuild = self.icon_rebuild.as_mut()?;
        match rebuild.step(crate::icon_atlas::ICON_RASTER_STEP_BUDGET) {
            crate::icon_atlas::IconAtlasRebuildStep::Rasterized(_) => None,
            crate::icon_atlas::IconAtlasRebuildStep::Complete(atlas) => {
                let scale = rebuild.scale_factor();
                self.icon_rebuild = None;
                self.icon_raster_scale = scale;
                Some(atlas)
            }
        }
    }

    /// 🎟️ The ONE way the interaction state leaves the runtime, so every checkout is named and aged.
    ///
    /// ⚖️ `site` is the bounded step the state is lent to; it must come home through
    /// [`Self::return_interaction`] on every path, faults and supersession included.
    fn check_out_interaction(&mut self, site: &'static str) -> Option<AppInteractionState> {
        let interaction = self.interaction.take()?;
        if !self.checkout.check_out(site) {
            self.interaction = Some(interaction);
            return None;
        }
        Some(interaction)
    }

    /// 🎟️ The ONE way the interaction state comes home.
    fn return_interaction(&mut self, interaction: AppInteractionState) {
        self.checkout.check_in();
        self.interaction = Some(interaction);
    }

    #[cfg(not(target_arch = "wasm32"))]
    fn submit_interaction<F, Fut>(&mut self, handle: &AppHandle, key: Option<&'static str>, work: F) -> bool
    where
        F: FnOnce(AppInteractionState) -> Fut,
        Fut: Future<Output = AppInteractionState> + Send + 'static,
    {
        let Some(interaction) = self.check_out_interaction("submit-interaction") else { return false };
        let Some(mailbox) = handle.upgrade().map(RuntimeMailbox) else {
            self.return_interaction(interaction);
            return false;
        };
        if !mailbox.reserve_interaction_future() {
            self.return_interaction(interaction);
            return false;
        }
        mailbox.spawn_interaction_reserved(key, work(interaction));
        true
    }
}

//#endregion 🎮️AppInteractionState

const FRAME_ENGINE_PACKET_CAPACITY: usize = 256;

struct FrameEnginePackets {
    slots: Box<[Option<engine_canvas::EngineCanvasPacket>; FRAME_ENGINE_PACKET_CAPACITY]>,
    len: usize,
}

impl Default for FrameEnginePackets {
    fn default() -> Self {
        Self { slots: semio_framework_async::boxed_fixed_slots(|| None), len: 0 }
    }
}

impl FrameEnginePackets {
    fn try_push(&mut self, packet: engine_canvas::EngineCanvasPacket) -> Result<(), engine_canvas::EngineCanvasPacket> {
        if self.len == FRAME_ENGINE_PACKET_CAPACITY {
            return Err(packet);
        }
        self.slots[self.len] = Some(packet);
        self.len += 1;
        Ok(())
    }

    fn pop(&mut self) -> Option<engine_canvas::EngineCanvasPacket> {
        let index = self.len.checked_sub(1)?;
        self.len = index;
        self.slots[index].take()
    }

    fn last_mut(&mut self) -> Option<&mut engine_canvas::EngineCanvasPacket> {
        self.len.checked_sub(1).and_then(|index| self.slots[index].as_mut())
    }

    fn get(&self, index: usize) -> Option<&engine_canvas::EngineCanvasPacket> {
        (index < self.len).then(|| self.slots[index].as_ref()).flatten()
    }

    fn is_empty(&self) -> bool {
        self.len == 0 && self.slots.iter().all(Option::is_none)
    }
}

