        "subTitle" => PlaceholderKind::Subtitle,
        "body" => PlaceholderKind::Body,
        "ftr" => PlaceholderKind::Footer,
        "sldNum" => PlaceholderKind::SlideNumber,
        "dt" => PlaceholderKind::DateTime,
        other => PlaceholderKind::Other { value: other.to_string() },
    }
}

