fn fan_operating_hours_weighted(doc: &Din18599Snapshot) -> f64 {
    let v: f64 = doc.zones.iter().map(|z| z.volume_m3).sum::<f64>().max(1e-9);
    doc.zones.iter().map(|z| usage_profile_row(z.usage_profile).fan_hours_a * z.volume_m3 / v).sum()
