    Ok(GifPlainText {
        left: parse_u32(left)?,
        top: parse_u32(top)?,
        width: parse_u32(width)?,
        height: parse_u32(height)?,
        cell_width: parse_u8(cw)?,
        cell_height: parse_u8(ch)?,
        fg_color_index: parse_u8(fg)?,
        bg_color_index: parse_u8(bg)?,
