macro_rules! value_field {
    ($kind:ty) => {
        impl DslField for $kind {
            fn shape() -> Shape {
                Shape::Value
            }
            fn to_value(&self) -> FieldValue {
                FieldValue::Value(semio_framework_value::ToValue::to_value(self))
