            fn from_value(value: &FieldValue) -> Result<Self, String> {
                match value {
                    FieldValue::Value(value) => semio_framework_value::FromValue::from_value(value.clone()).map_err(|error| error.to_string()),
                    other => Err(format!("expected Value, found {other:?}")),
                }
            }
        }
    };
