    /// 📋 Wall — Table 5.4: (h_min, a).
    pub fn wall(rating: FireRating) -> (f64, f64) {
        const T: &[(f64, f64)] = &[(100.0, 10.0), (120.0, 10.0), (140.0, 20.0), (160.0, 30.0)];
        let (h, a) = T[r_idx(rating)];
