        let length=match &output{crate::io_schema::IoPayload::Binary(bytes)=>bytes.len(),crate::io_schema::IoPayload::Text(text)=>text.len()};let mut exact=limits;exact.max_file_bytes=length;assert_eq!(super::encode_sqlite_snapshot_record_native(encoding,"fixture.output",ControlledOutputFields::__dsl_spec_producer(),|native|source.__dsl_to_record_controlled(native),&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap(),output);exact.max_file_bytes-=1;assert!(super::encode_sqlite_snapshot_record_native(encoding,"fixture.output",ControlledOutputFields::__dsl_spec_producer(),|native|source.__dsl_to_record_controlled(native),&mut SqliteSnapshotControl::new(&mut |_|true,exact)).is_err());
        let mut reached=false;let mut callback=|event:crate::sqlite_snapshot::SqliteSnapshotProgress|if event.phase==SqliteSnapshotPhase::EncodeNative&&event.total==count&&event.completed>=256&&event.completed<event.total{reached=true;false}else{true};assert!(super::encode_sqlite_snapshot_record_native(encoding,"fixture.output",ControlledOutputFields::__dsl_spec_producer(),|native|source.__dsl_to_record_controlled(native),&mut SqliteSnapshotControl::new(&mut callback,limits)).is_err());assert!(reached);
        let mut tiny=limits;tiny.max_value_bytes=1;assert!(super::encode_sqlite_snapshot_record_native(encoding,"fixture.output",ControlledOutputFields::__dsl_spec_producer(),|native|source.__dsl_to_record_controlled(native),&mut SqliteSnapshotControl::new(&mut |_|true,tiny)).is_err());
    }
}

