fn as_f64(v: &JsonValue) -> Result<f64, store::PackError> {
    match v {
        JsonValue::Number { lexeme } => lexeme.parse::<f64>().map_err(|e| store::PackError::Schema(format!("flow json: bad number lexeme {lexeme:?}: {e}"))),
