                Ok(ComposedArtifact { dialect: S::INTO, payload: IoPayload::Binary(bytes), diagnostics: Vec::new(), confidence: IoConfidence::High })
            })
        }
        ComposerEntry { writes: S::INTO, reads: &[S::FROM], compose: erased_compose::<S> }
    }
