//#region 🔖️State
async fn admit_wal_bytes(source: Vec<u8>, maximum: u64, control: &mut db_wal::WalCursorControl) -> Result<db_wal::WalBytes, DbError> {
    let source = if source.len() as u64 <= maximum && source.capacity() as u64 > maximum { source.into_boxed_slice().into_vec() } else { source };
    match db_wal::WalBytes::try_admit(source, maximum, control).await {
        Ok(bytes) => Ok(bytes),
        Err(mut rejected) => {
            control.grant()?;
            let _ = rejected.close_step()?;
            Err(rejected.into_error())
        }
    }
}

async fn push_wal_record(records: &mut db_wal::WalRecordBatch, record: db_wal::WalRecord, control: &mut db_wal::WalCursorControl) -> Result<(), DbError> {
    match records.push(record) {
        Ok(()) => Ok(()),
        Err(mut record) => {
            control.grant()?;
            let _ = record.close_step()?;
            drop(record);
            Err(DbError::LimitExceeded("db_artifact fixed wal record batch"))
        }
    }
}

async fn close_wal_record_batch(records: &mut db_wal::WalRecordBatch) -> Result<(), DbError> {
    let mut control = db_wal::WalCursorControl::new(Arc::new(std::sync::atomic::AtomicBool::new(false)), std::time::Instant::now() + std::time::Duration::from_secs(30), 1_000_000)?;
    while !records.terminal_is_empty() {
        control.grant()?;
        if !records.close_step()? && !records.terminal_is_empty() {
            return Err(DbError::Internal("WAL record batch retirement stalled".to_string()));
        }
        semio_framework_async::yield_once().await;
    }
    Ok(())
}

//#region 🔖️StateRetirement
const ARTIFACT_STATE_RETIREMENT_SLOTS: usize = 64;

/// 🧹️ Persists one rejected staging graph and advances exactly one refusal,
/// source, slot, page, or text owner for each maintenance grant.
struct ArtifactStateRetirementCursor {
    rejected: Option<db_state::StateEntryRejected>,
    staged: [Option<db_state::StateEntry>; 64],
    phase: u8,
    slot: u8,
    retirement: Option<ArtifactStateRetirementReservation>,
}

impl ArtifactStateRetirementCursor {
    fn rejected(retirement: ArtifactStateRetirementReservation, rejected: db_state::StateEntryRejected, staged: [Option<db_state::StateEntry>; 64]) -> Self {
        Self { rejected: Some(rejected), staged, phase: 0, slot: 0, retirement: Some(retirement) }
    }

    fn entry(retirement: ArtifactStateRetirementReservation, entry: db_state::StateEntry) -> Self {
        let mut staged = std::array::from_fn(|_| None);
        staged[0] = Some(entry);
        Self { rejected: None, staged, phase: 2, slot: 0, retirement: Some(retirement) }
    }

    fn staged(retirement: ArtifactStateRetirementReservation, staged: [Option<db_state::StateEntry>; 64]) -> Self {
        Self { rejected: None, staged, phase: 2, slot: 0, retirement: Some(retirement) }
    }

    fn empty() -> Self {
        Self { rejected: None, staged: std::array::from_fn(|_| None), phase: 3, slot: 64, retirement: None }
    }

    fn close_step(&mut self) -> Result<bool, DbError> {
        let cancelled = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let mut control = db_state::StateCursorControl::new(cancelled, std::time::Instant::now() + std::time::Duration::from_secs(30), 1)?;
        control.grant()?;
        match self.phase {
            0 => {
                let rejected = self.rejected.as_mut().ok_or_else(|| DbError::Internal("artifact retirement lost refusal owner".to_string()))?;
                if !rejected.close_step()? {
                    self.phase = 1;
                }
                Ok(true)
            }
            1 => {
                let source = self.rejected.take().and_then(db_state::StateEntryRejected::into_source);
                drop(source);
                self.phase = 2;
                Ok(true)
            }
            2 => {
                let Some(entry) = self.staged.get_mut(self.slot as usize) else {
                    self.phase = 3;
                    release_artifact_state_retirement(&mut self.retirement);
                    return Ok(true);
                };
                if let Some(entry) = entry.as_mut() {
                    if entry.close_step()? {
                        return Ok(true);
                    }
                }
                *entry = None;
                self.slot += 1;
                Ok(true)
            }
            _ => Ok(false),
        }
    }

    fn terminal_is_empty(&self) -> bool {
        self.phase == 3 && self.rejected.is_none() && self.staged.iter().all(Option::is_none)
    }
}

static ARTIFACT_STATE_RETIREMENT: std::sync::Mutex<[Option<ArtifactStateRetirementCursor>; ARTIFACT_STATE_RETIREMENT_SLOTS]> = std::sync::Mutex::new([const { None }; ARTIFACT_STATE_RETIREMENT_SLOTS]);
static ARTIFACT_STATE_RETIREMENT_OVERFLOW: std::sync::Mutex<[Option<ArtifactStateRetirementCursor>; ARTIFACT_STATE_RETIREMENT_SLOTS]> = std::sync::Mutex::new([const { None }; ARTIFACT_STATE_RETIREMENT_SLOTS]);
static ARTIFACT_STATE_RETIREMENT_QUARANTINE: std::sync::Mutex<[Option<ArtifactStateRetirementCursor>; ARTIFACT_STATE_RETIREMENT_SLOTS]> = std::sync::Mutex::new([const { None }; ARTIFACT_STATE_RETIREMENT_SLOTS]);
static ARTIFACT_STATE_RETIREMENT_RESERVATIONS: [std::sync::atomic::AtomicU64; 3] = [const { std::sync::atomic::AtomicU64::new(0) }; 3];
static ARTIFACT_STATE_RETIREMENT_PRESSURE_FAULT: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

#[derive(Clone, Copy)]
struct ArtifactStateRetirementReservation {
    tier: u8,
    index: u8,
}

fn reserve_artifact_state_retirement() -> Option<ArtifactStateRetirementReservation> {
    for tier in 0..3u8 {
        for index in 0..ARTIFACT_STATE_RETIREMENT_SLOTS as u8 {
            let bit = 1u64 << index;
            if ARTIFACT_STATE_RETIREMENT_RESERVATIONS[tier as usize].fetch_or(bit, std::sync::atomic::Ordering::AcqRel) & bit != 0 {
                continue;
            }
            let vacant = match tier {
                0 => ARTIFACT_STATE_RETIREMENT.lock().unwrap_or_else(std::sync::PoisonError::into_inner)[index as usize].is_none(),
                1 => ARTIFACT_STATE_RETIREMENT_OVERFLOW.lock().unwrap_or_else(std::sync::PoisonError::into_inner)[index as usize].is_none(),
                _ => ARTIFACT_STATE_RETIREMENT_QUARANTINE.lock().unwrap_or_else(std::sync::PoisonError::into_inner)[index as usize].is_none(),
            };
            if vacant {
                if tier != 0 {
                    ARTIFACT_STATE_RETIREMENT_PRESSURE_FAULT.store(true, std::sync::atomic::Ordering::Release);
                }
                return Some(ArtifactStateRetirementReservation { tier, index });
            }
            ARTIFACT_STATE_RETIREMENT_RESERVATIONS[tier as usize].fetch_and(!bit, std::sync::atomic::Ordering::AcqRel);
        }
    }
    ARTIFACT_STATE_RETIREMENT_PRESSURE_FAULT.store(true, std::sync::atomic::Ordering::Release);
    None
}

fn release_artifact_state_retirement(reservation: &mut Option<ArtifactStateRetirementReservation>) {
    if let Some(reservation) = reservation.take() {
        ARTIFACT_STATE_RETIREMENT_RESERVATIONS[reservation.tier as usize].fetch_and(!(1u64 << reservation.index), std::sync::atomic::Ordering::AcqRel);
    }
}

fn release_artifact_state_retirements(reservations: &mut [Option<ArtifactStateRetirementReservation>; 64]) {
    for reservation in reservations {
        release_artifact_state_retirement(reservation);
    }
}

fn artifact_state_vacant_retirement_slot(tier: usize, slots: &[Option<ArtifactStateRetirementCursor>]) -> Option<usize> {
    let reserved = ARTIFACT_STATE_RETIREMENT_RESERVATIONS[tier].load(std::sync::atomic::Ordering::Acquire);
    slots.iter().enumerate().position(|(index, slot)| slot.is_none() && reserved & (1u64 << index) == 0)
}

fn install_reserved_artifact_state_owner(owner: ArtifactStateRetirementCursor) {
    let reservation = owner.retirement.unwrap_or(ArtifactStateRetirementReservation { tier: 0, index: 0 });
    match reservation.tier {
        0 => ARTIFACT_STATE_RETIREMENT.lock().unwrap_or_else(std::sync::PoisonError::into_inner)[reservation.index as usize] = Some(owner),
        1 => ARTIFACT_STATE_RETIREMENT_OVERFLOW.lock().unwrap_or_else(std::sync::PoisonError::into_inner)[reservation.index as usize] = Some(owner),
        _ => ARTIFACT_STATE_RETIREMENT_QUARANTINE.lock().unwrap_or_else(std::sync::PoisonError::into_inner)[reservation.index as usize] = Some(owner),
    }
}

#[cfg(test)]
fn retire_artifact_state_owner(owner: ArtifactStateRetirementCursor) -> Result<(), ArtifactStateRetirementCursor> {
    if owner.retirement.is_some() {
        install_reserved_artifact_state_owner(owner);
        return Ok(());
    }
    let mut retired = ARTIFACT_STATE_RETIREMENT.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
    if let Some(index) = artifact_state_vacant_retirement_slot(0, &retired[..]) {
        retired[index] = Some(owner);
        Ok(())
    } else {
        drop(retired);
        ARTIFACT_STATE_RETIREMENT_PRESSURE_FAULT.store(true, std::sync::atomic::Ordering::Release);
        let mut overflow = ARTIFACT_STATE_RETIREMENT_OVERFLOW.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if let Some(index) = artifact_state_vacant_retirement_slot(1, &overflow[..]) {
            overflow[index] = Some(owner);
            return Ok(());
        }
        drop(overflow);
        let mut quarantine = ARTIFACT_STATE_RETIREMENT_QUARANTINE.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let Some(index) = artifact_state_vacant_retirement_slot(2, &quarantine[..]) else { return Err(owner) };
        quarantine[index] = Some(owner);
        Ok(())
    }
}

/// 🧹️ Advances one parked state retirement — a replaced or removed value, or a refused
/// staging graph. Every state apply drives it until nothing is parked, so a replaced value's pages
/// and its I/O operation never outlive the write that replaced it; parked owners used to wait for a
/// maintenance pass nothing ran, until the process ran out of I/O operations and refused every write.
pub fn artifact_state_retirement_maintenance_step() -> Result<bool, DbError> {
    let mut retired = ARTIFACT_STATE_RETIREMENT.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
    let Some(slot) = retired.iter_mut().find(|slot| slot.is_some()) else {
        drop(retired);
        let mut overflow = ARTIFACT_STATE_RETIREMENT_OVERFLOW.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let Some(index) = overflow.iter().position(Option::is_some) else {
            drop(overflow);
            let mut quarantine = ARTIFACT_STATE_RETIREMENT_QUARANTINE.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            let Some(index) = quarantine.iter().position(Option::is_some) else { return Ok(false) };
            let mut retired = ARTIFACT_STATE_RETIREMENT.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            let Some(target) = artifact_state_vacant_retirement_slot(0, &retired[..]) else {
                drop(retired);
                let owner = quarantine[index].as_mut().ok_or_else(|| DbError::Internal("artifact quarantine retirement changed owner".to_string()))?;
                if !owner.close_step()? {
                    quarantine[index] = None;
                }
                return Ok(true);
            };
            retired[target] = quarantine[index].take();
            return Ok(true);
        };
        let mut retired = ARTIFACT_STATE_RETIREMENT.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let Some(target) = artifact_state_vacant_retirement_slot(0, &retired[..]) else {
            drop(retired);
            let owner = overflow[index].as_mut().ok_or_else(|| DbError::Internal("artifact overflow retirement changed owner".to_string()))?;
            if !owner.close_step()? {
                overflow[index] = None;
            }
            return Ok(true);
        };
        retired[target] = overflow[index].take();
        return Ok(true);
    };
    let owner = slot.as_mut().ok_or_else(|| DbError::Internal("artifact retirement changed owner".to_string()))?;
    if owner.close_step()? {
        return Ok(true);
    }
    *slot = None;
    Ok(true)
}

impl Drop for ArtifactStateRetirementCursor {
    fn drop(&mut self) {
        if !self.terminal_is_empty() {
            install_reserved_artifact_state_owner(std::mem::replace(self, Self::empty()));
        }
    }
}
//#endregion 🔖️StateRetirement

/// 🏗️ A document's materialized state: a flat `db_state::PMap` from path to raw value
/// bytes, plus a per-path last-writer map for `submit`'s local, path-granular conflict detection
/// (see `🔖️Conflict`'s doc on why this stays local rather than `db_conflict`-backed). `values` uses
/// `PMap` (not a mutable `HashMap`) specifically so `content_hash` — the `Frontier.chain_hash`
/// source — is a real content-addressed digest of the whole state, not an incidental byte count,
/// and so `PMap::iter` gives `snapshot_now`/`query` a cheap, complete enumeration.
struct DocumentState {
    values: db_state::RetainedStateMap,
    last_writer: db_state::PMap<String, protocol::MutationId>,
}

/// 🗺️ One envelope planned by `ArtifactEngine::plan_one` and not applied yet: its path entries with every value
/// already encoded as the state stores it (`None` deletes), the regions it touches and the conflicts it meets.
struct PlannedEntries {
    entries: Vec<(String, Option<Vec<u8>>)>,
    touched: db_state::TouchedSet,
    conflicts: Vec<ConflictRecord>,
}

impl DocumentState {
    // 🚫️async: E1 pure constructor, `db_state::PMap::new` is sync — see R9
    fn new() -> DocumentState {
        DocumentState { values: db_state::RetainedStateMap::new(), last_writer: db_state::PMap::new() }
    }

    fn get(&self, path: &str) -> Option<&db_storage::DbIoPages> {
        self.values.get(path)
    }

    async fn content_hash(&self) -> Result<ContentHash, DbError> {
        let mut control = db_state::StateCursorControl::new(Arc::new(std::sync::atomic::AtomicBool::new(false)), std::time::Instant::now() + std::time::Duration::from_secs(30), 65_536)?;
        self.values.content_hash(&mut control).await
    }

    /// 🧭️ What applying one envelope's flattened path-value entries would touch and conflict with, decided
    /// without applying anything: a path's last writer is `written`'s (an earlier envelope of the same batch) or else
    /// the state's own, and a conflict is a last writer that is neither `mutation_id` itself nor a declared
    /// `dependencies` member. `written` gains this envelope's paths.
    fn plan_entries(&self, mutation_id: &protocol::MutationId, dependencies: &[protocol::MutationId], entries: &[(String, Option<DslValue>)], written: &mut HashMap<String, protocol::MutationId>) -> Result<(db_state::TouchedSet, Vec<ConflictRecord>), DbError> {
        check_len(entries.len() as u64, 64, "db_artifact::retained_state_mutations")?;
        let mut touched = db_state::TouchedSet::new();
        let mut conflicts = Vec::new();
        for (path, _) in entries {
            if let Some(previous_writer) = written.get(path).or_else(|| self.last_writer.get(path)) {
                if previous_writer != mutation_id && !dependencies.contains(previous_writer) {
                    conflicts.push(ConflictRecord { command_id: mutation_id.clone(), conflicting_with: previous_writer.clone(), path: path.clone() });
                }
            }
            touched.record(db_state::TouchedRegion::write(path.clone()));
            written.insert(path.clone(), mutation_id.clone());
        }
        Ok((touched, conflicts))
    }

    /// ✍️ Applies one planned envelope's entries ([`Self::plan_entries`]): every value, already encoded, set at
    /// its path, every `None` a deletion, and `mutation_id` recorded as each path's last writer.
    async fn apply_entries(&mut self, mutation_id: &protocol::MutationId, entries: Vec<(String, Option<Vec<u8>>)>) -> Result<(), DbError> {
        while artifact_state_retirement_maintenance_step()? {}
        if entries.is_empty() {
            return Ok(());
        }
        let cancelled = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let mut control = db_state::StateCursorControl::new(cancelled, std::time::Instant::now() + std::time::Duration::from_secs(30), 65_536)?;
        let mut staged: [Option<db_state::StateEntry>; 64] = std::array::from_fn(|_| None);
        let mut retirements: [Option<ArtifactStateRetirementReservation>; 64] = [None; 64];
        for index in 0..entries.len() {
            let Some(reservation) = reserve_artifact_state_retirement() else {
                release_artifact_state_retirements(&mut retirements);
                return Err(DbError::Unavailable("artifact state retirement pressure refused admission".to_string()));
            };
            retirements[index] = Some(reservation);
        }
        let mut paths = Vec::with_capacity(entries.len());
        for (index, (path, value)) in entries.into_iter().enumerate() {
            if let Some(bytes) = value {
                match db_state::StateEntry::try_admit(&path, bytes, MAX_STATE_PAGE_VALUE_BYTES, &mut control).await {
                    Ok(entry) => staged[index] = Some(entry),
                    Err(rejected) => {
                        let error = format!("retained state admission failed: {}", rejected.error());
                        let error = if matches!(rejected.error(), DbError::Unavailable(_)) { DbError::Unavailable(error) } else { DbError::InvalidArgument(error) };
                        let retirement = retirements[index].take().ok_or_else(|| DbError::Internal("retained state refusal lost retirement preflight".to_string()))?;
                        release_artifact_state_retirements(&mut retirements);
                        install_reserved_artifact_state_owner(ArtifactStateRetirementCursor::rejected(retirement, rejected, staged));
                        while artifact_state_retirement_maintenance_step()? {}
                        return Err(error);
                    }
                }
            }
            paths.push(path);
        }
        for (index, path) in paths.into_iter().enumerate() {
            let retirement = retirements[index].take().ok_or_else(|| DbError::Internal("retained state staging lost retirement admission".to_string()))?;
            match staged[index].take() {
                Some(entry) => {
                    let replaced = match self.values.insert(entry) {
                        Ok(replaced) => replaced,
                        Err(rejected) => {
                            staged[index] = Some(rejected);
                            release_artifact_state_retirements(&mut retirements);
                            install_reserved_artifact_state_owner(ArtifactStateRetirementCursor::staged(retirement, staged));
                            return Err(DbError::LimitExceeded("retained state entries"));
                        }
                    };
                    match replaced {
                        Some(replaced) => install_reserved_artifact_state_owner(ArtifactStateRetirementCursor::entry(retirement, replaced)),
                        None => release_artifact_state_retirement(&mut Some(retirement)),
                    }
                }
                None => match self.values.remove(&path) {
                    Some(removed) => install_reserved_artifact_state_owner(ArtifactStateRetirementCursor::entry(retirement, removed)),
                    None => release_artifact_state_retirement(&mut Some(retirement)),
                },
            }
            self.last_writer = self.last_writer.insert(path, mutation_id.clone());
        }
        while artifact_state_retirement_maintenance_step()? {}
        Ok(())
    }
}
//#endregion 🔖️State

//#region 🔖️Engine
/// ⚙️ Construction-time configuration for one `ArtifactEngine`: `db_engine` sets `limits` and
/// `preview_ttl_ms` and spreads `..Default::default()` for the rest.
pub struct ArtifactEngineConfig {
    pub limits: DbLimits,
    /// 🔐️ The real authz/dedupe/DoS-budget gate `submit` admits every not-yet-committed
    /// envelope through and records its committed ones in — see `db_security::SecurityGate::admit_commands`
    /// and `record_committed`. Keyed per-envelope by a `Principal`
    /// synthesized from that envelope's own `actor` (a permissive `"member"` role, `"default"`
    /// tenant) — `SubmitOptions` stays durability-only (see its doc) so this crate's dedupe/authz
    /// story does not require a caller to separately authenticate every submit call.
    pub security: db_security::SecurityGate,
    // 🔀️ dedyn-emit-runtime, O1/R11(c): every real call site (this crate's own `default()`,
    // `db_engine::document_engine_config`'s `other_defaults.emit` spread) constructs `NullEmit` and
    // nothing else — the field is stored but never actually called (`grep '.emit(' this crate: zero
    // hits). Unlike `db_security::SecurityGate` (which genuinely needs `E: Emit` generic so its own
    // tests can inject a `RecordingEmit`), there is no second implementor anywhere in this crate's
    // call graph, so O1 takes the "exactly one impl" branch: concrete `NullEmit`, no `dyn`, no
    // generic param added to this config type.
    pub emit: Arc<NullEmit>,
    pub preview_ttl_ms: u64,
    /// 🧬️ Projection factory: `submit`'s project step registers a fresh
    /// `db_projection::ProjectionEngine` from this on every call it needs one (see `🔖️Engine`'s doc
    /// for why a factory rather than a stored, already-built engine — `db_projection::
    /// ProjectionEngine::new`'s borrowed-`IndexStorage` + owned-`Vec<E>` shape does not
    /// semio_compose_rs with `ArtifactEngine` owning its storage as `Arc<dyn DbStorage>` without
    /// becoming self-referential). Defaults to no projections registered — `db_projection::
    /// NoProjections` (dedyn-fw-os-guestruntime, O1/R1: no first-party `dyn ErasedProjection`
    /// trait object) is uninhabited, so this factory can never actually return anything today; not
    /// one call site repo-wide overrides it with anything else. The day a real caller wants to
    /// register a projection here, it swaps `NoProjections` for its own closed `ErasedProjection`
    /// enum (R11) — this field's own `dyn Fn` closure stays (`dyn Fn` is R1-legal, a std trait).
    pub projections: Arc<dyn Fn() -> Vec<db_projection::NoProjections> + Send + Sync>,
}

impl Default for ArtifactEngineConfig {
    fn default() -> Self {
        let limits = DbLimits::default();
        let policy = db_security::RoleBasedPolicy::new().with_grant(db_security::Grant::allow("member", &["**"], &[db_security::Action::Read, db_security::Action::Write]));
        ArtifactEngineConfig {
            preview_ttl_ms: limits.max_preview_ttl_ms,
            limits,
            security: db_security::SecurityGate::new(policy, db_security::ReplayGuard::new(60_000, 4_096), db_security::BudgetRegistry::new(100_000, 100_000), Arc::new(NullEmit)),
            emit: Arc::new(NullEmit),
            projections: Arc::new(Vec::new),
        }
    }
}

/// 🎭️ The document authority's real, synchronous pipeline: one open document's WAL,
/// materialized state, causal dependency bookkeeping, previews and index backlog — everything
/// `ArtifactAuthority` (the `db_actor`-mailbox wrapper below) drives in finite process-pool turns.
/// The engine is moved only between serialized turns; callers can also use it directly wherever a
/// mailbox is unnecessary (for example this crate's own tests).
pub struct ArtifactEngine {
    document: ArtifactId,
    protocol_document: protocol::ArtifactId,
    storage: Arc<db_storage::DbBackend>,
    wal: db_wal::ArtifactWal,
    state: DocumentState,
    applied: HashMap<String, protocol::MutationEnvelope>,
    applied_receipts: HashMap<String, CommandReceipt>,
    applied_receipt_order: VecDeque<String>,
    durable_group_receipts: HashMap<String, store::durable_group::DurableOwnedGroupJournalReceiptV1>,
    durable_group_edit_ids: HashSet<String>,
    recent_targets: HashMap<String, Vec<String>>,
    actor_seq: HashMap<String, u64>,
    frontier: Frontier,
    head_edit_id: Option<protocol::MutationId>,
    previews: db_preview::PreviewStore,
    recent_touches: VecDeque<db_conflict::CommandTouch>,
    live_queries: HashMap<u64, db_query::LiveQuery>,
    next_live_query_id: u64,
    index_backlog: ArtifactIndexBacklog,
    config: ArtifactEngineConfig,
}

/// 🗂️ Index entries of commits that are durable in the WAL but not yet written as index runs.
/// A commit appends to it; after the commit's receipt was sent the runner writes every full run
/// (`db_index::RUN_ENTRIES_MAX` entries) through the kinds' owned runs — no listing, level folds
/// bounded per append — so the four index kinds cost one run write per 64 entries and no Ack waits
/// for index I/O. The WAL stays the source of truth: nothing here is durable, and opening a document
/// refills the backlog from the WAL suffix past what each kind's newest run already records.
#[derive(Default)]
struct ArtifactIndexBacklog {
    commands: VecDeque<(u64, db_index::RecordLocation)>,
    inverses: VecDeque<(u64, db_index::RecordLocation)>,
    actor_seqs: VecDeque<(ActorId, u64, u64)>,
    frontiers: VecDeque<Frontier>,
    runs: Option<ArtifactIndexRuns>,
}

/// 🗂️ The four kinds' owned runs, listed once on the backlog's first write and kept by its appends; dropped after
/// a failed write, so the next write lists again what storage really holds.
struct ArtifactIndexRuns {
    commands: db_index::OwnedRuns,
    inverses: db_index::OwnedRuns,
    actor_seqs: db_index::OwnedRuns,
    frontiers: db_index::OwnedRuns,
}

/// 🧾️ How far each index kind of one document already records (its newest run's highest
/// command or commit seq): the replay on open re-queues exactly what lies beyond.
#[derive(Clone, Copy, Default)]
struct ArtifactIndexWatermarks {
    commands: u64,
    inverses: u64,
    actor_seqs: u64,
    frontiers: u64,
}

/// 🛑️ The most entries one index kind may keep waiting for a run write: a `submit` that finds more writes
/// them first, and refuses transiently — before any WAL write — while index storage keeps failing.
const INDEX_BACKLOG_ENTRIES_MAX: usize = 64 * db_index::RUN_ENTRIES_MAX;

/// 🧾️ How many batch receipts the engine keeps for a whole-batch resend to be answered with its original
/// receipt; an older resend is answered by the per-envelope dedupe with the current frontier.
const APPLIED_RECEIPTS_MAX: usize = 1_024;

impl ArtifactIndexBacklog {
    async fn watermarks(storage: &impl db_storage::IndexStorage, document: &ArtifactId) -> Result<ArtifactIndexWatermarks, DbError> {
        Ok(ArtifactIndexWatermarks {
            commands: db_index::CommandIndex::new(storage, document.clone()).await.indexed_through().await?,
            inverses: db_index::InverseIndex::new(storage, document.clone()).await.indexed_through().await?,
            actor_seqs: db_index::ActorSeqIndex::new(storage, document.clone()).await.indexed_through().await?,
            frontiers: db_index::FrontierIndex::new(storage, document.clone()).await.indexed_through().await?,
        })
    }

    fn queue_command(&mut self, watermarks: &ArtifactIndexWatermarks, seq: u64, location: db_index::RecordLocation, actor: ActorId, actor_seq: u64) {
        if seq > watermarks.commands {
            self.commands.push_back((seq, location));
        }
        if seq > watermarks.inverses {
            self.inverses.push_back((seq, location));
        }
        if seq > watermarks.actor_seqs {
            self.actor_seqs.push_back((actor, actor_seq, seq));
        }
    }

    fn queue_frontier(&mut self, watermarks: &ArtifactIndexWatermarks, frontier: &Frontier) {
        if frontier.commit_seq > watermarks.frontiers {
            self.frontiers.push_back(frontier.clone());
        }
    }

    fn pending(&self) -> usize {
        self.commands.len().max(self.inverses.len()).max(self.actor_seqs.len()).max(self.frontiers.len())
    }

    /// 🚚️ Writes this backlog's runs: every full one, or everything including a partial tail
    /// (`drain`) before WAL history may be deleted. Each written run leaves the backlog at once, so a
    /// failed write resumes exactly where it stopped, and forgets the owned runs, which the next write
    /// lists again.
    async fn flush(&mut self, storage: &impl db_storage::IndexStorage, document: &ArtifactId, drain: bool) -> Result<(), DbError> {
        let written = self.flush_owned(storage, document, drain).await;
        if written.is_err() {
            self.runs = None;
        }
        written
    }

    async fn flush_owned(&mut self, storage: &impl db_storage::IndexStorage, document: &ArtifactId, drain: bool) -> Result<(), DbError> {
        let full = db_index::RUN_ENTRIES_MAX;
        let take = |len: usize| if len >= full { full } else if drain { len } else { 0 };
        if [self.commands.len(), self.inverses.len(), self.actor_seqs.len(), self.frontiers.len()].into_iter().all(|len| take(len) == 0) {
            return Ok(());
        }
        let commands = db_index::CommandIndex::new(storage, document.clone()).await;
        let inverses = db_index::InverseIndex::new(storage, document.clone()).await;
        let actor_seqs = db_index::ActorSeqIndex::new(storage, document.clone()).await;
        let frontiers = db_index::FrontierIndex::new(storage, document.clone()).await;
        let runs = match self.runs.as_mut() {
            Some(runs) => runs,
            None => self.runs.insert(ArtifactIndexRuns { commands: commands.owned_runs().await?, inverses: inverses.owned_runs().await?, actor_seqs: actor_seqs.owned_runs().await?, frontiers: frontiers.owned_runs().await? }),
        };
        while take(self.commands.len()) > 0 {
            let count = take(self.commands.len());
            let run: Vec<_> = self.commands.iter().take(count).copied().collect();
            commands.record_owned_run(&mut runs.commands, &run).await?;
            self.commands.drain(..count);
        }
        while take(self.inverses.len()) > 0 {
            let count = take(self.inverses.len());
            let run: Vec<_> = self.inverses.iter().take(count).copied().collect();
            inverses.record_owned_run(&mut runs.inverses, &run).await?;
            self.inverses.drain(..count);
        }
        while take(self.actor_seqs.len()) > 0 {
            let count = take(self.actor_seqs.len());
            let run: Vec<_> = self.actor_seqs.iter().take(count).cloned().collect();
            actor_seqs.record_owned_run(&mut runs.actor_seqs, &run).await?;
            self.actor_seqs.drain(..count);
        }
        while take(self.frontiers.len()) > 0 {
            let count = take(self.frontiers.len());
            let run: Vec<_> = self.frontiers.iter().take(count).cloned().collect();
            frontiers.record_owned_run(&mut runs.frontiers, &run).await?;
            self.frontiers.drain(..count);
        }
        Ok(())
    }
}

/// 🧭️ Consistency resolution of a mounted document: its current frontier is the engine's
/// own, and a historical frontier is found among the not-yet-written backlog before the index.
struct ArtifactConsistencyResolver<'a, S: db_storage::IndexStorage> {
    current: Frontier,
    pending: &'a VecDeque<Frontier>,
    commits: db_index::CommitIndex<'a, S>,
    frontiers: db_index::FrontierIndex<'a, S>,
}

impl<S: db_storage::IndexStorage> db_query::ConsistencyResolver for ArtifactConsistencyResolver<'_, S> {
    async fn current_frontier(&self) -> Result<Frontier, DbError> {
        Ok(self.current.clone())
    }

    async fn frontier_for_commit(&self, commit_id: &str) -> Result<Frontier, DbError> {
        let command_seq = self.commits.lookup(commit_id).await?.ok_or_else(|| DbError::NotFound(format!("unknown commit id {commit_id:?}")))?;
        if let Some(frontier) = self.pending.iter().find(|frontier| frontier.commit_seq == command_seq) {
            return Ok(frontier.clone());
        }
        self.frontiers.lookup(command_seq).await?.ok_or_else(|| DbError::NotFound(format!("no frontier recorded at command_seq {command_seq}")))
    }
}

/// 🧯️ Engine construction rejection that keeps every acquired WAL owner until bounded terminal close.
#[must_use = "engine construction rejection must reach terminal retained cleanup"]
pub enum ArtifactEngineOpenRejected {
    BeforeWal(DbError),
    WalOpen(db_wal::ArtifactWalOpenRejected),
    RetainedWal { cause: DbError, close_error: Option<DbError>, wal: db_wal::ArtifactWal },
}

impl ArtifactEngineOpenRejected {
    fn retained_wal(cause: DbError, wal: db_wal::ArtifactWal) -> Self {
        Self::RetainedWal { cause, close_error: None, wal }
    }

    fn retained_wal_after_cleanup_error(cause: DbError, close_error: DbError, wal: db_wal::ArtifactWal) -> Self {
        Self::RetainedWal { cause, close_error: Some(close_error), wal }
    }

    pub fn error(&self) -> &DbError {
        match self {
            Self::BeforeWal(cause) => cause,
            Self::WalOpen(rejected) => rejected.error(),
            Self::RetainedWal { cause, .. } => cause,
        }
    }

    pub fn cleanup_error(&self) -> Option<&DbError> {
        match self {
            Self::WalOpen(rejected) => rejected.release_error(),
            Self::RetainedWal { close_error, .. } => close_error.as_ref(),
            Self::BeforeWal(_) => None,
        }
    }

    pub fn has_retained_writer(&self) -> bool {
        match self {
            Self::BeforeWal(_) => false,
            Self::WalOpen(rejected) => rejected.has_release_owner(),
            Self::RetainedWal { .. } => true,
        }
    }

    pub async fn retry_close(self) -> Result<DbError, ArtifactEngineOpenRejected> {
        match self {
            Self::BeforeWal(cause) => Ok(cause),
            Self::WalOpen(rejected) => rejected.retry_close().await.map_err(Self::WalOpen),
            Self::RetainedWal { cause, close_error: _, mut wal } => match wal.close().await {
                Ok(()) => Ok(cause),
                Err(error) => Err(Self::RetainedWal { cause, close_error: Some(error), wal }),
            },
        }
    }
}

impl From<DbError> for ArtifactEngineOpenRejected {
    fn from(error: DbError) -> Self {
        Self::BeforeWal(error)
    }
}

impl From<db_wal::ArtifactWalOpenRejected> for ArtifactEngineOpenRejected {
    fn from(rejected: db_wal::ArtifactWalOpenRejected) -> Self {
        Self::WalOpen(rejected)
    }
}

impl std::fmt::Debug for ArtifactEngineOpenRejected {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.debug_struct("ArtifactEngineOpenRejected").field("cause", self.error()).field("cleanup_error", &self.cleanup_error()).field("has_retained_writer", &self.has_retained_writer()).finish()
    }
}

const MAX_RECENT_TOUCHES: usize = 256;

impl ArtifactEngine {
    /// 🔕️ One close step: progress wakes the caller's waker, a pending writer release parks it
    /// in the release signal until the backend's terminal notification.
    fn poll_close(&mut self, context: &mut std::task::Context<'_>) -> std::task::Poll<Result<(), DbError>> {
        if self.wal.poll_close(context)?.is_pending() {
            return std::task::Poll::Pending;
        }
        if self.state.values.close_step()? {
            context.waker().wake_by_ref();
            return std::task::Poll::Pending;
        }
        std::task::Poll::Ready(Ok(()))
    }

    #[cfg(test)]
    pub(crate) async fn close(&mut self) -> Result<(), DbError> {
        std::future::poll_fn(|context| self.poll_close(context)).await
    }

    fn close_flush_pending(&self) -> bool {
        self.wal.has_pending()
    }

    /// 🅿️ The engine rests between turns: its WAL parks the document's writer (unless a group commit still waits), so a
    /// backend with more open documents than writers lends it to whichever document writes next.
    fn park_writer(&self) {
        self.wal.park_writer();
    }

    async fn close_flush(&mut self) -> Result<(), DbError> {
        let wal_facet = self.storage.wal().await;
        self.wal.close_flush(&wal_facet).await
    }

    /// 🌱️ Retained constructor used by the document authority. Every storage wait remains
    /// represented by this future so a pool worker only polls it once before yielding.
    pub async fn create_retained(document: protocol::ArtifactId, storage: Arc<db_storage::DbBackend>, config: ArtifactEngineConfig, now_ms: u64) -> Result<ArtifactEngine, ArtifactEngineOpenRejected> {
        let core_id = to_core_document_id(&document).await;
        let wal = db_wal::ArtifactWal::create(&storage.wal().await, core_id.clone(), db_wal::GroupCommitPolicy::default(), now_ms).await.map_err(ArtifactEngineOpenRejected::WalOpen)?;
        Ok(ArtifactEngine::assemble(document, core_id, storage, wal, config).await)
    }

    /// 🌱️ Creates a brand-new document: a genesis WAL (segment 0) and an empty state.
    /// Errors `AlreadyExists` if `document` already has WAL segments in `storage`.
    /// Process/test entry-point convenience; live document authorities use `create_retained`.
    #[cfg(not(target_arch = "wasm32"))]
    pub(crate) fn create(document: protocol::ArtifactId, storage: Arc<db_storage::DbBackend>, config: ArtifactEngineConfig, now_ms: u64) -> Result<ArtifactEngine, ArtifactEngineOpenRejected> {
        db_actor::block_on(Self::create_retained(document, storage, config, now_ms))
    }

    /// 🚑️ Retained materialization as initial ⊕ snapshot ⊕ WAL suffix.
    pub async fn open_retained(document: protocol::ArtifactId, storage: Arc<db_storage::DbBackend>, config: ArtifactEngineConfig, now_ms: u64) -> Result<(ArtifactEngine, MaterializeReport), ArtifactEngineOpenRejected> {
        let core_id = to_core_document_id(&document).await;
        let mut report = MaterializeReport::default();

        let mut state = DocumentState::new();
        let mut applied_head_seq = 0u64;
        let snapshot_facet = storage.snapshot().await;
        let snapshot_manager = db_snapshot::SnapshotManager::new(&snapshot_facet).await;
        if let Some((generation, descriptor)) = snapshot_manager.load_latest(&core_id).await? {
            report.from_snapshot = true;
            report.snapshot_generation = Some(generation);
            let cancelled = Arc::new(std::sync::atomic::AtomicBool::new(false));
            let control = db_snapshot::SnapshotCursorControl::new(cancelled, std::time::Instant::now() + std::time::Duration::from_secs(30), 65_536)?;
            let mut snapshot_cursor = snapshot_manager.chain_cursor(&core_id, generation, control);
            for hash in &descriptor.roots {
                let mut page_bytes = snapshot_cursor.read_page(*hash).await?;
                let cancelled = Arc::new(std::sync::atomic::AtomicBool::new(false));
                let mut decoder = StatePageDecodeCursor::new(&page_bytes, cancelled, std::time::Instant::now() + std::time::Duration::from_secs(30), 65_536)?;
                while let Some(entry) = decoder.next().await? {
                    let replaced = match state.values.insert(entry) {
                        Ok(replaced) => replaced,
                        Err(mut rejected) => {
                            let _ = rejected.close_step()?;
                            return Err(ArtifactEngineOpenRejected::BeforeWal(DbError::LimitExceeded("retained state entries")));
                        }
                    };
                    if let Some(mut replaced) = replaced {
                        let _ = replaced.close_step()?;
                        drop(replaced);
                    }
                }
                let _ = decoder.close_step()?;
                drop(decoder);
                let _ = page_bytes.close_step()?;
                drop(page_bytes);
            }
            let _ = snapshot_cursor.close_step()?;
            applied_head_seq = descriptor.head_seq;
        }
        drop(snapshot_manager);
        drop(snapshot_facet);

        let (wal, wal_recovery) = db_wal::ArtifactWal::open(&storage.wal().await, core_id.clone(), db_wal::GroupCommitPolicy::default(), now_ms).await.map_err(ArtifactEngineOpenRejected::WalOpen)?;
        report.torn_tail_bytes = wal_recovery.torn_tail_bytes;
        let mut engine = ArtifactEngine::assemble(document, core_id.clone(), storage.clone(), wal, config).await;
        engine.state = state;
        engine.frontier.head_seq = applied_head_seq;

        let replay = async {
            let wal_facet = storage.wal().await;
            let replay_cancelled = Arc::new(std::sync::atomic::AtomicBool::new(false));
            let replay_control = db_wal::WalCursorControl::new(replay_cancelled, std::time::Instant::now() + std::time::Duration::from_secs(30), 1_000_000)?;
            let watermarks = ArtifactIndexBacklog::watermarks(&storage.index().await, &core_id).await?;
            let mut records = db_wal::replay_committed_document(&wal_facet, &core_id, replay_control).await?;
            let mut decode_control = db_wal::WalCursorControl::stall_bounded(Arc::new(std::sync::atomic::AtomicBool::new(false)), db_wal::WAL_REPLAY_STEP_STALL_BOUND, db_wal::WAL_REPLAY_STEP_FUEL)?;
            let mut turn = db_wal::WalTurn::start();
            let mut batch_ids: HashSet<String> = HashSet::new();
            let mut seen: u64 = 0;
            let mut replay_frontier = Frontier::genesis(core_id.clone());
            let mut replay_head_edit_id = None;
            let mut replay_projected = false;
            let result = async {
                loop {
                    records.renew_step()?;
                    decode_control.renew_step()?;
                    let mut transaction = match records.next_transaction_step().await? {
                        db_wal::WalCommittedStep::Transaction(transaction) => transaction,
                        db_wal::WalCommittedStep::Yield => {
                            turn.step().await;
                            continue;
                        }
                        db_wal::WalCommittedStep::Done => break,
                    };
                    let transaction_id = transaction.transaction_id();
                    let segment_index = transaction.segment_index();
                    batch_ids.clear();
                    let mut frontier_seen = false;
                    let mut body_records = 0usize;
                    let mut durable_group = None;
                    loop {
                        let record = match transaction.next_record_step()? {
                            db_wal::WalCommittedRecordStep::Record(record) => record,
                            db_wal::WalCommittedRecordStep::Yield => {
                                turn.step().await;
                                continue;
                            }
                            db_wal::WalCommittedRecordStep::Done => break,
                        };
                        if frontier_seen {
                            return Err(DbError::Corrupt("artifact committed frontier is not terminal".to_string()));
                        }
                        body_records = body_records.checked_add(1).ok_or_else(|| DbError::LimitExceeded("artifact committed body records"))?;
                        if durable_group.is_some() {
                            return Err(DbError::Corrupt("durable group decision must be the sole committed transaction body".to_string()));
                        }
                        match record {
                            db_wal::WalRecord::Command(bytes) => {
                                let envelope = db_sync::decode_wal_command(bytes, &mut decode_control)?;
                                if envelope.document_id.0 != core_id.0 {
                                    return Err(DbError::Corrupt("artifact envelope document differs".to_string()));
                                }
                                replay_head_edit_id = Some(envelope.mutation_id.clone());
                                seen += 1;
                                batch_ids.insert(envelope.mutation_id.0.clone());
                                let actor = to_core_actor_id(&envelope.actor).await;
                                if seen <= applied_head_seq {
                                    *engine.actor_seq.entry(envelope.actor.0.clone()).or_insert(0) += 1;
                                    engine.applied.insert(envelope.mutation_id.0.clone(), envelope.clone());
                                } else {
                                    let touched = match engine.plan_one(&envelope, &batch_ids, &mut HashMap::new()).await? {
                                        Some(plan) => {
                                            engine.commit_one(&envelope, plan.entries).await?;
                                            plan.touched
                                        }
                                        None => db_state::TouchedSet::new(),
                                    };
                                    let touch = command_touch(&envelope, &touched);
                                    engine.remember_target(&envelope);
                                    remember_recent_touch(&mut engine.recent_touches, touch);
                                    report.commands_replayed += 1;
                                }
                                let actor_seq = *engine.actor_seq.get(&envelope.actor.0).unwrap_or(&0);
                                engine.index_backlog.queue_command(&watermarks, seen, db_index::RecordLocation { segment: segment_index, offset: seen, len: 1 }, actor, actor_seq);
                            }
                            db_wal::WalRecord::Frontier(frontier) => {
                                if frontier.document != core_id {
                                    return Err(DbError::Corrupt("artifact frontier document differs".to_string()));
                                }
                                engine.index_backlog.queue_frontier(&watermarks, frontier);
                                frontier_seen = true;
                                replay_frontier = frontier.clone();
                                replay_projected = true;
                            }
                            db_wal::WalRecord::Event(bytes) => {
                                if body_records != 1 {
                                    return Err(DbError::Corrupt("durable group decision must be the sole committed transaction body".to_string()));
                                }
                                let mut canonical_pack = Vec::with_capacity(bytes.len());
                                for fragment in bytes.fragments() {
                                    canonical_pack.extend_from_slice(fragment);
                                }
                                let record = store::durable_group::DurableOwnedGroupJournalRecordV1::admit_canonical(canonical_pack).map_err(|error| DbError::Corrupt(format!("committed durable group decision is invalid: {error}")))?;
                                if record.document().artifact_id != core_id.0 {
                                    return Err(DbError::Corrupt("committed durable group decision targets a different replay document".to_string()));
                                }
                                durable_group = Some(record);
                            }
                            _ => {}
                        }
                        while transaction.close_record_step()? {
                            turn.step().await;
                        }
                        turn.step().await;
                    }
                    if !batch_ids.is_empty() && !frontier_seen {
                        return Err(DbError::Corrupt("artifact committed commands have no frontier".to_string()));
                    }
                    if let Some(record) = durable_group {
                        if body_records != 1 {
                            return Err(DbError::Corrupt("durable group decision must be the sole committed transaction body".to_string()));
                        }
                        seen = seen.checked_add(1).ok_or_else(|| DbError::LimitExceeded("artifact replay head sequence"))?;
                        let receipt = store::durable_group::DurableOwnedGroupJournalReceiptV1 { anchor_sha256: record.anchor_sha256().to_string(), decision_sha256: record.decision_sha256().to_string(), transaction_id, segment_index };
                        let duplicate = engine.durable_group_receipts.insert(receipt.decision_sha256.clone(), receipt).is_some();
                        engine.durable_group_edit_ids.insert(record.parent_edit_id().to_string());
                        if !duplicate {
                            replay_frontier = Frontier {
                                document: core_id.clone(),
                                head_seq: replay_frontier.head_seq.checked_add(1).ok_or_else(|| DbError::LimitExceeded("durable group replay head sequence"))?,
                                commit_seq: replay_frontier.commit_seq.checked_add(1).ok_or_else(|| DbError::LimitExceeded("durable group replay commit sequence"))?,
                                chain_hash: record.parent_post_revision(),
                                epoch: replay_frontier.epoch,
                            };
                            replay_head_edit_id = Some(protocol::MutationId(record.parent_edit_id().to_string()));
                            remember_recent_touch(&mut engine.recent_touches, durable_group_touch(record.parent_edit_id()));
                            replay_projected = true;
                        }
                    }
                    transaction.finish()?;
                }
                if replay_projected {
                    engine.frontier = replay_frontier;
                    engine.head_edit_id = replay_head_edit_id;
                }
                Ok::<(), DbError>(())
            }
            .await;
            let closed = async {
                while records.close_owner_step()? {
                    semio_framework_async::yield_once().await;
                }
                Ok::<(), DbError>(())
            }
            .await;
            drop(records);
            drop(wal_facet);
            result.and(closed)
        }
        .await;
        if let Err(error) = replay {
            let state_close = async {
                while engine.state.values.close_step()? {
                    semio_framework_async::yield_once().await;
                }
                Ok::<(), DbError>(())
            }
            .await;
            let ArtifactEngine { wal, .. } = engine;
            if let Err(close_error) = state_close {
                return Err(ArtifactEngineOpenRejected::retained_wal_after_cleanup_error(error, close_error, wal));
            }
            return Err(ArtifactEngineOpenRejected::retained_wal(error, wal));
        }
        Ok((engine, report))
    }

    /// 🚑️ Process/test entry-point convenience; live authorities use `open_retained`.
    #[cfg(not(target_arch = "wasm32"))]
    pub(crate) fn open(document: protocol::ArtifactId, storage: &Arc<db_storage::DbBackend>, config: ArtifactEngineConfig, now_ms: u64) -> Result<(ArtifactEngine, MaterializeReport), ArtifactEngineOpenRejected> {
        db_actor::block_on(Self::open_retained(document, storage.clone(), config, now_ms))
    }

    async fn assemble(protocol_document: protocol::ArtifactId, core_id: ArtifactId, storage: Arc<db_storage::DbBackend>, wal: db_wal::ArtifactWal, config: ArtifactEngineConfig) -> ArtifactEngine {
        let preview_budgets = db_preview::PreviewBudgets { default_ttl_ms: config.preview_ttl_ms, max_ttl_ms: config.preview_ttl_ms, ..db_preview::PreviewBudgets::default() };
        ArtifactEngine {
            document: core_id.clone(),
            protocol_document,
            storage,
            wal,
            state: DocumentState::new(),
            applied: HashMap::new(),
            applied_receipts: HashMap::new(),
            applied_receipt_order: VecDeque::new(),
            durable_group_receipts: HashMap::new(),
            durable_group_edit_ids: HashSet::new(),
            recent_targets: HashMap::new(),
            actor_seq: HashMap::new(),
            frontier: Frontier::genesis(core_id.clone()),
            head_edit_id: None,
            previews: db_preview::PreviewStore::new(core_id, preview_budgets),
            recent_touches: VecDeque::new(),
            live_queries: HashMap::new(),
            next_live_query_id: 0,
            index_backlog: ArtifactIndexBacklog::default(),
            config,
        }
    }

    /// 🧭️ Plans `envelope` against this engine and the batch so far without applying anything: `None` when it is
    /// already applied (the per-envelope half of the dedupe law), else its decoded entries — values encoded as the state
    /// stores them — with the regions it touches and the conflicts it meets. Refuses an envelope whose dependency is
    /// neither applied, nor earlier in `batch_ids`, nor folded by a durable group decision.
    async fn plan_one(&self, envelope: &protocol::MutationEnvelope, batch_ids: &HashSet<String>, written: &mut HashMap<String, protocol::MutationId>) -> Result<Option<PlannedEntries>, DbError> {
        if self.applied.contains_key(&envelope.mutation_id.0) {
            return Ok(None);
        }
        for dependency in &envelope.dependencies {
            if !self.applied.contains_key(&dependency.0) && !batch_ids.contains(&dependency.0) && !self.names_durable_group_operation(&dependency.0) {
                return Err(DbError::InvalidArgument(format!("operation {} depends on unseen operation {}", envelope.mutation_id.0, dependency.0)));
            }
        }
        let entries = diff_entries(&envelope.diff).await?;
        check_len(entries.len() as u64, self.config.limits.max_batch_commands as u64, "db_artifact::diff_entries")?;
        let (touched, conflicts) = self.state.plan_entries(&envelope.mutation_id, &envelope.dependencies, &entries, written)?;
        let entries = entries.into_iter().map(|(path, value)| (path, value.map(|value| store::pack_rt::encode_wire_value(&value)))).collect();
        Ok(Some(PlannedEntries { entries, touched, conflicts }))
    }

    /// ✍️ Applies one planned envelope to the document state and records it as applied.
    async fn commit_one(&mut self, envelope: &protocol::MutationEnvelope, entries: Vec<(String, Option<Vec<u8>>)>) -> Result<(), DbError> {
        self.state.apply_entries(&envelope.mutation_id, entries).await?;
        self.applied.insert(envelope.mutation_id.0.clone(), envelope.clone());
        *self.actor_seq.entry(envelope.actor.0.clone()).or_insert(0) += 1;
        Ok(())
    }

    /// 🪪️ The event log's twin of `protocol::fold_history`'s admission, so the log never holds a history transition every
    /// replica refuses: refused before the WAL, whatever the merge policy, with one typed message.
    /// - A payload that does not decode: [`MALFORMED_HISTORY_TRANSITION_CODE`].
    /// - An undo belongs to its author: a `Revert` or `Reinstate` naming an operation this document's log (or an envelope of
    ///   the same batch) records under another actor: [`FOREIGN_HISTORY_TRANSITION_CODE`]. An operation the log does not
    ///   know belongs to anyone (the replicas' fold says the same).
    /// - A `Supersede` has no ownership rule: editing history is non-destructive and reversible, and write permission is the
    ///   security gate's. It must depend on exactly its targets ([`MALFORMED_HISTORY_TRANSITION_CODE`]), and every target
    ///   must be committed, `earlier` in its batch, or folded by a durable group decision ([`UNKNOWN_SUPERSEDE_TARGET_CODE`]).
    ///
    /// 📋️ `.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️09/☀️30/NON-DESTRUCTIVE-HISTORY-EDITING/📋️design.md` §2, §9.1.
    fn history_transition_refusal(&self, envelope: &protocol::MutationEnvelope, batch: &[protocol::MutationEnvelope], earlier: &HashSet<String>) -> Option<protocol::MutationMessage> {
        let transition = match protocol::history_transition_from_envelope(envelope) {
            Ok(Some(transition)) => transition,
            Ok(None) => return None,
            Err(_) => return Some(protocol::MutationMessage::error(MALFORMED_HISTORY_TRANSITION_CODE, MALFORMED_HISTORY_TRANSITION_MESSAGE)),
        };
        match transition {
            protocol::HistoryTransition::Revert { mutation_ids } | protocol::HistoryTransition::Reinstate { mutation_ids } => {
                let author = |id: &protocol::MutationId| self.applied.get(&id.0).map(|applied| &applied.actor).or_else(|| batch.iter().find(|earlier| &earlier.mutation_id == id).map(|earlier| &earlier.actor));
                mutation_ids.iter().any(|id| author(id).is_some_and(|actor| actor != &envelope.actor)).then(|| protocol::MutationMessage::error(FOREIGN_HISTORY_TRANSITION_CODE, FOREIGN_HISTORY_TRANSITION_MESSAGE))
            }
            protocol::HistoryTransition::Supersede(supersede) => {
                let targets = supersede.targets();
                if envelope.dependencies != targets {
                    return Some(protocol::MutationMessage::error(MALFORMED_HISTORY_TRANSITION_CODE, MALFORMED_HISTORY_TRANSITION_MESSAGE));
                }
                targets
                    .into_iter()
                    .find(|target| !self.applied.contains_key(&target.0) && !earlier.contains(&target.0) && !self.names_durable_group_operation(&target.0))
                    .map(|target| protocol::MutationMessage::error(UNKNOWN_SUPERSEDE_TARGET_CODE, UNKNOWN_SUPERSEDE_TARGET_MESSAGE).at([target.0]))
            }
            protocol::HistoryTransition::Commit(_) | protocol::HistoryTransition::Branch { .. } | protocol::HistoryTransition::Checkout { .. } | protocol::HistoryTransition::Repin { .. } => None,
        }
    }

    /// 👁️ Whether `dependency` names an operation a committed durable group decision folded: the
    /// decision's edit itself, or `<edit>#<position>`.
    fn names_durable_group_operation(&self, dependency: &str) -> bool {
        self.durable_group_edit_ids.contains(dependency) || dependency.rsplit_once('#').is_some_and(|(edit, position)| !position.is_empty() && position.bytes().all(|byte| byte.is_ascii_digit()) && self.durable_group_edit_ids.contains(edit))
    }

    /// 🎯️ Keeps `envelope`'s declared target while its touch is in the recent commit window, so a later
    /// concurrent write can be graded against it; targets that left the window are dropped with it.
    fn remember_target(&mut self, envelope: &protocol::MutationEnvelope) {
        if self.recent_targets.len() >= MAX_RECENT_TOUCHES {
            let window: HashSet<&str> = self.recent_touches.iter().map(|touch| touch.command_id.0.as_str()).collect();
            self.recent_targets.retain(|command, _| window.contains(command.as_str()));
        }
        self.recent_targets.insert(envelope.mutation_id.0.clone(), envelope.target.clone());
    }

    /// 🚦️ The full command pipeline: admit → dedupe → base-resolve/deps → authz → validate →
    /// conflict → execute → WAL append → durability → publish → project →
    /// preview-reconcile → live-query notify → receipt.
    // 🔒️ `batch` is taken by value deliberately, not just because the current body happens not to
    // move it: submitting a batch is the one place in this API where the caller's copy is
    // logically spent (it becomes part of durable history), matching `ArtifactMessage::Submit`'s
    // owned payload on the actor-mailbox side one level up. Keeping ownership here leaves room for
    // a future zero-copy WAL append that moves `batch.envelopes` directly into the write path.
    #[allow(clippy::needless_pass_by_value)]
    pub async fn submit(&mut self, batch: CommandBatch, options: SubmitOptions, now_ms: u64) -> Result<CommandReceipt, DbError> {
        // admit
        check_len(batch.envelopes.len() as u64, self.config.limits.max_batch_commands as u64, "db_artifact::batch_commands")?;
        for envelope in &batch.envelopes {
            if envelope.document_id != self.protocol_document {
                return Err(DbError::InvalidArgument(format!("envelope targets document {:?} but this actor owns {:?}", envelope.document_id, self.protocol_document)));
            }
        }
        let command_id = batch.envelopes.last().expect("CommandBatch::new guarantees at least one envelope").mutation_id.clone();

        for envelope in &batch.envelopes {
            if let Some(applied) = self.applied.get(&envelope.mutation_id.0) {
                if applied.diff != envelope.diff || applied.inverse != envelope.inverse || applied.dependencies != envelope.dependencies {
                    return Err(DbError::Conflict(format!("mutation id {} is already committed with different content", envelope.mutation_id.0)));
                }
            }
        }

        // dedupe (whole-batch, keyed by the batch's designated command_id)
        if let Some(cached) = self.applied_receipts.get(&command_id.0) {
            return Ok(cached.clone());
        }

        // index backlog bound: write what earlier commits queued before this one adds more; refuse
        // transiently while index storage fails, before the WAL holds anything of this batch
        if self.index_backlog.pending() > INDEX_BACKLOG_ENTRIES_MAX {
            if let Err(error) = self.maintain_index().await {
                return Err(DbError::Unavailable(format!("index backlog of {} entries cannot be written: {error}", self.index_backlog.pending())));
            }
        }

        let mut batch_ids: HashSet<String> = HashSet::new();
        let mut written: HashMap<String, protocol::MutationId> = HashMap::new();
        let mut planned: Vec<(&protocol::MutationEnvelope, PlannedEntries)> = Vec::new();
        let mut commands: Vec<Vec<u8>> = Vec::new();
        for envelope in &batch.envelopes {
            if batch_ids.contains(&envelope.mutation_id.0) {
                return Err(DbError::Conflict(format!("mutation id {} appears twice in one batch", envelope.mutation_id.0)));
            }
            if self.applied.contains_key(&envelope.mutation_id.0) {
                batch_ids.insert(envelope.mutation_id.0.clone());
                continue;
            }

            // authz: the `db_security::SecurityGate`, keyed by a permissive principal synthesized from the
            // envelope's own actor (see `ArtifactEngineConfig::security`'s doc). An already-committed
            // envelope (content-checked above) skipped it: it is an idempotent resend.
            let principal = db_security::Principal::new(envelope.actor.clone(), db_security::TenantId::from("default"), vec!["member".to_string()]);
            self.config.security.admit_commands(&principal, &db_security::TenantId::from("default"), &envelope.document_id, &envelope.diff.schema.0, &[(&envelope.actor, &envelope.mutation_id)], now_ms).await?;
            if let Some(refusal) = self.history_transition_refusal(envelope, &batch.envelopes, &batch_ids) {
                return Err(DbError::Rejected { policy: options.policy, worst: semio_framework_diagnostic::Severity::Error, messages: vec![refusal] });
            }

            // 🎯️ W5: `WalRecord::Command`'s bytes are `protocol::encode_envelope`'s binary record now
            // (M-C's "storage AND communication both binary") — `db_sync::replay_sync_state` reads
            // these same WAL records via `decode_command_envelope` (the same binary codec) to serve
            // semio_hub bootstrap/catch-up, so this crate's own write-and-read-back convention below must
            // agree with it byte-for-byte.
            let mut envelope_bytes = Vec::new();
            protocol::encode_envelope(envelope, &mut envelope_bytes);
            check_len(envelope_bytes.len() as u64, self.config.limits.max_command_bytes, "db_artifact::envelope_bytes")?;

            let plan = self.plan_one(envelope, &batch_ids, &mut written).await?;
            batch_ids.insert(envelope.mutation_id.0.clone());
            if let Some(plan) = plan {
                planned.push((envelope, plan));
                commands.push(envelope_bytes);
            }
        }

        if planned.is_empty() {
            // Every envelope in this (re-)submitted batch was already durable individually — a
            // full no-op commit, per-envelope half of the dedupe law (see `plan_one`'s doc).
            let receipt = CommandReceipt { command_id, frontier: self.frontier.clone(), durability: options.durability, conflicts: Vec::new(), state_hash: Some(self.state.content_hash().await?), messages: Vec::new() };
            self.remember_receipt(&receipt);
            return Ok(receipt);
        }

        // outcome step (contract §C9): union this batch's own `db_conflict::ConflictDetector`
        // findings (probed against recent commit history) into graded `protocol::MutationMessage`s,
        // then let `options.policy` decide before touching `self.recent_touches`/`self.outbox`/the
        // WAL at all — a rejected batch must leave every one of those untouched.
        let batch_touches: Vec<db_conflict::CommandTouch> = planned.iter().map(|(envelope, plan)| command_touch(envelope, &plan.touched)).collect();
        let mut messages: Vec<protocol::MutationMessage> = Vec::new();
        for (index, (envelope, _)) in planned.iter().enumerate() {
            for unseen in unseen_concurrent_writes(&self.recent_touches, &batch_touches[..index], &batch_touches[index], envelope) {
                let unseen_target = self.recent_targets.get(&unseen.command_id.0).map(Vec::as_slice).or_else(|| planned[..index].iter().find(|(earlier, _)| earlier.mutation_id == unseen.command_id).map(|(earlier, _)| earlier.target.as_slice())).unwrap_or(&[]);
                messages.extend(grade_concurrent_write(&batch_touches[index], &envelope.target, unseen, unseen_target).await);
            }
        }
        if let Some(worst) = protocol::worst_level(&messages) {
            if options.policy.rejects(worst) {
                return Err(DbError::Rejected { policy: options.policy, worst, messages });
            }
        }

        let head_seq = self.frontier.head_seq.checked_add(planned.len() as u64).ok_or(DbError::LimitExceeded("db_artifact::head_seq"))?;
        let mut records = db_wal::WalRecordBatch::new();
        let _ = records.push(db_wal::WalRecord::Frontier(Frontier { document: self.document.clone(), head_seq, commit_seq: self.frontier.commit_seq + 1, chain_hash: [0; 32], epoch: self.frontier.epoch }));
        self.wal.preflight_submit(&commands, &records)?;
        let _ = records.close_step()?;
        let wal_facet = self.storage.wal().await;
        self.wal.begin_write(&wal_facet).await?;
        drop(wal_facet);

        let mut touched_all = db_state::TouchedSet::new();
        let mut conflicts_all: Vec<ConflictRecord> = Vec::new();
        let mut applied_actor_seqs: Vec<u64> = Vec::with_capacity(planned.len());
        let mut newly_applied: Vec<(&protocol::MutationEnvelope, db_state::TouchedSet)> = Vec::with_capacity(planned.len());
        for (envelope, plan) in planned {
            self.commit_one(envelope, plan.entries).await?;
            applied_actor_seqs.push(*self.actor_seq.get(&envelope.actor.0).unwrap_or(&0));
            for region in &plan.touched.regions {
                touched_all.record(region.clone());
            }
            conflicts_all.extend(plan.conflicts);
            newly_applied.push((envelope, plan.touched));
        }

        // Bookkeeping for `preview_conflicts`'s real, additive `db_conflict::ConflictDetector`
        // integration (see its own doc) — `submit`'s own returned `ConflictRecord`s stay this
        // crate's original path-granular last-writer detection above (see `🔖️Conflict`'s doc). Only
        // reached once the outcome step above has accepted the batch.
        for (envelope, _) in &newly_applied {
            self.remember_target(envelope);
        }
        for touch in batch_touches {
            remember_recent_touch(&mut self.recent_touches, touch);
        }

        // publish: compute + WAL-append the new frontier in the same transaction as its commands
        let new_frontier = Frontier { document: self.document.clone(), head_seq, commit_seq: self.frontier.commit_seq + 1, chain_hash: self.state.content_hash().await?.0, epoch: self.frontier.epoch };
        let mut records = db_wal::WalRecordBatch::new();
        let _ = records.push(db_wal::WalRecord::Frontier(new_frontier.clone()));

        // WAL append + durability (ArtifactWal::submit wraps `records` in its own TxBegin/TxCommit)
        let wal_facet = self.storage.wal().await;
        let appended = self.wal.submit(&wal_facet, &commands, &records, options.durability, now_ms).await?;
        drop(wal_facet);
        self.config.security.record_committed(&newly_applied.iter().map(|(envelope, _)| (&envelope.actor, &envelope.mutation_id)).collect::<Vec<_>>(), now_ms);
        let _ = records.close_step()?;
        drop(records);
        self.frontier = new_frontier.clone();

        // publish: index entries join the backlog; the runner writes its full runs after the receipt
        let base_seq = self.frontier.head_seq - newly_applied.len() as u64;
        let queued = ArtifactIndexWatermarks::default();
        for (offset, ((envelope, _), actor_seq)) in newly_applied.iter().zip(&applied_actor_seqs).enumerate() {
            let seq = base_seq + offset as u64 + 1;
            let location = db_index::RecordLocation { segment: appended.segment_index, offset: seq, len: 1 };
            self.index_backlog.queue_command(&queued, seq, location, to_core_actor_id(&envelope.actor).await, *actor_seq);
        }
        self.index_backlog.queue_frontier(&queued, &new_frontier);

        // project: run every registered projection over each newly-applied envelope
        let projection_classes = (self.config.projections)();
        if !projection_classes.is_empty() {
            let index_facet = self.storage.index().await;
            let engine = db_projection::ProjectionEngine::new(&index_facet, self.document.clone(), projection_classes).await?;
            for (offset, (envelope, touched)) in newly_applied.iter().enumerate() {
                engine.apply_envelope(base_seq + offset as u64 + 1, envelope, touched).await?;
            }
        }

        // preview-reconcile
        self.previews.reconcile_with(&db_preview::LandedCommand { frontier: new_frontier.clone(), touched: touched_all }, &db_preview::DbConflictOracle::default());
        self.head_edit_id = Some(command_id.clone());

        // live-query notify
        // 🩹️ R13: was `let _ = self.refresh_live_queries();` — silently dropped the future, so
        // this notify step never actually ran. `.await`ed now; the `Vec<(u64, QueryDiff)>` result
        // is genuinely unneeded here (callers observe diffs via their own subscription poll), so
        // `let _ =` on the awaited, resolved value is the correct fire-and-forget shape.
        let _ = self.refresh_live_queries().await;

        // receipt
        let receipt = CommandReceipt { command_id, frontier: new_frontier, durability: options.durability, conflicts: conflicts_all, state_hash: Some(self.state.content_hash().await?), messages };
        self.remember_receipt(&receipt);
        Ok(receipt)
    }

    /// 🧾️ Keeps `receipt` for a whole-batch resend, forgetting the oldest beyond [`APPLIED_RECEIPTS_MAX`].
    fn remember_receipt(&mut self, receipt: &CommandReceipt) {
        if self.applied_receipts.insert(receipt.command_id.0.clone(), receipt.clone()).is_none() {
            self.applied_receipt_order.push_back(receipt.command_id.0.clone());
        }
        while self.applied_receipt_order.len() > APPLIED_RECEIPTS_MAX {
            if let Some(oldest) = self.applied_receipt_order.pop_front() {
                self.applied_receipts.remove(&oldest);
            }
        }
    }

    /// 🗂️ Writes every full index run the commits so far queued — their WAL records are the durable truth
    /// ([`ArtifactIndexBacklog`]). The document runner calls it after a commit's receipt was sent, so no Ack waits
    /// for index I/O; `submit` calls it first only when the backlog outgrew [`INDEX_BACKLOG_ENTRIES_MAX`].
    pub async fn maintain_index(&mut self) -> Result<(), DbError> {
        let index_facet = self.storage.index().await;
        self.index_backlog.flush(&index_facet, &self.document, false).await
    }

    /// ↩️ The inverse-undo pipeline: looks up `target`'s already-applied envelope, flips its
    /// `inverse` into a compensating envelope's `diff` (and vice versa, so the compensating
    /// envelope's OWN inverse can re-undo the undo), and submits it as a fresh, ordinary command
    /// depending on `target` — undo is just another commit, not a WAL rewrite. This is the crate's
    /// "inverse undo, using protocol's inverse-operation machinery".
    pub async fn undo(&mut self, target: &protocol::MutationId, undo_mutation_id: protocol::MutationId, actor: protocol::ActorId, now_ms: u64) -> Result<CommandReceipt, DbError> {
        let original = self.applied.get(&target.0).cloned().ok_or_else(|| DbError::NotFound(format!("operation {} not found for undo", target.0)))?;
        let undo_diff_entries = inverse_entries(&original.inverse).await?;
        let redo_inverse_entries = diff_entries(&original.diff).await?;
        let compensating = protocol::MutationEnvelope {
            mutation_id: undo_mutation_id,
            document_id: self.protocol_document.clone(),
            actor,
            dependencies: vec![target.clone()],
            observed: None,
            target: Vec::new(),
            diff: protocol::ArtifactDiff { schema: original.inverse.schema.clone(), payload: encode_pathmap(&entries_to_value(&undo_diff_entries)).await },
            inverse: protocol::InverseMutation { schema: original.diff.schema, payload: encode_pathmap(&entries_to_value(&redo_inverse_entries)).await },
            timestamp: protocol::HybridLogicalTimestamp::new(0, now_ms),
            transaction: None, verb: None, line: None,
        };
        self.submit(CommandBatch::new(vec![compensating]).await?, SubmitOptions::default(), now_ms).await
    }

    pub async fn get(&self, path: &str) -> Result<Option<db_query::QueryBytes>, DbError> {
        let Some(value) = self.state.get(path) else { return Ok(None) };
        let mut control = db_query::QueryCursorControl::new(Arc::new(std::sync::atomic::AtomicBool::new(false)), std::time::Instant::now() + std::time::Duration::from_secs(30), 65_536)?;
        Ok(Some(db_query::QueryBytes::copy_from_pages(value, &mut control).await?))
    }

    pub async fn frontier(&self) -> Frontier {
        self.frontier.clone()
    }

    /// 📍️ Captures the frontier and its exact committed tip in one serialized actor turn.
    pub async fn checkpoint_publication_snapshot(&self) -> CheckpointPublicationSnapshot {
        CheckpointPublicationSnapshot { frontier: self.frontier.clone(), head_edit_id: self.head_edit_id.clone() }
    }

    pub fn history_replay(&self, operation_generation: u64, cancelled: Arc<std::sync::atomic::AtomicBool>, reservation: HistoryReplayReservation) -> HistoryReplayFuture {
        HistoryReplayFuture::new(self.storage.clone(), self.document.clone(), operation_generation, cancelled, reservation)
    }

    /// 📓️ Appends one Store-admitted fixed-three decision as a forced-Fsync event on this
    /// authority's already-retained WAL writer. Admission and capacity rejection complete before
    /// storage I/O; every error returned by `submit` remains an uncertain durable outcome.
    async fn append_durable_group_decision(&mut self, record: store::durable_group::DurableOwnedGroupJournalRecordV1, cancelled: Arc<std::sync::atomic::AtomicBool>, now_ms: u64) -> Result<ArtifactDurableGroupJournalAppendV1, DbError> {
        if let Some(receipt) = self.durable_group_receipts.get(record.decision_sha256()) {
            return Ok(ArtifactDurableGroupJournalAppendV1::Committed(receipt.clone()));
        }
        if cancelled.load(std::sync::atomic::Ordering::Acquire) {
            return Ok(ArtifactDurableGroupJournalAppendV1::Absent);
        }
        let head_edit_id = protocol::MutationId(record.parent_edit_id().to_string());
        let next_frontier = Frontier {
            document: self.document.clone(),
            head_seq: self.frontier.head_seq.checked_add(1).ok_or_else(|| DbError::LimitExceeded("durable group head sequence"))?,
            commit_seq: self.frontier.commit_seq.checked_add(1).ok_or_else(|| DbError::LimitExceeded("durable group commit sequence"))?,
            chain_hash: record.parent_post_revision(),
            epoch: self.frontier.epoch,
        };
        let (canonical_pack, decision_sha256, anchor_sha256, document) = record.into_parts();
        if document.artifact_id != self.protocol_document.0 {
            return Ok(ArtifactDurableGroupJournalAppendV1::Rejected(DbError::InvalidArgument("durable group decision anchor targets a different document".to_string())));
        }
        let mut control = db_wal::WalCursorControl::new(cancelled.clone(), std::time::Instant::now() + std::time::Duration::from_secs(30), 1_000_000)?;
        let event = match admit_wal_bytes(canonical_pack, db_storage::DB_IO_MAX_READ_BYTES, &mut control).await {
            Ok(event) => event,
            Err(error) => return Ok(ArtifactDurableGroupJournalAppendV1::Rejected(error)),
        };
        let mut records = db_wal::WalRecordBatch::new();
        if let Err(error) = push_wal_record(&mut records, db_wal::WalRecord::Event(event), &mut control).await {
            let close = close_wal_record_batch(&mut records).await;
            return Ok(ArtifactDurableGroupJournalAppendV1::Rejected(close.err().unwrap_or(error)));
        }
        if let Err(error) = self.wal.preflight_submit(&[], &records) {
            let close = close_wal_record_batch(&mut records).await;
            return Ok(ArtifactDurableGroupJournalAppendV1::Rejected(close.err().unwrap_or(error)));
        }
        if cancelled.load(std::sync::atomic::Ordering::Acquire) {
            close_wal_record_batch(&mut records).await?;
            return Ok(ArtifactDurableGroupJournalAppendV1::Absent);
        }
        let wal_facet = self.storage.wal().await;
        let append = self.wal.submit(&wal_facet, &[], &records, DurabilityClass::Fsync, now_ms).await;
        drop(wal_facet);
        let close = close_wal_record_batch(&mut records).await;
        let receipt = match (append, close) {
            (Ok(receipt), Ok(())) => receipt,
            (Err(error), Ok(())) => return Err(error),
            (Ok(_), Err(error)) => return Err(error),
            (Err(error), Err(close_error)) => return Err(DbError::Internal(format!("durable group WAL append failed: {error}; record retirement failed: {close_error}"))),
        };
        if !receipt.committed {
            return Err(DbError::Internal("forced-Fsync durable group decision did not commit".to_string()));
        }
        let receipt = store::durable_group::DurableOwnedGroupJournalReceiptV1 { anchor_sha256, decision_sha256, transaction_id: receipt.tx_id, segment_index: receipt.segment_index };
        self.frontier = next_frontier;
        self.durable_group_edit_ids.insert(head_edit_id.0.clone());
        remember_recent_touch(&mut self.recent_touches, durable_group_touch(&head_edit_id.0));
        self.head_edit_id = Some(head_edit_id);
        self.durable_group_receipts.insert(receipt.decision_sha256.clone(), receipt.clone());
        Ok(ArtifactDurableGroupJournalAppendV1::Committed(receipt))
    }

    /// 🧭 Replays every committed fixed-three Event in physical WAL order into one opaque
    /// retained target. The target, cursor pages, transaction gate and current Store recovery
    /// never cross the caller reply boundary.
    async fn recover_durable_group_decisions(&mut self, mut driver: ArtifactDurableGroupRecoveryDriverV1) -> Result<(), DbError> {
        if driver.owner.document() != &self.document {
            return Err(DbError::InvalidArgument("durable group recovery target differs from the document authority".to_string()));
        }
        while !driver.owner.drive_recovery_step()? {
            semio_framework_async::yield_once().await;
        }
        let wal_facet = self.storage.wal().await;
        let cancelled = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let control = db_wal::WalCursorControl::new(cancelled, std::time::Instant::now() + std::time::Duration::from_secs(2), 65_536)?;
        let mut replay = db_wal::replay_committed_document(&wal_facet, &self.document, control).await?;
        let outcome = async {
            loop {
                replay.replenish(std::time::Instant::now() + std::time::Duration::from_secs(2), 65_536)?;
                let transaction = match replay.next_transaction_step().await? {
                    db_wal::WalCommittedStep::Transaction(transaction) => transaction,
                    db_wal::WalCommittedStep::Yield => {
                        semio_framework_async::yield_once().await;
                        continue;
                    }
                    db_wal::WalCommittedStep::Done => break,
                };
                if let Some(witness) = committed_durable_group_decision_from_transaction(&self.document, transaction).await? {
                    driver.owner.accept(witness)?;
                    while !driver.owner.drive_recovery_step()? {
                        semio_framework_async::yield_once().await;
                    }
                }
            }
            driver.owner.finish_scan()
        }
        .await;
        loop {
            replay.replenish(std::time::Instant::now() + std::time::Duration::from_secs(2), 65_536)?;
            if !replay.close_owner_step()? {
                break;
            }
            semio_framework_async::yield_once().await;
        }
        if !replay.terminal_is_empty() {
            return Err(DbError::Internal("durable group WAL recovery cursor did not retire terminally".to_string()));
        }
        outcome
    }

    /// 🧹 Runs compaction inside this document authority while its WAL writer stays retained.
    pub(crate) async fn compact_retained(
        &mut self,
        holder: db_storage::DbIoText,
        consolidate_snapshots: bool,
        budget: db_compact::CompactionBudget,
        now_ms: u64,
        cancelled: Arc<std::sync::atomic::AtomicBool>,
    ) -> Result<db_compact::CompactionReport, DbError> {
        let index_facet = self.storage.index().await;
        self.index_backlog.flush(&index_facet, &self.document, true).await?;
        drop(index_facet);
        db_compact::retained_compaction_with_wal(self.storage.clone(), &mut self.wal, holder, consolidate_snapshots, budget, now_ms, cancelled).await
    }

    //#region 🔖️Snapshot
    /// 📸️ Publishes a new `db_snapshot` generation of the whole current `DocumentState` —
    /// new this revision; the counterpart `open` reads back to accelerate materialization.
    pub async fn snapshot_now(&self, now_ms: u64) -> Result<u64, DbError> {
        let cancelled = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let encoder = StatePageEncodeCursor::try_new(&self.state.values, cancelled, std::time::Instant::now() + std::time::Duration::from_secs(30), 65_536)?;
        let page = db_state::Page::try_from_pages(encoder.finish().await?).await?;
        let snapshot_facet = self.storage.snapshot().await;
        let snapshot_manager = db_snapshot::SnapshotManager::new(&snapshot_facet).await;
        let origin = if snapshot_manager.load_latest(&self.document).await?.is_some() { db_snapshot::SnapshotOrigin::Incremental } else { db_snapshot::SnapshotOrigin::FullBaseline };
        let body = db_snapshot::SnapshotBody {
            head_seq: self.frontier.head_seq,
            commit_seq: self.frontier.commit_seq,
            epoch: self.frontier.epoch,
            chain_hash: self.frontier.chain_hash,
            protocol_version: 1,
            base_pack_hash: None,
            roots: vec![page.hash],
            created_at_ms: now_ms,
        };
        snapshot_manager.publish(&self.document, origin, &[page], body).await
    }
    //#endregion 🔖️Snapshot

    //#region 🔖️Query
    /// 🔎️ One-shot query over the document's current materialized state, resolved under
    /// `consistency` via `db_index`'s `CommitIndex`/`FrontierIndex`. `StateQuerySource` always reads
    /// the CURRENT canonical state regardless of what `consistency` resolved to — a true
    /// point-in-time replay is `db_engine`'s documented deferred extension (see its own module doc).
    // 🔒️ Mirrors `submit`'s ownership rationale above: `ArtifactMessage::RunQuery` already owns
    // `query`/`consistency` one level up on the actor-mailbox side, and query descriptors are
    // small, cheap-to-move value types — taking them by reference here would only push the
    // ownership question onto every caller for no benefit.
    #[allow(clippy::needless_pass_by_value)]
    pub async fn query(&self, query: db_query::Query, consistency: db_query::Consistency) -> Result<db_query::QueryResult, DbError> {
        let index_facet = self.storage.index().await;
        let resolver = ArtifactConsistencyResolver {
            current: self.frontier.clone(),
            pending: &self.index_backlog.frontiers,
            commits: db_index::CommitIndex::new(&index_facet, self.document.clone()).await,
            frontiers: db_index::FrontierIndex::new(&index_facet, self.document.clone()).await,
        };
        // A fresh document has no recorded frontier yet; canonical reads still succeed via the
        // in-memory frontier, so only consult the resolver for modes that truly need the index.
        if !matches!(consistency, db_query::Consistency::Canonical) {
            db_query::resolve_consistency(&consistency, &resolver).await?;
        }
        let source = StateQuerySource(&self.state.values);
        let mut control = db_query::QueryCursorControl::new(Arc::new(std::sync::atomic::AtomicBool::new(false)), std::time::Instant::now() + std::time::Duration::from_secs(30), 65_536)?;
        db_query::execute(&query, &source, None::<&db_query::NoFullTextLookup>, &db_query::QueryLimits::default(), &mut control).await
    }

    /// 📡️ Registers a live query, returning its subscription id — new this revision.
    pub async fn subscribe(&mut self, spec: db_query::LiveQuerySpec) -> u64 {
        let id = self.next_live_query_id;
        self.next_live_query_id += 1;
        self.live_queries.insert(id, db_query::LiveQuery::new(spec).await);
        id
    }

    pub async fn unsubscribe(&mut self, id: u64) {
        self.live_queries.remove(&id);
    }

    /// 📡️ Live-query notify: re-evaluates every registered live query and returns what
    /// changed. Called automatically at the end of `submit`; also callable directly.
    pub async fn refresh_live_queries(&mut self) -> Vec<(u64, db_query::QueryDiff)> {
        let source = StateQuerySource(&self.state.values);
        let limits = db_query::QueryLimits::default();
        let mut diffs = Vec::new();
        for (id, live_query) in self.live_queries.iter_mut() {
            let mut control = match db_query::QueryCursorControl::new(Arc::new(std::sync::atomic::AtomicBool::new(false)), std::time::Instant::now() + std::time::Duration::from_secs(30), 65_536) {
                Ok(control) => control,
                Err(_) => continue,
            };
            if let Ok(diff) = live_query.refresh(&source, None::<&db_query::NoFullTextLookup>, &limits, &mut control).await {
                if !diff.added.is_empty() || !diff.removed.is_empty() || !diff.updated.is_empty() {
                    diffs.push((*id, diff));
                }
            }
        }
        diffs
    }
    //#endregion 🔖️Query

    //#region 🔖️Advisory
    /// 🔮️ Advisory-only, real `db_conflict::ConflictDetector` integration: runs `batch`'s
    /// envelopes' touched regions against recent commit history WITHOUT executing anything, using
    /// the family's real bloom-filter/kind-matrix machinery — a caller (e.g. a UI) can call this
    /// before `submit` to preview likely conflicts. `submit`'s own returned `ConflictRecord`s stay
    /// this crate's original path-granular last-writer detection (see `🔖️Conflict`'s doc on why
    /// `db_conflict`'s per-command-pair shape can't replace it without breaking `db_engine`'s frozen
    /// `CommandReceipt.conflicts` element type).
    pub async fn preview_conflicts(&self, batch: &CommandBatch) -> Result<Vec<db_conflict::ConflictRecord>, DbError> {
        let mut probe: Vec<db_conflict::CommandTouch> = self.recent_touches.iter().cloned().collect();
        for envelope in &batch.envelopes {
            let entries = diff_entries(&envelope.diff).await?;
            let touched = entries_touched(&entries);
            probe.push(command_touch(envelope, &touched));
        }
        Ok(db_conflict::ConflictDetector::new().detect(&probe))
    }
    //#endregion 🔖️Advisory

    //#region 🔖️Preview
    /// 🌫️ Publishes a new preview overlaying the CURRENT committed state — never durable
    /// (never touches the WAL), per the contract's preview law. Backed by a real
    /// `db_preview::PreviewStore` this revision (previously a local, minimal stand-in).
    pub async fn publish_preview(&mut self, entries: &[(String, Option<serde_json::Value>)], now_ms: u64) -> Result<db_preview::PreviewId, DbError> {
        let dsl_entries: Vec<(String, Option<DslValue>)> = entries.iter().map(|(path, value)| (path.clone(), value.as_ref().map(DslValue::from))).collect();
        let touched = entries_touched(&dsl_entries);
        let envelope = protocol::MutationEnvelope {
            mutation_id: protocol::MutationId(format!("preview-{}", entries.len())),
            document_id: self.protocol_document.clone(),
            actor: protocol::ActorId("preview".to_string()),
            dependencies: Vec::new(),
            observed: None,
            target: Vec::new(),
            diff: protocol::ArtifactDiff { schema: protocol::SchemaId(DB_PATHMAP_SCHEMA.to_string()), payload: encode_pathmap(&entries_to_value(&dsl_entries)).await },
            inverse: protocol::InverseMutation { schema: protocol::SchemaId(DB_PATHMAP_SCHEMA.to_string()), payload: encode_pathmap(&DslValue::Object(vec![])).await },
            timestamp: protocol::HybridLogicalTimestamp::new(0, now_ms),
            transaction: None, verb: None, line: None,
        };
        self.previews.publish(db_preview::PublishPreviewRequest { document: self.document.clone(), actor: ActorId("preview".to_string()), key: format!("preview-{now_ms}"), base: self.frontier.clone(), envelope, touched, ttl_ms: None, now_ms })
    }

    /// 🌫️ The value a preview would show at `path`: the preview's own diff if it touches
    /// `path`, else falling through to the committed state.
    pub async fn preview_get(&self, id: &db_preview::PreviewId, path: &str) -> Result<Option<db_query::QueryBytes>, DbError> {
        let preview = self.previews.get(id).ok_or_else(|| DbError::NotFound(format!("preview {id} not found")))?;
        for (entry_path, value) in diff_entries(&preview.envelope.diff).await? {
            if entry_path == path {
                return match value {
                    Some(dsl_value) => {
                        let bytes = store::pack_rt::encode_wire_value(&dsl_value);
                        let mut writer = db_storage::DbIoPageWriter::try_reserve(bytes.capacity().div_ceil(db_storage::DB_IO_PAGE_BYTES)).map_err(db_storage::DbIoPageWriterRejected::into_error)?;
                        let mut offset = 0;
                        while offset < bytes.len() {
                            offset += writer.write_fragment(&bytes[offset..])?;
                        }
                        let pages = writer.seal_retained().await.map_err(db_storage::DbIoPageWriterRejected::into_error)?;
                        Ok(Some(db_query::QueryBytes::from_pages(pages).map_err(|(error, mut pages)| {
                            let _ = pages.close_step();
                            drop(pages);
                            error
                        })?))
                    }
                    None => Ok(None),
                };
            }
        }
        self.get(path).await
    }

    pub async fn preview_status(&self, id: &db_preview::PreviewId) -> Result<db_preview::PreviewState, DbError> {
        Ok(self.previews.get(id).ok_or_else(|| DbError::NotFound(format!("preview {id} not found")))?.state)
    }

    pub async fn withdraw_preview(&mut self, id: &db_preview::PreviewId) -> Result<(), DbError> {
        self.previews.withdraw(id)
    }

    pub async fn reject_preview(&mut self, id: &db_preview::PreviewId) -> Result<(), DbError> {
        self.previews.reject(id)
    }

    pub async fn expire_previews(&mut self, now_ms: u64) -> Vec<db_preview::PreviewId> {
        self.previews.sweep_expired(now_ms)
    }
    //#endregion 🔖️Preview
}
//#endregion 🔖️Engine

//#region 🔖️QuerySource
/// 🚰️ The `db_query::QuerySource` this crate supplies over its own `DocumentState`: one row
/// per stored path, `{"path": <path>, "value": <text-or-bytes>}`.
struct StateQuerySource<'a>(&'a db_state::RetainedStateMap);

// 🚫️async: E1 pure accessor consumed by a sync Iterator::map (QuerySource::scan's row builder) — see R9
async fn path_row_value(path: &str, bytes: &db_storage::DbIoPages, control: &mut db_query::QueryCursorControl) -> Result<db_query::Value, DbError> {
    let mut map = std::collections::BTreeMap::new();
    map.insert("path".to_string(), db_query::Value::Text(path.to_string()));
    map.insert("value".to_string(), db_query::Value::Bytes(db_query::QueryBytes::copy_from_pages(bytes, control).await?));
    Ok(db_query::Value::Map(map))
}

impl<'a> db_query::QuerySource for StateQuerySource<'a> {
    async fn scan(&self, control: &mut db_query::QueryCursorControl) -> Result<db_query::QueryRows, DbError> {
        let mut rows = db_query::QueryRows::new();
        for (index, entry) in self.0.iter().enumerate() {
            control.grant()?;
            rows.preflight_push()?;
            let row = db_query::QueryRow::new(db_query::RowId(index as u64), path_row_value(entry.key(), entry.value(), control).await?);
            rows.push_preflighted(row);
        }
        Ok(rows)
    }
}
//#endregion 🔖️QuerySource

//#region 🔖️Snapshot
const MAX_STATE_PAGE_ENTRIES: u64 = 10_000_000;
const MAX_STATE_PAGE_PATH_BYTES: u64 = db_storage::DbIoText::maximum_capacity() as u64;
const MAX_STATE_PAGE_VALUE_BYTES: u64 = 256 * 1024 * 1024;

fn state_page_varint_len(mut value: u64) -> usize {
    let mut len = 1;
    while value >= 0x80 {
        value >>= 7;
        len += 1;
    }
    len
}

fn state_page_varint(mut value: u64, output: &mut [u8; 10]) -> &[u8] {
    let mut len = 0;
    loop {
        let mut byte = (value & 0x7f) as u8;
        value >>= 7;
        if value != 0 {
            byte |= 0x80;
        }
        output[len] = byte;
        len += 1;
        if value == 0 {
            return &output[..len];
        }
    }
}

struct StatePageGrant {
    cancelled: Arc<std::sync::atomic::AtomicBool>,
    deadline: std::time::Instant,
    fuel: usize,
}

impl StatePageGrant {
    fn consume(&mut self) -> Result<(), DbError> {
        if self.cancelled.load(std::sync::atomic::Ordering::Acquire) {
            return Err(DbError::Unavailable("state page cursor cancelled".to_string()));
        }
        if std::time::Instant::now() >= self.deadline {
            return Err(DbError::Unavailable("state page cursor deadline reached".to_string()));
        }
        self.fuel = self.fuel.checked_sub(1).ok_or(DbError::LimitExceeded("state page cursor fuel"))?;
        Ok(())
    }
}

struct StatePageEncodeCursor<'state> {
    values: &'state db_state::RetainedStateMap,
    writer: db_storage::DbIoPageWriter,
    grant: StatePageGrant,
}

impl<'state> StatePageEncodeCursor<'state> {
    fn try_new(values: &'state db_state::RetainedStateMap, cancelled: Arc<std::sync::atomic::AtomicBool>, deadline: std::time::Instant, fuel: usize) -> Result<Self, DbError> {
        check_len(values.len() as u64, MAX_STATE_PAGE_ENTRIES, "db_artifact::snapshot_page_entries")?;
        let mut len = state_page_varint_len(values.len() as u64);
        for entry in values.iter() {
            let path = entry.key();
            let value = entry.value();
            check_len(path.len() as u64, MAX_STATE_PAGE_PATH_BYTES, "db_artifact::snapshot_page_path")?;
            check_len(value.len() as u64, MAX_STATE_PAGE_VALUE_BYTES, "db_artifact::snapshot_page_value")?;
            len = len.checked_add(state_page_varint_len(path.len() as u64) + path.len() + 1 + state_page_varint_len(value.len() as u64) + value.len()).ok_or(DbError::LimitExceeded("state page encoded bytes"))?;
        }
        let pages = len.div_ceil(db_storage::DB_IO_PAGE_BYTES);
        if pages > db_storage::DB_IO_OPERATION_PAGES {
            return Err(DbError::LimitExceeded("state page reservation"));
        }
        let writer = db_storage::DbIoPageWriter::try_reserve(pages).map_err(db_storage::DbIoPageWriterRejected::into_error)?;
        Ok(Self { values, writer, grant: StatePageGrant { cancelled, deadline, fuel } })
    }

    async fn write(&mut self, bytes: &[u8]) -> Result<(), DbError> {
        let mut offset = 0;
        while offset < bytes.len() {
            self.grant.consume()?;
            offset += self.writer.write_fragment(&bytes[offset..])?;
            semio_framework_async::yield_once().await;
        }
        Ok(())
    }

    async fn finish(mut self) -> Result<db_storage::DbIoPages, DbError> {
        let mut varint = [0u8; 10];
        self.write(state_page_varint(self.values.len() as u64, &mut varint)).await?;
        for entry in self.values.iter() {
            let path = entry.key();
            let value = entry.value();
            self.write(state_page_varint(path.len() as u64, &mut varint)).await?;
            self.write(path.as_bytes()).await?;
            self.write(&[1]).await?;
            self.write(state_page_varint(value.len() as u64, &mut varint)).await?;
            for fragment in value.fragments() {
                self.write(fragment).await?;
            }
        }
        self.writer.seal_retained().await.map_err(db_storage::DbIoPageWriterRejected::into_error)
    }
}

struct StatePageDecodeCursor<'pages> {
    pages: &'pages db_storage::DbIoPages,
    page: u8,
    offset: usize,
    remaining: Option<u64>,
    grant: StatePageGrant,
    closed: bool,
}

impl<'pages> StatePageDecodeCursor<'pages> {
    fn new(pages: &'pages db_storage::DbIoPages, cancelled: Arc<std::sync::atomic::AtomicBool>, deadline: std::time::Instant, fuel: usize) -> Result<Self, DbError> {
        if pages.operation() == 0 || fuel == 0 {
            return Err(DbError::InvalidArgument("state page decode authority".to_string()));
        }
        Ok(Self { pages, page: 0, offset: 0, remaining: None, grant: StatePageGrant { cancelled, deadline, fuel }, closed: false })
    }

    fn byte(&mut self) -> Result<u8, DbError> {
        self.grant.consume()?;
        loop {
            let fragment = self.pages.page(self.page).ok_or_else(|| DbError::Corrupt("state page ended early".to_string()))?;
            if let Some(byte) = fragment.get(self.offset) {
                self.offset += 1;
                return Ok(*byte);
            }
            self.page = self.page.checked_add(1).ok_or(DbError::LimitExceeded("state page fragment cursor"))?;
            self.offset = 0;
        }
    }

    fn varint(&mut self) -> Result<u64, DbError> {
        let mut value = 0u64;
        for shift in (0..70).step_by(7) {
            let byte = self.byte()?;
            value |= u64::from(byte & 0x7f) << shift;
            if byte & 0x80 == 0 {
                return Ok(value);
            }
        }
        Err(DbError::Corrupt("state page varint overflow".to_string()))
    }

    fn fixed_field<const N: usize>(&mut self, len: usize) -> Result<[u8; N], DbError> {
        if len > N {
            return Err(DbError::LimitExceeded("state page fixed field"));
        }
        let mut output = [0u8; N];
        let mut written = 0;
        while written < len {
            self.grant.consume()?;
            let fragment = self.pages.page(self.page).ok_or_else(|| DbError::Corrupt("state page field ended early".to_string()))?;
            if self.offset == fragment.len() {
                self.page = self.page.checked_add(1).ok_or(DbError::LimitExceeded("state page fragment cursor"))?;
                self.offset = 0;
                continue;
            }
            let copied = (len - written).min(fragment.len() - self.offset);
            output[written..written + copied].copy_from_slice(&fragment[self.offset..self.offset + copied]);
            written += copied;
            self.offset += copied;
        }
        Ok(output)
    }

    async fn retained_field(&mut self, len: usize) -> Result<db_storage::DbIoPages, DbError> {
        let pages = len.div_ceil(db_storage::DB_IO_PAGE_BYTES);
        let mut writer = db_storage::DbIoPageWriter::try_reserve_for_operation(self.pages.operation(), pages).map_err(db_storage::DbIoPageWriterRejected::into_error)?;
        let mut written = 0;
        while written < len {
            self.grant.consume()?;
            let fragment = self.pages.page(self.page).ok_or_else(|| DbError::Corrupt("state page value ended early".to_string()))?;
            if self.offset == fragment.len() {
                self.page = self.page.checked_add(1).ok_or(DbError::LimitExceeded("state page fragment cursor"))?;
                self.offset = 0;
                continue;
            }
            let copied = (len - written).min(fragment.len() - self.offset);
            let accepted = writer.write_fragment(&fragment[self.offset..self.offset + copied])?;
            if accepted != copied {
                return Err(DbError::Internal("state page value writer made partial progress".to_string()));
            }
            self.offset += copied;
            written += copied;
            semio_framework_async::yield_once().await;
        }
        writer.seal_retained().await.map_err(db_storage::DbIoPageWriterRejected::into_error)
    }

    async fn next(&mut self) -> Result<Option<db_state::StateEntry>, DbError> {
        let remaining = match self.remaining {
            Some(remaining) => remaining,
            None => {
                let count = self.varint()?;
                check_len(count, MAX_STATE_PAGE_ENTRIES, "db_artifact::snapshot_page_entries")?;
                self.remaining = Some(count);
                count
            }
        };
        if remaining == 0 {
            return Ok(None);
        }
        let path_len = self.varint()?;
        check_len(path_len, MAX_STATE_PAGE_PATH_BYTES, "db_artifact::snapshot_page_path")?;
        let path = self.fixed_field::<1024>(path_len as usize)?;
        let path = std::str::from_utf8(&path[..path_len as usize]).map_err(|_| DbError::Corrupt("snapshot page path is not valid utf-8".to_string()))?;
        let value = match self.byte()? {
            1 => {
                let len = self.varint()?;
                check_len(len, MAX_STATE_PAGE_VALUE_BYTES, "db_artifact::snapshot_page_value")?;
                self.retained_field(len as usize).await?
            }
            _ => return Err(DbError::Corrupt("state page value tag".to_string())),
        };
        let entry = db_state::StateEntry::try_new(path, value).map_err(|(error, mut value)| {
            let _ = value.close_step();
            drop(value);
            error
        })?;
        self.remaining = Some(remaining - 1);
        semio_framework_async::yield_once().await;
        Ok(Some(entry))
    }

    fn close_step(&mut self) -> Result<bool, DbError> {
        self.grant.consume()?;
        if self.closed {
            return Ok(false);
        }
        self.remaining = Some(0);
        self.closed = true;
        Ok(true)
    }
}

/// 📋️ What `ArtifactEngine::open` did to materialize state — "initial ⊕ snapshot ⊕ WAL
/// suffix" made observable. New this revision (was `db_wal::WalRecoveryReport` alone before).
#[derive(Clone, Debug, Default)]
pub struct MaterializeReport {
    pub from_snapshot: bool,
    pub snapshot_generation: Option<u64>,
    pub torn_tail_bytes: u64,
    pub commands_replayed: u64,
}
//#endregion 🔖️Snapshot

//#region 🔖️LedgerTail
/// 🧮️ Ceiling on the committed transactions one ledger tail may carry, equal to the hub
/// authority's own `AUTHORITY_MAX_OPERATIONS`.
pub const ARTIFACT_LEDGER_TAIL_MAX_COMMITS: usize = 16_384;

/// 📍️ One exact point of a document's committed ledger: the counters and content chain the
/// document authority publishes plus the edit id at its tip (`None` only for genesis).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ArtifactLedgerPoint {
    pub head_seq: u64,
    pub commit_seq: u64,
    pub chain_hash: [u8; 32],
    pub head_edit_id: Option<protocol::MutationId>,
}

impl ArtifactLedgerPoint {
    /// 🌱️ The point of a document nothing was ever committed to.
    pub const fn genesis() -> Self {
        Self { head_seq: 0, commit_seq: 0, chain_hash: [0; 32], head_edit_id: None }
    }

    /// 📸️ The point an actor-serialized snapshot names.
    pub fn of_snapshot(snapshot: &CheckpointPublicationSnapshot) -> Self {
        Self { head_seq: snapshot.frontier.head_seq, commit_seq: snapshot.frontier.commit_seq, chain_hash: snapshot.frontier.chain_hash, head_edit_id: snapshot.head_edit_id.clone() }
    }

    fn is_genesis(&self) -> bool {
        *self == Self::genesis()
    }
}

/// 📜️ One committed command transaction of the ledger tail: its envelopes in WAL order and the
/// point the document authority published for it.
#[derive(Clone, Debug, PartialEq)]
pub struct ArtifactLedgerCommit {
    pub point: ArtifactLedgerPoint,
    pub envelopes: Vec<protocol::MutationEnvelope>,
}

/// 📜️ The committed command transactions strictly after `after` through exactly `through`, read
/// from the same WAL and with the same point derivation `ArtifactEngine::open` replays: a command
/// transaction's point is its terminal `Frontier` record plus its last command's id, and a durable
/// group decision advances the point by one head and one commit to its parent post revision. Both
/// points must be ledger points exactly, `after` must precede `through`, and a durable group
/// decision inside the range is refused: its content is an approval's, published with its own
/// checkpoint, and never an envelope a replica folds. `cancelled` stops the walk at the next record.
///
/// See `🌎️hub/🗿️artifact-authority/📌️check-in` for the hub Check In that consumes it.
pub async fn artifact_ledger_tail(wal: &impl WalStorage, document: &ArtifactId, after: &ArtifactLedgerPoint, through: &ArtifactLedgerPoint, cancelled: Arc<std::sync::atomic::AtomicBool>) -> Result<Vec<ArtifactLedgerCommit>, DbError> {
    if through.head_seq <= after.head_seq || through.commit_seq <= after.commit_seq || through.head_edit_id.is_none() {
        return Err(DbError::InvalidArgument("ledger tail must end at an edited point after its start".to_string()));
    }
    let control = db_wal::WalCursorControl::new(cancelled.clone(), std::time::Instant::now() + db_wal::WAL_REPLAY_STEP_STALL_BOUND, db_wal::WAL_REPLAY_STEP_FUEL)?;
    let mut records = db_wal::replay_committed_document(wal, document, control).await?;
    let mut decode_control = db_wal::WalCursorControl::stall_bounded(cancelled.clone(), db_wal::WAL_REPLAY_STEP_STALL_BOUND, db_wal::WAL_REPLAY_STEP_FUEL)?;
    let mut turn = db_wal::WalTurn::start();
    let result = async {
        let mut point = ArtifactLedgerPoint::genesis();
        let mut decisions: HashSet<String> = HashSet::new();
        let mut started = after.is_genesis();
        let mut commits = Vec::new();
        loop {
            if cancelled.load(std::sync::atomic::Ordering::Acquire) {
                return Err(DbError::Unavailable("ledger tail cancelled".to_string()));
            }
            records.renew_step()?;
            decode_control.renew_step()?;
            let mut transaction = match records.next_transaction_step().await? {
                db_wal::WalCommittedStep::Transaction(transaction) => transaction,
                db_wal::WalCommittedStep::Yield => {
                    turn.step().await;
                    continue;
                }
                db_wal::WalCommittedStep::Done => return Err(DbError::NotFound("ledger tail end is not a committed ledger point".to_string())),
            };
            let mut envelopes = Vec::new();
            let mut frontier = None;
            let mut decision = None;
            loop {
                let record = match transaction.next_record_step()? {
                    db_wal::WalCommittedRecordStep::Record(record) => record,
                    db_wal::WalCommittedRecordStep::Yield => {
                        turn.step().await;
                        continue;
                    }
                    db_wal::WalCommittedRecordStep::Done => break,
                };
                match record {
                    db_wal::WalRecord::Command(bytes) => {
                        let envelope = db_sync::decode_wal_command(bytes, &mut decode_control)?;
                        if envelope.document_id.0 != document.0 {
                            return Err(DbError::Corrupt("ledger envelope document differs".to_string()));
                        }
                        envelopes.push(envelope);
                    }
                    db_wal::WalRecord::Frontier(committed) => {
                        if committed.document != *document {
                            return Err(DbError::Corrupt("ledger frontier document differs".to_string()));
                        }
                        frontier = Some(committed.clone());
                    }
                    db_wal::WalRecord::Event(bytes) => {
                        let mut canonical_pack = Vec::with_capacity(bytes.len());
                        for fragment in bytes.fragments() {
                            canonical_pack.extend_from_slice(fragment);
                        }
                        decision = Some(store::durable_group::DurableOwnedGroupJournalRecordV1::admit_canonical(canonical_pack).map_err(|error| DbError::Corrupt(format!("committed durable group decision is invalid: {error}")))?);
                    }
                    _ => {}
                }
                while transaction.close_record_step()? {
                    turn.step().await;
                }
                turn.step().await;
            }
            transaction.finish()?;
            let next = match (decision, frontier, envelopes.last()) {
                (Some(record), None, None) => {
                    if !decisions.insert(record.decision_sha256().to_string()) {
                        continue;
                    }
                    if started {
                        return Err(DbError::Conflict("ledger tail contains a durable group decision".to_string()));
                    }
                    ArtifactLedgerPoint {
                        head_seq: point.head_seq.checked_add(1).ok_or(DbError::LimitExceeded("ledger tail head sequence"))?,
                        commit_seq: point.commit_seq.checked_add(1).ok_or(DbError::LimitExceeded("ledger tail commit sequence"))?,
                        chain_hash: record.parent_post_revision(),
                        head_edit_id: Some(protocol::MutationId(record.parent_edit_id().to_string())),
                    }
                }
                (None, Some(frontier), Some(last)) => ArtifactLedgerPoint { head_seq: frontier.head_seq, commit_seq: frontier.commit_seq, chain_hash: frontier.chain_hash, head_edit_id: Some(last.mutation_id.clone()) },
                (None, None, None) => continue,
                _ => return Err(DbError::Corrupt("ledger transaction is neither one command batch with its frontier nor one durable group decision".to_string())),
            };
            if next.head_seq <= point.head_seq || next.commit_seq <= point.commit_seq {
                return Err(DbError::Corrupt("ledger points do not advance".to_string()));
            }
            point = next;
            if !started {
                if point == *after {
                    started = true;
                } else if point.commit_seq >= after.commit_seq {
                    return Err(DbError::NotFound("ledger tail start is not a committed ledger point".to_string()));
                }
                continue;
            }
            if commits.len() == ARTIFACT_LEDGER_TAIL_MAX_COMMITS {
                return Err(DbError::LimitExceeded("ledger tail commits"));
            }
            let reached = point == *through;
            if !reached && point.commit_seq >= through.commit_seq {
                return Err(DbError::NotFound("ledger tail end is not a committed ledger point".to_string()));
            }
            commits.push(ArtifactLedgerCommit { point: point.clone(), envelopes });
            if reached {
                return Ok(commits);
            }
        }
    }
    .await;
    while records.close_owner_step()? {
        semio_framework_async::yield_once().await;
    }
    drop(records);
    result
}
//#endregion 🔖️LedgerTail

//#region 🔖️HistoryReplay
const HISTORY_REPLAY_PAGE_BYTES: u64 = 16 * 1024;
const HISTORY_REPLAY_SEGMENT_PAGES: u64 = 1_024;
const HISTORY_REPLAY_RESULT_BYTES: u64 = 15 * 1024 * 1024;
const HISTORY_REPLAY_OPERATION_BYTES: u64 = 32 * 1024 * 1024;
const HISTORY_REPLAY_MAX_FRAME_BYTES: u64 = 1024 * 1024;
const HISTORY_REPLAY_MAX_FIELD_BYTES: usize = HISTORY_REPLAY_PAGE_BYTES as usize;
const HISTORY_REPLAY_MAX_ENTRIES: usize = 4_096;
const HISTORY_REPLAY_MAX_OPERATION_IDS: usize = 8_192;
const HISTORY_REPLAY_RESULT_PAGES: usize = (HISTORY_REPLAY_RESULT_BYTES / HISTORY_REPLAY_PAGE_BYTES) as usize;
const HISTORY_REPLAY_CONSTRUCTION_SLOTS: usize = 64;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct HistoryTextRange {
    start: u32,
    len: u16,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ArtifactHistoryEntry {
    pub operation_start: u16,
    pub operation_count: u16,
    pub head_seq: u64,
    pub commit_seq: u64,
    pub chain_hash: [u8; 32],
    pub epoch: u64,
}

pub struct ArtifactHistoryView {
    pub entries: Vec<ArtifactHistoryEntry>,
    operation_ids: Vec<HistoryTextRange>,
    result_pages: Vec<Option<Vec<u8>>>,
    result_len: u64,
    pub retained_bytes: u64,
    pub retained_items: usize,
}

impl ArtifactHistoryView {
    pub fn operation_id_eq(&self, entry: usize, operation: usize, expected: &str) -> bool {
        let Some(entry) = self.entries.get(entry) else {
            return false;
        };
        if operation >= entry.operation_count as usize {
            return false;
        }
        let Some(index) = (entry.operation_start as usize).checked_add(operation) else {
            return false;
        };
        let Some(range) = self.operation_ids.get(index).copied() else {
            return false;
        };
        let expected = expected.as_bytes();
        if expected.len() != range.len as usize {
            return false;
        }
        let offset = range.start as usize;
        let page = offset / HISTORY_REPLAY_PAGE_BYTES as usize;
        let within = offset % HISTORY_REPLAY_PAGE_BYTES as usize;
        let Some(first) = self.result_pages.get(page).and_then(Option::as_ref) else {
            return false;
        };
        let first_len = expected.len().min(first.len().saturating_sub(within));
        if first_len == 0 || expected.get(..first_len) != first.get(within..within + first_len) {
            return false;
        }
        if first_len == expected.len() {
            return true;
        }
        self.result_pages.get(page + 1).and_then(Option::as_ref).and_then(|second| second.get(..expected.len() - first_len)) == expected.get(first_len..)
    }

    pub fn close_step(&mut self) -> bool {
        if self.operation_ids.pop().is_some() {
            return true;
        }
        if self.entries.pop().is_some() {
            return true;
        }
        if let Some(owner) = self.result_pages.pop() {
            drop(owner);
            return true;
        }
        false
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.operation_ids.is_empty() && self.entries.is_empty() && self.result_pages.is_empty()
    }
}

/// 🔒️ Serializes the tests that saturate or consume the process-global history replay
/// construction registry and admission slots, so one law's capacity never becomes another's refusal.
#[cfg(test)]
pub(crate) fn history_capacity_test_lock() -> std::sync::MutexGuard<'static, ()> {
    static LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
    LOCK.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
}

pub struct HistoryReplayReservation {
    source_pages: Vec<Option<Vec<u8>>>,
    source_page_count: usize,
    result_pages: Vec<Option<Vec<u8>>>,
    operation_ids: Vec<HistoryTextRange>,
    entries: Vec<ArtifactHistoryEntry>,
    scratch: Option<Vec<u8>>,
    retained_operation_bytes: u64,
    retained_result_bytes: u64,
}

impl std::fmt::Debug for HistoryReplayReservation {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("HistoryReplayReservation")
            .field("source_pages", &self.source_pages.len())
            .field("source_page_count", &self.source_page_count)
            .field("result_pages", &self.result_pages.len())
            .field("operation_ids", &self.operation_ids.len())
            .field("entries", &self.entries.len())
            .field("scratch", &self.scratch.as_ref().map(Vec::len))
            .field("retained_operation_bytes", &self.retained_operation_bytes)
            .field("retained_result_bytes", &self.retained_result_bytes)
            .finish()
    }
}

impl HistoryReplayReservation {
    pub(crate) fn try_new() -> Result<Self, HistoryReplayReservationConstructionFault> {
        Self::try_new_retained(None)
    }

    #[cfg(test)]
    fn try_new_with_result_page_failure(failure_after: usize) -> Result<Self, HistoryReplayReservationConstructionFault> {
        Self::try_new_retained(Some(failure_after))
    }

    fn try_new_retained(failure_after: Option<usize>) -> Result<Self, HistoryReplayReservationConstructionFault> {
        let mut builder = match HistoryReplayReservationConstructionBuilder::new() {
            Ok(builder) => builder,
            Err(fault) => return Err(fault),
        };
        if !builder.edit_cursor(|cursor| cursor.source_pages.as_mut().is_some_and(|owners| owners.try_reserve_exact(HISTORY_REPLAY_SEGMENT_PAGES as usize).is_ok())).unwrap_or(false) {
            return Err(builder.fault(|| DbError::Unavailable("history source owner-slot reservation failed".to_string())));
        }
        if !builder
            .edit_cursor(|cursor| {
                let Some(owners) = cursor.source_pages.as_mut() else {
                    return false;
                };
                owners.resize_with(HISTORY_REPLAY_SEGMENT_PAGES as usize, || None);
                true
            })
            .unwrap_or(false)
        {
            return Err(builder.fault(|| DbError::Unavailable("history source owner-slot publication failed".to_string())));
        }
        if !builder.edit_cursor(|cursor| cursor.result_pages.as_mut().is_some_and(|owners| owners.try_reserve_exact(HISTORY_REPLAY_RESULT_PAGES).is_ok())).unwrap_or(false) {
            return Err(builder.fault(|| DbError::Unavailable("history result page-slot reservation failed".to_string())));
        }
        let mut result_owner_bytes = 0u64;
        for page_index in 0..HISTORY_REPLAY_RESULT_PAGES {
            if failure_after == Some(page_index) {
                return Err(builder.fault(|| DbError::Unavailable("history injected result page reservation failed".to_string())));
            }
            let mut page = Vec::new();
            if page.try_reserve_exact(HISTORY_REPLAY_PAGE_BYTES as usize).is_err() {
                return Err(builder.fault(|| DbError::Unavailable("history result page reservation failed".to_string())));
            }
            page.resize(HISTORY_REPLAY_PAGE_BYTES as usize, 0);
            let Some(next_result_owner_bytes) = result_owner_bytes.checked_add(page.capacity() as u64) else {
                let published = builder.edit_cursor(|cursor| {
                    cursor.result_pages.as_mut().is_some_and(|owners| {
                        owners.push(Some(page));
                        true
                    })
                });
                if !published.unwrap_or(false) {
                    return Err(builder.fault(|| DbError::Unavailable("history result page publication failed".to_string())));
                }
                return Err(builder.fault(|| DbError::LimitExceeded("history result reservation bytes")));
            };
            result_owner_bytes = next_result_owner_bytes;
            if !builder
                .edit_cursor(|cursor| {
                    cursor.result_pages.as_mut().is_some_and(|owners| {
                        owners.push(Some(page));
                        true
                    })
                })
                .unwrap_or(false)
            {
                return Err(builder.fault(|| DbError::Unavailable("history result page publication failed".to_string())));
            }
        }
        if failure_after == Some(HISTORY_REPLAY_RESULT_PAGES) {
            return Err(builder.fault(|| DbError::Unavailable("history injected result page boundary failed".to_string())));
        }
        if !builder.edit_cursor(|cursor| cursor.operation_ids.as_mut().is_some_and(|owners| owners.try_reserve_exact(HISTORY_REPLAY_MAX_OPERATION_IDS).is_ok())).unwrap_or(false) {
            return Err(builder.fault(|| DbError::Unavailable("history operation owner-slot reservation failed".to_string())));
        }
        if !builder.edit_cursor(|cursor| cursor.entries.as_mut().is_some_and(|owners| owners.try_reserve_exact(HISTORY_REPLAY_MAX_ENTRIES).is_ok())).unwrap_or(false) {
            return Err(builder.fault(|| DbError::Unavailable("history entry owner-slot reservation failed".to_string())));
        }
        let Some((result_slot_bytes, operation_slot_bytes, entry_slot_bytes, source_slot_bytes)) = builder
            .read_cursor(|cursor| {
                let result = cursor.result_pages.as_ref().map(Vec::capacity);
                let operations = cursor.operation_ids.as_ref().map(Vec::capacity);
                let entries = cursor.entries.as_ref().map(Vec::capacity);
                let source = cursor.source_pages.as_ref().map(Vec::capacity);
                match (result, operations, entries, source) {
                    (Some(result), Some(operations), Some(entries), Some(source)) => {
                        Some(((result * size_of::<Option<Vec<u8>>>()) as u64, (operations * size_of::<HistoryTextRange>()) as u64, (entries * size_of::<ArtifactHistoryEntry>()) as u64, (source * size_of::<Option<Vec<u8>>>()) as u64))
                    }
                    _ => None,
                }
            })
            .flatten()
        else {
            return Err(builder.fault(|| DbError::Unavailable("history construction owner accounting was unavailable".to_string())));
        };
        let Some(retained_result_bytes) = result_owner_bytes.checked_add(result_slot_bytes).and_then(|bytes| bytes.checked_add(operation_slot_bytes)).and_then(|bytes| bytes.checked_add(entry_slot_bytes)) else {
            return Err(builder.fault(|| DbError::LimitExceeded("history retained result bytes")));
        };
        let Some(retained_operation_bytes) = retained_result_bytes.checked_add(source_slot_bytes).and_then(|bytes| bytes.checked_add(HISTORY_REPLAY_MAX_FIELD_BYTES as u64)) else {
            return Err(builder.fault(|| DbError::LimitExceeded("history retained operation bytes")));
        };
        if !builder.edit_cursor(|cursor| cursor.scratch.as_mut().is_some_and(|scratch| scratch.try_reserve_exact(HISTORY_REPLAY_MAX_FIELD_BYTES).is_ok())).unwrap_or(false) {
            return Err(builder.fault(|| DbError::Unavailable("history scratch page reservation failed".to_string())));
        }
        if !builder
            .edit_cursor(|cursor| {
                cursor.scratch.as_mut().is_some_and(|scratch| {
                    scratch.resize(HISTORY_REPLAY_MAX_FIELD_BYTES, 0);
                    true
                })
            })
            .unwrap_or(false)
        {
            return Err(builder.fault(|| DbError::Unavailable("history scratch page publication failed".to_string())));
        }
        builder.finish(retained_operation_bytes, retained_result_bytes)
    }

    fn retained_bytes(&self) -> Option<u64> {
        Some(self.retained_operation_bytes)
    }

    fn preflight_result_range(&self, result_len: u64, len: u64) -> Result<u64, DbError> {
        if self.operation_ids.len() >= HISTORY_REPLAY_MAX_OPERATION_IDS {
            return Err(DbError::LimitExceeded("history operation item credit"));
        }
        match result_len.checked_add(len) {
            Some(end) if end <= HISTORY_REPLAY_RESULT_BYTES => Ok(end),
            _ => Err(DbError::LimitExceeded("history result byte credit")),
        }
    }

    #[cfg(test)]
    fn retain_source_page(&mut self, page: Vec<u8>) -> Result<(), Vec<u8>> {
        let Some(slot) = self.source_pages.get_mut(self.source_page_count) else {
            return Err(page);
        };
        if slot.is_some() {
            return Err(page);
        }
        *slot = Some(page);
        self.source_page_count += 1;
        Ok(())
    }
}

pub struct HistoryReplayReservationCloseCursor {
    source_pages: Option<Vec<Option<Vec<u8>>>>,
    source_page_count: usize,
    result_pages: Option<Vec<Option<Vec<u8>>>>,
    operation_ids: Option<Vec<HistoryTextRange>>,
    entries: Option<Vec<ArtifactHistoryEntry>>,
    scratch: Option<Vec<u8>>,
    retained_operation_bytes: u64,
    retained_result_bytes: u64,
    started: bool,
}

impl HistoryReplayReservationCloseCursor {
    pub fn new(reservation: HistoryReplayReservation) -> Self {
        let HistoryReplayReservation { source_pages, source_page_count, result_pages, operation_ids, entries, scratch, retained_operation_bytes, retained_result_bytes } = reservation;
        Self { source_pages: Some(source_pages), source_page_count, result_pages: Some(result_pages), operation_ids: Some(operation_ids), entries: Some(entries), scratch, retained_operation_bytes, retained_result_bytes, started: false }
    }

    pub fn close_step(&mut self) -> bool {
        self.started = true;
        if self.source_page_count != 0 {
            self.source_page_count -= 1;
            if let Some(owner) = self.source_pages.as_mut().and_then(|pages| pages.get_mut(self.source_page_count)).and_then(Option::take) {
                drop(owner);
            }
            return true;
        }
        if self.operation_ids.as_mut().is_some_and(|owners| owners.pop().is_some()) {
            return true;
        }
        if self.entries.as_mut().is_some_and(|owners| owners.pop().is_some()) {
            return true;
        }
        if let Some(owner) = self.result_pages.as_mut().and_then(Vec::pop) {
            drop(owner);
            return true;
        }
        if self.scratch.take().is_some() {
            return true;
        }
        if self.source_pages.take().is_some() {
            return true;
        }
        if self.operation_ids.take().is_some() {
            return true;
        }
        if self.entries.take().is_some() {
            return true;
        }
        if self.result_pages.take().is_some() {
            return true;
        }
        false
    }

    pub fn resume(&mut self) -> Option<HistoryReplayReservation> {
        if self.started {
            return None;
        }
        Some(HistoryReplayReservation {
            source_pages: self.source_pages.take()?,
            source_page_count: self.source_page_count,
            result_pages: self.result_pages.take()?,
            operation_ids: self.operation_ids.take()?,
            entries: self.entries.take()?,
            scratch: self.scratch.take(),
            retained_operation_bytes: self.retained_operation_bytes,
            retained_result_bytes: self.retained_result_bytes,
        })
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.source_pages.is_none() && self.result_pages.is_none() && self.operation_ids.is_none() && self.entries.is_none() && self.scratch.is_none()
    }
}

#[derive(Debug, PartialEq, Eq)]
struct HistoryReplayReservationConstructionToken {
    slot: usize,
    generation: u64,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct HistoryReplayReservationConstructionHandbackRejection {
    slot: usize,
    generation: u64,
}

struct HistoryReplayReservationConstructionSlot {
    generation: u64,
    occupied: bool,
    checked_out: bool,
    error: Option<DbError>,
    cursor: Option<HistoryReplayReservationCloseCursor>,
}

impl Default for HistoryReplayReservationConstructionSlot {
    fn default() -> Self {
        Self { generation: 0, occupied: false, checked_out: false, error: None, cursor: None }
    }
}

struct HistoryReplayReservationConstructionRegistry {
    slots: [HistoryReplayReservationConstructionSlot; HISTORY_REPLAY_CONSTRUCTION_SLOTS],
    next_generation: u64,
}

fn history_replay_reservation_construction_registry() -> &'static std::sync::Mutex<HistoryReplayReservationConstructionRegistry> {
    static REGISTRY: std::sync::OnceLock<std::sync::Mutex<HistoryReplayReservationConstructionRegistry>> = std::sync::OnceLock::new();
    REGISTRY.get_or_init(|| std::sync::Mutex::new(HistoryReplayReservationConstructionRegistry { slots: std::array::from_fn(|_| HistoryReplayReservationConstructionSlot::default()), next_generation: 1 }))
}

fn claim_history_replay_reservation_construction() -> Result<HistoryReplayReservationConstructionToken, DbError> {
    let mut registry = history_replay_reservation_construction_registry().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
    let Some(slot) = registry.slots.iter().position(|slot| !slot.occupied) else {
        return Err(DbError::Unavailable("history construction registry capacity exhausted".to_string()));
    };
    let generation = registry.next_generation;
    let Some(next_generation) = generation.checked_add(1) else {
        return Err(DbError::LimitExceeded("history construction generation"));
    };
    registry.next_generation = next_generation;
    registry.slots[slot] = HistoryReplayReservationConstructionSlot {
        generation,
        occupied: true,
        checked_out: true,
        error: None,
        cursor: Some(HistoryReplayReservationCloseCursor {
            source_pages: Some(Vec::new()),
            source_page_count: 0,
            result_pages: Some(Vec::new()),
            operation_ids: Some(Vec::new()),
            entries: Some(Vec::new()),
            scratch: Some(Vec::new()),
            retained_operation_bytes: 0,
            retained_result_bytes: 0,
            started: false,
        }),
    };
    Ok(HistoryReplayReservationConstructionToken { slot, generation })
}

fn handback_history_replay_reservation_construction(token: &HistoryReplayReservationConstructionToken) -> Result<(), HistoryReplayReservationConstructionHandbackRejection> {
    let mut registry = history_replay_reservation_construction_registry().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
    let Some(slot) = registry.slots.get_mut(token.slot) else {
        return Err(HistoryReplayReservationConstructionHandbackRejection { slot: token.slot, generation: token.generation });
    };
    if !slot.occupied || !slot.checked_out || slot.generation != token.generation || slot.cursor.is_none() {
        return Err(HistoryReplayReservationConstructionHandbackRejection { slot: token.slot, generation: token.generation });
    }
    slot.checked_out = false;
    Ok(())
}

fn release_history_replay_reservation_construction(token: &HistoryReplayReservationConstructionToken) -> bool {
    let mut registry = history_replay_reservation_construction_registry().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
    let Some(slot) = registry.slots.get_mut(token.slot) else {
        return false;
    };
    if !slot.occupied || !slot.checked_out || slot.generation != token.generation || slot.error.is_some() || slot.cursor.is_some() {
        return false;
    }
    slot.generation = 0;
    slot.occupied = false;
    slot.checked_out = false;
    true
}

#[cfg(test)]
pub(crate) fn take_history_replay_reservation_construction_fault(generation: u64) -> Option<HistoryReplayReservationConstructionFault> {
    let mut registry = history_replay_reservation_construction_registry().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
    let slot_index = registry.slots.iter().position(|slot| slot.occupied && !slot.checked_out && slot.generation == generation)?;
    let slot = &mut registry.slots[slot_index];
    slot.checked_out = true;
    Some(HistoryReplayReservationConstructionFault { token: Some(HistoryReplayReservationConstructionToken { slot: slot_index, generation }), unregistered_error: None })
}

struct HistoryReplayReservationConstructionBuilder {
    token: Option<HistoryReplayReservationConstructionToken>,
}

impl HistoryReplayReservationConstructionBuilder {
    fn new() -> Result<Self, HistoryReplayReservationConstructionFault> {
        let token = match claim_history_replay_reservation_construction() {
            Ok(token) => token,
            Err(error) => return Err(HistoryReplayReservationConstructionFault::unregistered(error)),
        };
        Ok(Self { token: Some(token) })
    }

    fn edit_cursor<T>(&mut self, edit: impl FnOnce(&mut HistoryReplayReservationCloseCursor) -> T) -> Option<T> {
        let token = self.token.as_ref()?;
        let mut registry = history_replay_reservation_construction_registry().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let slot = registry.slots.get_mut(token.slot)?;
        if !slot.occupied || !slot.checked_out || slot.generation != token.generation || slot.error.is_some() {
            return None;
        }
        slot.cursor.as_mut().map(edit)
    }

    fn read_cursor<T>(&self, read: impl FnOnce(&HistoryReplayReservationCloseCursor) -> T) -> Option<T> {
        let token = self.token.as_ref()?;
        let registry = history_replay_reservation_construction_registry().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let slot = registry.slots.get(token.slot)?;
        if !slot.occupied || !slot.checked_out || slot.generation != token.generation || slot.error.is_some() {
            return None;
        }
        slot.cursor.as_ref().map(read)
    }

    fn fault(mut self, error: impl FnOnce() -> DbError) -> HistoryReplayReservationConstructionFault {
        let Some(token) = self.token.take() else {
            return HistoryReplayReservationConstructionFault::unregistered(DbError::Unavailable("history construction token was unavailable".to_string()));
        };
        {
            let mut registry = history_replay_reservation_construction_registry().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            let Some(slot) = registry.slots.get_mut(token.slot) else {
                return HistoryReplayReservationConstructionFault { token: Some(token), unregistered_error: None };
            };
            if slot.occupied && slot.checked_out && slot.generation == token.generation && slot.error.is_none() && slot.cursor.is_some() {
                slot.error = Some(error());
            }
        }
        HistoryReplayReservationConstructionFault { token: Some(token), unregistered_error: None }
    }

    fn finish(mut self, retained_operation_bytes: u64, retained_result_bytes: u64) -> Result<HistoryReplayReservation, HistoryReplayReservationConstructionFault> {
        let Some(token) = self.token.take() else {
            return Err(HistoryReplayReservationConstructionFault::unregistered(DbError::Unavailable("history construction token was unavailable".to_string())));
        };
        let reservation = {
            let mut registry = history_replay_reservation_construction_registry().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            let Some(slot) = registry.slots.get_mut(token.slot) else {
                return Err(HistoryReplayReservationConstructionFault { token: Some(token), unregistered_error: None });
            };
            if !slot.occupied || !slot.checked_out || slot.generation != token.generation || slot.error.is_some() {
                return Err(HistoryReplayReservationConstructionFault { token: Some(token), unregistered_error: None });
            }
            let Some(mut cursor) = slot.cursor.take() else {
                return Err(HistoryReplayReservationConstructionFault { token: Some(token), unregistered_error: None });
            };
            cursor.retained_operation_bytes = retained_operation_bytes;
            cursor.retained_result_bytes = retained_result_bytes;
            let Some(reservation) = cursor.resume() else {
                slot.cursor = Some(cursor);
                return Err(HistoryReplayReservationConstructionFault { token: Some(token), unregistered_error: None });
            };
            slot.generation = 0;
            slot.occupied = false;
            slot.checked_out = false;
            reservation
        };
        Ok(reservation)
    }
}

impl Drop for HistoryReplayReservationConstructionBuilder {
    fn drop(&mut self) {
        if let Some(token) = self.token.as_ref() {
            let mut registry = history_replay_reservation_construction_registry().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            if let Some(slot) = registry.slots.get_mut(token.slot).filter(|slot| slot.occupied && slot.checked_out && slot.generation == token.generation && slot.error.is_none() && slot.cursor.is_some()) {
                slot.error = Some(DbError::Unavailable("history reservation construction unwound".to_string()));
            }
        }
        if let Some(token) = self.token.take() {
            let _ = handback_history_replay_reservation_construction(&token);
        }
    }
}

pub(crate) struct HistoryReplayReservationConstructionFault {
    token: Option<HistoryReplayReservationConstructionToken>,
    unregistered_error: Option<DbError>,
}

impl HistoryReplayReservationConstructionFault {
    fn unregistered(error: DbError) -> Self {
        Self { token: None, unregistered_error: Some(error) }
    }

    pub(crate) fn generation(&self) -> Option<u64> {
        self.token.as_ref().map(|token| token.generation)
    }

    pub(crate) fn take_error(&mut self) -> Option<DbError> {
        if self.unregistered_error.is_some() {
            return self.unregistered_error.take();
        }
        let token = self.token.as_ref()?;
        let mut registry = history_replay_reservation_construction_registry().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let slot = registry.slots.get_mut(token.slot)?;
        if !slot.occupied || !slot.checked_out || slot.generation != token.generation {
            return None;
        }
        slot.error.take()
    }

    pub(crate) fn close_step(&mut self) -> bool {
        if self.unregistered_error.take().is_some() {
            return true;
        }
        let Some(token) = self.token.as_ref() else {
            return false;
        };
        {
            let mut registry = history_replay_reservation_construction_registry().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            let Some(slot) = registry.slots.get_mut(token.slot) else {
                return false;
            };
            if !slot.occupied || !slot.checked_out || slot.generation != token.generation {
                return false;
            }
            if let Some(cursor) = slot.cursor.as_mut() {
                if cursor.close_step() {
                    return true;
                }
                if cursor.terminal_is_empty() {
                    slot.cursor = None;
                    return true;
                }
            }
            if slot.error.take().is_some() {
                return true;
            }
        }
        if release_history_replay_reservation_construction(token) {
            self.token = None;
            return true;
        }
        false
    }

    pub(crate) fn terminal_is_empty(&self) -> bool {
        self.token.is_none() && self.unregistered_error.is_none()
    }

    #[cfg(test)]
    fn retained_result_page_count(&self) -> usize {
        let Some(token) = self.token.as_ref() else {
            return 0;
        };
        let registry = history_replay_reservation_construction_registry().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        registry.slots.get(token.slot).filter(|slot| slot.occupied && slot.generation == token.generation).and_then(|slot| slot.cursor.as_ref()).and_then(|cursor| cursor.result_pages.as_ref()).map_or(0, Vec::len)
    }

    #[cfg(test)]
    fn retained_result_page_pointer(&self, index: usize) -> Option<*const u8> {
        let token = self.token.as_ref()?;
        let registry = history_replay_reservation_construction_registry().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        registry
            .slots
            .get(token.slot)
            .filter(|slot| slot.occupied && slot.generation == token.generation)
            .and_then(|slot| slot.cursor.as_ref())
            .and_then(|cursor| cursor.result_pages.as_ref())
            .and_then(|owners| owners.get(index))
            .and_then(Option::as_ref)
            .map(Vec::as_ptr)
    }

    #[cfg(test)]
    fn retained_error_pointer(&self) -> Option<*const u8> {
        if let Some(DbError::Unavailable(message)) = self.unregistered_error.as_ref() {
            return Some(message.as_ptr());
        }
        let token = self.token.as_ref()?;
        let registry = history_replay_reservation_construction_registry().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        match registry.slots.get(token.slot).filter(|slot| slot.occupied && slot.generation == token.generation)?.error.as_ref()? {
            DbError::Unavailable(message) => Some(message.as_ptr()),
            _ => None,
        }
    }
}

impl std::fmt::Debug for HistoryReplayReservationConstructionFault {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.debug_struct("HistoryReplayReservationConstructionFault").field("generation", &self.generation()).field("terminal_is_empty", &self.terminal_is_empty()).finish()
    }
}

impl Drop for HistoryReplayReservationConstructionFault {
    fn drop(&mut self) {
        if let Some(token) = self.token.take() {
            let _ = handback_history_replay_reservation_construction(&token);
        }
    }
}

impl Drop for HistoryReplayReservationCloseCursor {
    fn drop(&mut self) {
        assert!(self.terminal_is_empty() || std::thread::panicking(), "history replay reservation reached Drop before retained retirement or exact resume");
    }
}

#[derive(Default)]
struct HistoryPageSet {
    pages: Vec<Option<Vec<u8>>>,
    len: u64,
}

impl db_wal::WalImmutableByteSource for HistoryPageSet {
    fn byte_len(&self) -> usize {
        self.len as usize
    }

    fn fragment_at(&self, offset: usize, limit: usize) -> Result<&[u8], DbError> {
        if offset >= limit || limit as u64 > self.len {
            return Err(DbError::Corrupt("history immutable source range".to_string()));
        }
        let bytes = self.page_slice(offset as u64, (limit - offset) as u64)?;
        if bytes.is_empty() {
            return Err(DbError::Corrupt("history immutable source lost bytes".to_string()));
        }
        Ok(bytes)
    }
}

impl HistoryPageSet {
    fn byte(&self, offset: u64) -> Result<u8, DbError> {
        if offset >= self.len {
            return Err(DbError::Corrupt("history page cursor exceeded the segment".to_string()));
        }
        let page = usize::try_from(offset / HISTORY_REPLAY_PAGE_BYTES).map_err(|_| DbError::LimitExceeded("history page index"))?;
        let within = usize::try_from(offset % HISTORY_REPLAY_PAGE_BYTES).map_err(|_| DbError::LimitExceeded("history page offset"))?;
        self.pages.get(page).and_then(Option::as_ref).and_then(|bytes| bytes.get(within)).copied().ok_or_else(|| DbError::Corrupt("history page owner is missing admitted bytes".to_string()))
    }

    fn page_slice(&self, offset: u64, maximum: u64) -> Result<&[u8], DbError> {
        if offset >= self.len {
            return Ok(&[]);
        }
        let page = usize::try_from(offset / HISTORY_REPLAY_PAGE_BYTES).map_err(|_| DbError::LimitExceeded("history page index"))?;
        let within = usize::try_from(offset % HISTORY_REPLAY_PAGE_BYTES).map_err(|_| DbError::LimitExceeded("history page offset"))?;
        let bytes = self.pages.get(page).and_then(Option::as_ref).ok_or_else(|| DbError::Corrupt("history page owner is missing".to_string()))?;
        let available = bytes.len().checked_sub(within).ok_or_else(|| DbError::Corrupt("history page offset exceeds owner".to_string()))?;
        let take = available.min(usize::try_from(maximum).unwrap_or(usize::MAX));
        Ok(&bytes[within..within + take])
    }

    fn read_varint(&self, pos: &mut u64, end: u64) -> Result<u64, DbError> {
        let mut next = *pos;
        let value = db_wal::wal_read_canonical_varint(|| {
            if next >= end {
                return Err(DbError::Corrupt("history varint exceeds its admitted range".to_string()));
            }
            let byte = self.byte(next)?;
            next = next.checked_add(1).ok_or(DbError::LimitExceeded("history varint offset"))?;
            Ok(byte)
        })?;
        *pos = next;
        Ok(value)
    }

    fn read_range(&self, pos: &mut u64, end: u64, maximum: u64) -> Result<std::ops::Range<u64>, DbError> {
        let len = self.read_varint(pos, end)?;
        if len > maximum {
            return Err(DbError::LimitExceeded("history envelope field bytes"));
        }
        let start = *pos;
        let next = start.checked_add(len).ok_or(DbError::LimitExceeded("history envelope field range"))?;
        if next > end {
            return Err(DbError::Corrupt("history envelope field exceeds its frame payload".to_string()));
        }
        *pos = next;
        Ok(start..next)
    }

    fn copy_small<'a>(&self, range: std::ops::Range<u64>, scratch: &'a mut [u8]) -> Result<&'a [u8], DbError> {
        let len = range.end.checked_sub(range.start).ok_or(DbError::LimitExceeded("history copied range"))?;
        if len > HISTORY_REPLAY_PAGE_BYTES {
            return Err(DbError::LimitExceeded("history scratch page bytes"));
        }
        let first = self.page_slice(range.start, len)?;
        scratch[..first.len()].copy_from_slice(first);
        let remaining = usize::try_from(len).map_err(|_| DbError::LimitExceeded("history scratch page bytes"))?.checked_sub(first.len()).ok_or(DbError::LimitExceeded("history scratch page bytes"))?;
        if remaining != 0 {
            let offset = range.start.checked_add(first.len() as u64).ok_or(DbError::LimitExceeded("history scratch page offset"))?;
            let second = self.page_slice(offset, remaining as u64)?;
            if second.len() != remaining {
                return Err(DbError::Corrupt("history scratch page is truncated".to_string()));
            }
            scratch[first.len()..first.len() + remaining].copy_from_slice(second);
        }
        Ok(&scratch[..len as usize])
    }

    fn read_array<const N: usize>(&self, pos: &mut u64, end: u64, scratch: &mut [u8]) -> Result<[u8; N], DbError> {
        let next = pos.checked_add(N as u64).ok_or(DbError::LimitExceeded("history scalar range"))?;
        if next > end {
            return Err(DbError::Corrupt("history scalar exceeds its frame payload".to_string()));
        }
        let owner = self.copy_small(*pos..next, scratch)?;
        *pos = next;
        owner.try_into().map_err(|_| DbError::Corrupt("history scalar length mismatch".to_string()))
    }
}

enum HistoryEnvelopeField {
    MutationId,
    Document,
    Actor,
    DependencyCount,
    Dependency,
    ObservedFlag,
    Observed,
    TargetCount,
    TargetSegment,
    DiffSchema,
    DiffPayload,
    InverseSchema,
    InversePayload,
    ClockActor,
    ClockPhysical,
    ClockLogical,
    TrailingFlags,
    TransactionId,
    TransactionTool,
    Verb,
    Line,
    Done,
}

struct HistoryEnvelopeCursor {
    pos: u64,
    end: u64,
    field: HistoryEnvelopeField,
    dependencies: u64,
    target_segments: u64,
    verb: bool,
    line: bool,
    mutation_id: Option<std::ops::Range<u64>>,
}

impl HistoryEnvelopeCursor {
    fn new(pages: &HistoryPageSet, offset: u64, len: u64) -> Result<Self, DbError> {
        let end = offset.checked_add(len).ok_or(DbError::LimitExceeded("history command range"))?;
        if end > pages.len {
            return Err(DbError::Corrupt("history command range exceeds retained pages".to_string()));
        }
        Ok(Self { pos: offset, end, field: HistoryEnvelopeField::MutationId, dependencies: 0, target_segments: 0, verb: false, line: false, mutation_id: None })
    }

    fn finish(&self) -> Result<HistoryEnvelopeField, DbError> {
        if self.pos != self.end {
            return Err(DbError::Corrupt("history envelope has trailing bytes".to_string()));
        }
        Ok(HistoryEnvelopeField::Done)
    }

    fn skip_text(&mut self, pages: &HistoryPageSet, scratch: &mut [u8]) -> Result<(), DbError> {
        let range = pages.read_range(&mut self.pos, self.end, HISTORY_REPLAY_MAX_FIELD_BYTES as u64)?;
        let scratch = pages.copy_small(range, scratch)?;
        std::str::from_utf8(&scratch).map_err(|_| DbError::Corrupt("history envelope text is not valid utf-8".to_string()))?;
        Ok(())
    }

    fn step(&mut self, pages: &HistoryPageSet, scratch: &mut [u8], document: &ArtifactId) -> Result<Option<std::ops::Range<u64>>, DbError> {
        match self.field {
            HistoryEnvelopeField::MutationId => {
                let range = pages.read_range(&mut self.pos, self.end, HISTORY_REPLAY_MAX_FIELD_BYTES as u64)?;
                let value = pages.copy_small(range.clone(), scratch)?;
                std::str::from_utf8(value).map_err(|_| DbError::Corrupt("history operation id is not valid utf-8".to_string()))?;
                self.mutation_id = Some(range);
                self.field = HistoryEnvelopeField::Document;
            }
            HistoryEnvelopeField::Document => {
                let range = pages.read_range(&mut self.pos, self.end, HISTORY_REPLAY_MAX_FIELD_BYTES as u64)?;
                if pages.copy_small(range, scratch)? != document.0.as_bytes() {
                    return Err(DbError::Corrupt("history envelope document differs".to_string()));
                }
                self.field = HistoryEnvelopeField::Actor;
            }
            HistoryEnvelopeField::Actor => {
                self.skip_text(pages, scratch)?;
                self.field = HistoryEnvelopeField::DependencyCount;
            }
            HistoryEnvelopeField::DependencyCount => {
                self.dependencies = pages.read_varint(&mut self.pos, self.end)?;
                if self.dependencies > HISTORY_REPLAY_MAX_OPERATION_IDS as u64 {
                    return Err(DbError::LimitExceeded("history dependency item credit"));
                }
                self.field = if self.dependencies == 0 { HistoryEnvelopeField::ObservedFlag } else { HistoryEnvelopeField::Dependency };
            }
            HistoryEnvelopeField::Dependency => {
                self.skip_text(pages, scratch)?;
                self.dependencies -= 1;
                if self.dependencies == 0 {
                    self.field = HistoryEnvelopeField::ObservedFlag;
                }
            }
            HistoryEnvelopeField::ObservedFlag => {
                self.field = match pages.read_varint(&mut self.pos, self.end)? {
                    0 => HistoryEnvelopeField::TargetCount,
                    1 => HistoryEnvelopeField::Observed,
                    _ => return Err(DbError::Corrupt("history envelope observed flag is invalid".to_string())),
                };
            }
            HistoryEnvelopeField::Observed => {
                self.skip_text(pages, scratch)?;
                self.field = HistoryEnvelopeField::TargetCount;
            }
            HistoryEnvelopeField::TargetCount => {
                self.target_segments = pages.read_varint(&mut self.pos, self.end)?;
                if self.target_segments > HISTORY_REPLAY_MAX_OPERATION_IDS as u64 {
                    return Err(DbError::LimitExceeded("history target segment credit"));
                }
                self.field = if self.target_segments == 0 { HistoryEnvelopeField::DiffSchema } else { HistoryEnvelopeField::TargetSegment };
            }
            HistoryEnvelopeField::TargetSegment => {
                self.skip_text(pages, scratch)?;
                self.target_segments -= 1;
                if self.target_segments == 0 {
                    self.field = HistoryEnvelopeField::DiffSchema;
                }
            }
            HistoryEnvelopeField::DiffSchema => {
                self.skip_text(pages, scratch)?;
                self.field = HistoryEnvelopeField::DiffPayload;
            }
            HistoryEnvelopeField::DiffPayload => {
                pages.read_range(&mut self.pos, self.end, HISTORY_REPLAY_MAX_FRAME_BYTES)?;
                self.field = HistoryEnvelopeField::InverseSchema;
            }
            HistoryEnvelopeField::InverseSchema => {
                self.skip_text(pages, scratch)?;
                self.field = HistoryEnvelopeField::InversePayload;
            }
            HistoryEnvelopeField::InversePayload => {
                pages.read_range(&mut self.pos, self.end, HISTORY_REPLAY_MAX_FRAME_BYTES)?;
                self.field = HistoryEnvelopeField::ClockActor;
            }
            HistoryEnvelopeField::ClockActor => {
                pages.read_varint(&mut self.pos, self.end)?;
                self.field = HistoryEnvelopeField::ClockPhysical;
            }
            HistoryEnvelopeField::ClockPhysical => {
                pages.read_varint(&mut self.pos, self.end)?;
                self.field = HistoryEnvelopeField::ClockLogical;
            }
            HistoryEnvelopeField::ClockLogical => {
                pages.read_varint(&mut self.pos, self.end)?;
                self.field = HistoryEnvelopeField::TrailingFlags;
            }
            HistoryEnvelopeField::TrailingFlags => {
                let flags = pages.read_varint(&mut self.pos, self.end)?;
                if flags > 0b111 {
                    return Err(DbError::Corrupt("history envelope trailing flags are invalid".to_string()));
                }
                self.verb = flags & 0b10 != 0;
                self.line = flags & 0b100 != 0;
                self.field = match (flags & 0b01 != 0, self.verb, self.line) {
                    (true, _, _) => HistoryEnvelopeField::TransactionId,
                    (false, true, _) => HistoryEnvelopeField::Verb,
                    (false, false, true) => HistoryEnvelopeField::Line,
                    (false, false, false) => self.finish()?,
                };
            }
            HistoryEnvelopeField::TransactionId => {
                self.skip_text(pages, scratch)?;
                self.field = HistoryEnvelopeField::TransactionTool;
            }
            HistoryEnvelopeField::TransactionTool => {
                self.skip_text(pages, scratch)?;
                self.field = if self.verb { HistoryEnvelopeField::Verb } else if self.line { HistoryEnvelopeField::Line } else { self.finish()? };
            }
            HistoryEnvelopeField::Verb => {
                self.skip_text(pages, scratch)?;
                self.field = if self.line { HistoryEnvelopeField::Line } else { self.finish()? };
            }
            HistoryEnvelopeField::Line => {
                self.skip_text(pages, scratch)?;
                self.field = self.finish()?;
            }
            HistoryEnvelopeField::Done => return Ok(self.mutation_id.take()),
        }
        Ok(None)
    }
}

enum HistoryFrontierField {
    Document,
    Head,
    Commit,
    Chain,
    Epoch,
}

struct HistoryFrontierCursor {
    pos: u64,
    end: u64,
    field: HistoryFrontierField,
    head_seq: u64,
    commit_seq: u64,
    chain_hash: [u8; 32],
}

impl HistoryFrontierCursor {
    fn new(pages: &HistoryPageSet, offset: u64, len: u64) -> Result<Self, DbError> {
        let end = offset.checked_add(len).ok_or(DbError::LimitExceeded("history frontier range"))?;
        if end > pages.len {
            return Err(DbError::Corrupt("history frontier range exceeds retained pages".to_string()));
        }
        Ok(Self { pos: offset, end, field: HistoryFrontierField::Document, head_seq: 0, commit_seq: 0, chain_hash: [0; 32] })
    }

    fn step(&mut self, pages: &HistoryPageSet, scratch: &mut [u8], document: &ArtifactId) -> Result<Option<(u64, u64, [u8; 32], u64)>, DbError> {
        match self.field {
            HistoryFrontierField::Document => {
                let range = pages.read_range(&mut self.pos, self.end, HISTORY_REPLAY_MAX_FIELD_BYTES as u64)?;
                if pages.copy_small(range, scratch)? != document.0.as_bytes() {
                    return Err(DbError::Corrupt("history frontier document differs".to_string()));
                }
                self.field = HistoryFrontierField::Head;
            }
            HistoryFrontierField::Head => {
                self.head_seq = u64::from_le_bytes(pages.read_array(&mut self.pos, self.end, scratch)?);
                self.field = HistoryFrontierField::Commit;
            }
            HistoryFrontierField::Commit => {
                self.commit_seq = u64::from_le_bytes(pages.read_array(&mut self.pos, self.end, scratch)?);
                self.field = HistoryFrontierField::Chain;
            }
            HistoryFrontierField::Chain => {
                self.chain_hash = pages.read_array(&mut self.pos, self.end, scratch)?;
                self.field = HistoryFrontierField::Epoch;
            }
            HistoryFrontierField::Epoch => {
                let epoch = u64::from_le_bytes(pages.read_array(&mut self.pos, self.end, scratch)?);
                if self.pos != self.end {
                    return Err(DbError::Corrupt("history frontier has trailing bytes".to_string()));
                }
                return Ok(Some((self.head_seq, self.commit_seq, self.chain_hash, epoch)));
            }
        }
        Ok(None)
    }
}

type HistorySegmentLenFuture = Pin<Box<dyn Future<Output = Result<u64, DbError>> + Send + 'static>>;
type HistoryPageReadFuture = Pin<Box<dyn Future<Output = Result<db_storage::DbIoPages, DbError>> + Send + 'static>>;
type HistorySegmentListFuture = Pin<Box<dyn Future<Output = Result<db_storage::DbIoU64List, DbError>> + Send + 'static>>;

enum HistoryReplayPhase {
    Inventory { future: HistorySegmentListFuture },
    Probe,
    SegmentLen { index: u64, future: HistorySegmentLenFuture },
    PageStart { index: u64, len: u64, offset: u64 },
    PageRead { index: u64, len: u64, offset: u64, requested: u64, future: HistoryPageReadFuture },
    PageClose { index: u64, len: u64, offset: u64, retained: db_storage::DbIoPages },
    Verify { index: u64 },
    Frame { index: u64 },
    CommittedBody { index: u64 },
    Envelope { index: u64, cursor: HistoryEnvelopeCursor },
    CopyMutation { index: u64, range: std::ops::Range<u64>, copied: u64, result_start: u64 },
    Frontier { index: u64, cursor: HistoryFrontierCursor },
    Publish { index: u64, head_seq: u64, commit_seq: u64, chain_hash: [u8; 32], epoch: u64 },
    Retire,
    InventoryClose,
    FinalizeSuccess,
}

enum HistoryReplayTransition {
    InProgress,
    FaultRetire,
    Complete,
}

pub struct HistoryReplayFuture {
    storage: Arc<db_storage::DbBackend>,
    document: Arc<ArtifactId>,
    phase: Option<HistoryReplayPhase>,
    transition: HistoryReplayTransition,
    pages: HistoryPageSet,
    authenticated: Option<db_wal::WalAuthenticatedSource<HistoryPageSet>>,
    gate: Option<db_wal::WalTransactionGate>,
    previous_tip: db_wal::WalPriorChainTip,
    segments: Option<db_storage::DbIoU64List>,
    segment_ordinal: usize,
    body_index: usize,
    pending_frontier: Option<(u64, u64, [u8; 32], u64)>,
    page_count: usize,
    reservation: Option<HistoryReplayReservation>,
    reservation_close: Option<HistoryReplayReservationCloseCursor>,
    terminal_page: Option<Vec<u8>>,
    terminal_error: Option<DbError>,
    result_len: u64,
    pending_start: usize,
    operation_generation: u64,
    cancelled: Arc<std::sync::atomic::AtomicBool>,
    panic_before_transition_commit: bool,
}

impl HistoryReplayFuture {
    fn new(storage: Arc<db_storage::DbBackend>, document: ArtifactId, operation_generation: u64, cancelled: Arc<std::sync::atomic::AtomicBool>, mut reservation: HistoryReplayReservation) -> Self {
        let source_pages = std::mem::take(&mut reservation.source_pages);
        reservation.source_page_count = 0;
        let inventory_storage = storage.clone();
        let inventory_document = document.clone();
        Self {
            storage,
            document: Arc::new(document),
            phase: Some(HistoryReplayPhase::Inventory { future: Box::pin(async move { inventory_storage.wal().await.list_segments(&inventory_document).await }) }),
            transition: HistoryReplayTransition::InProgress,
            pages: HistoryPageSet { pages: source_pages, len: 0 },
            authenticated: None,
            gate: Some(db_wal::WalTransactionGate::new()),
            previous_tip: db_wal::WalPriorChainTip::Genesis,
            segments: None,
            segment_ordinal: 0,
            body_index: 0,
            pending_frontier: None,
            page_count: 0,
            reservation: Some(reservation),
            reservation_close: None,
            terminal_page: None,
            terminal_error: None,
            result_len: 0,
            pending_start: 0,
            operation_generation,
            cancelled,
            panic_before_transition_commit: false,
        }
    }

    pub fn request_close(&mut self, error: DbError) {
        if self.terminal_error.is_none() {
            self.terminal_error = Some(error);
        }
        if !matches!(self.transition, HistoryReplayTransition::Complete) {
            self.transition = HistoryReplayTransition::FaultRetire;
        }
    }

    pub fn close_step(&mut self) -> bool {
        if let Some(source) = self.authenticated.take() {
            self.pages = source.abort_into_source();
            return true;
        }
        if self.terminal_page.take().is_some() {
            return true;
        }
        if self.page_count != 0 {
            self.page_count -= 1;
            drop(self.pages.pages[self.page_count].take());
            return true;
        }
        if !self.pages.pages.is_empty() {
            drop(std::mem::take(&mut self.pages.pages));
            return true;
        }
        if let Some(segments) = self.segments.as_mut() {
            if segments.close_step() {
                return true;
            }
            if !segments.terminal_is_empty() {
                return true;
            }
            self.segments = None;
            return true;
        }
        if self.reservation_close.is_none() {
            if let Some(reservation) = self.reservation.take() {
                self.reservation_close = Some(HistoryReplayReservationCloseCursor::new(reservation));
                return true;
            }
        }
        if self.reservation_close.as_mut().is_some_and(HistoryReplayReservationCloseCursor::close_step) {
            return true;
        }
        if self.reservation_close.as_ref().is_some_and(HistoryReplayReservationCloseCursor::terminal_is_empty) {
            self.reservation_close = None;
            return true;
        }
        false
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.authenticated.is_none()
            && self.segments.is_none()
            && self.terminal_page.is_none()
            && self.page_count == 0
            && self.pages.pages.is_empty()
            && self.reservation.is_none()
            && self.reservation_close.is_none()
            && self.phase.is_none()
            && matches!(self.transition, HistoryReplayTransition::Complete)
    }

    fn begin_fault(&mut self, error: DbError) {
        self.request_close(error);
    }

    fn fail_pending(&mut self, error: DbError) {
        self.begin_fault(error);
    }

    fn copy_mutation_fragment(pages: &HistoryPageSet, reservation: &mut Option<HistoryReplayReservation>, range: &std::ops::Range<u64>, copied: u64, result_start: u64) -> Result<u64, DbError> {
        let remaining = range.end.checked_sub(range.start).and_then(|len| len.checked_sub(copied)).ok_or(DbError::LimitExceeded("history result copy range"))?;
        if remaining == 0 {
            return Ok(0);
        }
        let source_offset = range.start.checked_add(copied).ok_or(DbError::LimitExceeded("history result source offset"))?;
        let destination_offset = result_start.checked_add(copied).ok_or(DbError::LimitExceeded("history result destination offset"))?;
        let source = pages.page_slice(source_offset, remaining.min(HISTORY_REPLAY_PAGE_BYTES))?;
        let page_index = usize::try_from(destination_offset / HISTORY_REPLAY_PAGE_BYTES).map_err(|_| DbError::LimitExceeded("history result page index"))?;
        let within = usize::try_from(destination_offset % HISTORY_REPLAY_PAGE_BYTES).map_err(|_| DbError::LimitExceeded("history result page offset"))?;
        let reservation = reservation.as_mut().ok_or(DbError::Closed)?;
        let destination = reservation.result_pages.get_mut(page_index).and_then(Option::as_mut).ok_or_else(|| DbError::Corrupt("history result page owner is missing".to_string()))?;
        let take = source.len().min(destination.len().saturating_sub(within));
        if take == 0 {
            return Err(DbError::Corrupt("history result copy made no progress".to_string()));
        }
        destination[within..within + take].copy_from_slice(&source[..take]);
        Ok(take as u64)
    }

    fn finish_view(&mut self) -> Result<ArtifactHistoryView, DbError> {
        let Some(reservation) = self.reservation.as_ref() else {
            return Err(DbError::Closed);
        };
        let retained_bytes = reservation.retained_result_bytes;
        let retained_items = reservation
            .result_pages
            .len()
            .checked_add(reservation.operation_ids.len())
            .and_then(|items| items.checked_add(reservation.entries.len()))
            .and_then(|items| items.checked_add(1))
            .ok_or(DbError::LimitExceeded("history retained result items"));
        let retained_items = retained_items?;
        let Some(reservation) = self.reservation.take() else {
            return Err(DbError::Closed);
        };
        if reservation.scratch.is_some() || !reservation.source_pages.is_empty() {
            self.reservation = Some(reservation);
            return Err(DbError::Internal("history final view retained non-result owners".to_string()));
        }
        Ok(ArtifactHistoryView { entries: reservation.entries, operation_ids: reservation.operation_ids, result_pages: reservation.result_pages, result_len: self.result_len, retained_bytes, retained_items })
    }

    fn next(self: Pin<&mut Self>, context: &mut std::task::Context<'_>) -> std::task::Poll<Result<ArtifactHistoryView, DbError>> {
        let this = self.get_mut();
        if this.operation_generation == 0 {
            this.request_close(DbError::Closed);
        }
        if this.cancelled.load(std::sync::atomic::Ordering::Acquire) {
            this.request_close(DbError::Closed);
        }
        if matches!(this.transition, HistoryReplayTransition::Complete) {
            return std::task::Poll::Ready(Err(this.terminal_error.take().unwrap_or(DbError::Closed)));
        }
        if matches!(this.transition, HistoryReplayTransition::FaultRetire) {
            if this.phase.take().is_some() {
                context.waker().wake_by_ref();
                return std::task::Poll::Pending;
            }
            if this.close_step() {
                context.waker().wake_by_ref();
                return std::task::Poll::Pending;
            }
            this.transition = HistoryReplayTransition::Complete;
            return std::task::Poll::Ready(Err(this.terminal_error.take().unwrap_or(DbError::Closed)));
        }
        let mut next = None;
        let mut fault = None;
        let mut finalize = false;
        let Some(active) = this.phase.as_mut() else {
            this.request_close(DbError::Internal("history replay transition authority was missing".to_string()));
            context.waker().wake_by_ref();
            return std::task::Poll::Pending;
        };
        match active {
            HistoryReplayPhase::Inventory { future } => match future.as_mut().poll(context) {
                std::task::Poll::Pending => {}
                std::task::Poll::Ready(Err(error)) => fault = Some(error),
                std::task::Poll::Ready(Ok(segments)) => {
                    this.segments = Some(segments);
                    next = Some(HistoryReplayPhase::Probe);
                }
            },
            HistoryReplayPhase::Probe => {
                if let Some(error) = this.terminal_error.take() {
                    fault = Some(error);
                } else {
                    let segments = this.segments.as_ref().map(db_storage::DbIoU64List::as_slice).unwrap_or(&[]);
                    match segments.get(this.segment_ordinal).copied() {
                        None => next = Some(HistoryReplayPhase::InventoryClose),
                        Some(segment) if segments.first().and_then(|first| first.checked_add(this.segment_ordinal as u64)) != Some(segment) => fault = Some(DbError::Corrupt("history WAL inventory is not a dense retained suffix".to_string())),
                        Some(segment) => {
                            if this.segment_ordinal == 0 && segment != 0 {
                                this.previous_tip = db_wal::WalPriorChainTip::RetainedBoundary;
                            }
                            let storage = this.storage.clone();
                            let document = this.document.clone();
                            next = Some(HistoryReplayPhase::SegmentLen { index: segment, future: Box::pin(async move { storage.wal().await.segment_len(&document, segment).await }) });
                        }
                    }
                }
            }
            HistoryReplayPhase::SegmentLen { index, future } => match future.as_mut().poll(context) {
                std::task::Poll::Pending => {}
                std::task::Poll::Ready(Err(error)) => fault = Some(this.terminal_error.take().unwrap_or(error)),
                std::task::Poll::Ready(Ok(len)) => {
                    if let Some(error) = this.terminal_error.take() {
                        fault = Some(error);
                    } else if let Some(page_count) = len.checked_add(HISTORY_REPLAY_PAGE_BYTES - 1).map(|bytes| bytes / HISTORY_REPLAY_PAGE_BYTES) {
                        let inventory_bytes = this.segments.as_ref().map_or(0, db_storage::DbIoU64List::retained_bytes);
                        let simultaneous = this
                            .reservation
                            .as_ref()
                            .and_then(HistoryReplayReservation::retained_bytes)
                            .and_then(|bytes| bytes.checked_add(len))
                            .and_then(|bytes| bytes.checked_add(inventory_bytes))
                            .and_then(|bytes| bytes.checked_add(size_of::<Self>() as u64));
                        if len < protocol::format::HEADER_SIZE as u64 || page_count > HISTORY_REPLAY_SEGMENT_PAGES || simultaneous.is_none_or(|bytes| bytes > HISTORY_REPLAY_OPERATION_BYTES) {
                            fault = Some(DbError::LimitExceeded("history replay page/source byte credit"));
                        } else {
                            this.pages.len = len;
                            next = Some(HistoryReplayPhase::PageStart { index: *index, len, offset: 0 });
                        }
                    } else {
                        fault = Some(DbError::LimitExceeded("history segment page rounding"));
                    }
                }
            },
            HistoryReplayPhase::PageStart { index, len, offset } => {
                if offset == len {
                    if let Some(gate) = this.gate.take() {
                        this.authenticated = Some(db_wal::WalAuthenticatedSource::new(std::mem::take(&mut this.pages), gate, *index, this.previous_tip));
                        next = Some(HistoryReplayPhase::Verify { index: *index });
                    } else {
                        fault = Some(DbError::Closed);
                    }
                } else {
                    match len.checked_sub(*offset) {
                        Some(remaining) => {
                            let requested = remaining.min(HISTORY_REPLAY_PAGE_BYTES);
                            let storage = this.storage.clone();
                            let document = this.document.clone();
                            let (index, len, offset) = (*index, *len, *offset);
                            next = Some(HistoryReplayPhase::PageRead {
                                index,
                                len,
                                offset,
                                requested,
                                future: Box::pin(async move { storage.wal().await.read(&document, index, pack::ByteRange { offset, len: requested }).await }),
                            });
                        }
                        None => fault = Some(DbError::LimitExceeded("history page remaining bytes")),
                    }
                }
            }
            HistoryReplayPhase::PageRead { index, len, offset, requested, future } => match future.as_mut().poll(context) {
                std::task::Poll::Pending => {}
                std::task::Poll::Ready(Err(error)) => fault = Some(this.terminal_error.take().unwrap_or(error)),
                std::task::Poll::Ready(Ok(retained)) => {
                    let mut page = Vec::with_capacity(retained.len());
                    for fragment in retained.fragments() {
                        page.extend_from_slice(fragment);
                    }
                    let page = page.into_boxed_slice().into_vec();
                    if let Some(error) = this.terminal_error.take() {
                        this.terminal_page = Some(page);
                        fault = Some(error);
                    } else if page.len() as u64 != *requested || page.capacity() as u64 > HISTORY_REPLAY_PAGE_BYTES || this.page_count >= HISTORY_REPLAY_SEGMENT_PAGES as usize {
                        this.terminal_page = Some(page);
                        fault = Some(DbError::LimitExceeded("history backend page ownership"));
                    } else if let Some(next_offset) = offset.checked_add(*requested) {
                        this.pages.pages[this.page_count] = Some(page);
                        this.page_count += 1;
                        next = Some(HistoryReplayPhase::PageClose { index: *index, len: *len, offset: next_offset, retained });
                    } else {
                        this.terminal_page = Some(page);
                        fault = Some(DbError::LimitExceeded("history page offset"));
                    }
                }
            },
            HistoryReplayPhase::PageClose { index, len, offset, retained } => {
                if retained.terminal_is_empty() {
                    next = Some(HistoryReplayPhase::PageStart { index: *index, len: *len, offset: *offset });
                } else if let Err(error) = retained.close_step() {
                    fault = Some(error);
                }
            }
            HistoryReplayPhase::Verify { index } => {
                let result = db_wal::WalCursorControl::new(this.cancelled.clone(), std::time::Instant::now() + std::time::Duration::from_millis(8), 1)
                    .and_then(|mut control| this.authenticated.as_mut().ok_or(DbError::Closed)?.verify_step(&this.document, &mut control));
                match result {
                    Ok(true) => next = Some(HistoryReplayPhase::Frame { index: *index }),
                    Ok(false) => {}
                    Err(DbError::Unavailable(message)) if message == "wal cursor deadline reached" => {}
                    Err(error) => fault = Some(error),
                }
            }
            HistoryReplayPhase::Frame { index } => {
                let result =
                    db_wal::WalCursorControl::new(this.cancelled.clone(), std::time::Instant::now() + std::time::Duration::from_millis(8), 1).and_then(|mut control| this.authenticated.as_mut().ok_or(DbError::Closed)?.next_step(&mut control));
                match result {
                    Ok(db_wal::WalAuthenticatedStep::Yield) => {}
                    Ok(db_wal::WalAuthenticatedStep::Committed) => {
                        this.body_index = 0;
                        this.pending_frontier = None;
                        next = Some(HistoryReplayPhase::CommittedBody { index: *index });
                    }
                    Ok(db_wal::WalAuthenticatedStep::Done) => {
                        if let Some(source) = this.authenticated.take() {
                            match source.finish() {
                                Ok((pages, gate, tip)) => {
                                    this.pages = pages;
                                    this.gate = Some(gate);
                                    this.previous_tip = db_wal::WalPriorChainTip::Verified(tip);
                                    next = Some(HistoryReplayPhase::Retire);
                                }
                                Err(source) => {
                                    this.authenticated = Some(source);
                                    fault = Some(DbError::Corrupt("history source finished without authentication".to_string()));
                                }
                            }
                        } else {
                            fault = Some(DbError::Closed);
                        }
                    }
                    Err(DbError::Unavailable(message)) if message == "wal cursor deadline reached" => {}
                    Err(error) => fault = Some(error),
                }
            }
            HistoryReplayPhase::CommittedBody { index } => {
                if let Some(source) = this.authenticated.as_ref() {
                    if let Some(frame) = source.committed_frame(this.body_index) {
                        this.body_index += 1;
                        let (offset, len) = (frame.payload_start as u64, (frame.payload_end - frame.payload_start) as u64);
                        match frame.kind {
                            _ if this.pending_frontier.is_some() => fault = Some(DbError::Corrupt("history committed frontier is not terminal".to_string())),
                            db_wal::WAL_COMMAND => match HistoryEnvelopeCursor::new(source.source(), offset, len) {
                                Ok(cursor) => next = Some(HistoryReplayPhase::Envelope { index: *index, cursor }),
                                Err(error) => fault = Some(error),
                            },
                            db_wal::WAL_FRONTIER => match HistoryFrontierCursor::new(source.source(), offset, len) {
                                Ok(cursor) => next = Some(HistoryReplayPhase::Frontier { index: *index, cursor }),
                                Err(error) => fault = Some(error),
                            },
                            _ => {}
                        }
                    } else if let Some((head_seq, commit_seq, chain_hash, epoch)) = this.pending_frontier.take() {
                        next = Some(HistoryReplayPhase::Publish { index: *index, head_seq, commit_seq, chain_hash, epoch });
                    } else if this.reservation.as_ref().is_some_and(|owner| owner.operation_ids.len() != this.pending_start) {
                        fault = Some(DbError::Corrupt("history committed commands have no frontier".to_string()));
                    } else {
                        match this.authenticated.as_mut().ok_or(DbError::Closed).and_then(|source| source.finish_transaction()) {
                            Ok(()) => next = Some(HistoryReplayPhase::Frame { index: *index }),
                            Err(error) => fault = Some(error),
                        }
                    }
                } else {
                    fault = Some(DbError::Closed);
                }
            }
            HistoryReplayPhase::Envelope { index, cursor } => {
                let step = match this.reservation.as_mut().and_then(|owner| owner.scratch.as_mut()) {
                    Some(scratch) => this.authenticated.as_ref().ok_or(DbError::Closed).and_then(|source| cursor.step(source.source(), scratch, &this.document)),
                    None => Err(DbError::Closed),
                };
                match step {
                    Err(error) => fault = Some(error),
                    Ok(Some(range)) => {
                        let len = range.end.saturating_sub(range.start);
                        match this.reservation.as_ref().map_or(Err(DbError::Closed), |owner| owner.preflight_result_range(this.result_len, len)) {
                            Ok(_) => next = Some(HistoryReplayPhase::CopyMutation { index: *index, range, copied: 0, result_start: this.result_len }),
                            Err(error) => fault = Some(error),
                        }
                    }
                    Ok(None) => {}
                }
            }
            HistoryReplayPhase::CopyMutation { index, range, copied, result_start } => {
                match this.authenticated.as_ref().ok_or(DbError::Closed).and_then(|source| Self::copy_mutation_fragment(source.source(), &mut this.reservation, range, *copied, *result_start)) {
                    Err(error) => fault = Some(error),
                    Ok(0) => {
                        if let Some(len) = range.end.checked_sub(range.start).and_then(|value| u16::try_from(value).ok()) {
                            if let Some(reservation) = this.reservation.as_mut() {
                                reservation.operation_ids.push(HistoryTextRange { start: *result_start as u32, len });
                                this.result_len = *result_start + u64::from(len);
                                next = Some(HistoryReplayPhase::CommittedBody { index: *index });
                            } else {
                                fault = Some(DbError::Closed);
                            }
                        } else {
                            fault = Some(DbError::LimitExceeded("history operation id range"));
                        }
                    }
                    Ok(count) => *copied += count,
                }
            }
            HistoryReplayPhase::Frontier { index, cursor } => {
                let step = match this.reservation.as_mut().and_then(|owner| owner.scratch.as_mut()) {
                    Some(scratch) => this.authenticated.as_ref().ok_or(DbError::Closed).and_then(|source| cursor.step(source.source(), scratch, &this.document)),
                    None => Err(DbError::Closed),
                };
                match step {
                    Err(error) => fault = Some(error),
                    Ok(Some(frontier)) => {
                        this.pending_frontier = Some(frontier);
                        next = Some(HistoryReplayPhase::CommittedBody { index: *index });
                    }
                    Ok(None) => {}
                }
            }
            HistoryReplayPhase::Publish { index, head_seq, commit_seq, chain_hash, epoch } => {
                let operation_end = this.reservation.as_ref().map_or(this.pending_start, |owner| owner.operation_ids.len());
                if operation_end == this.pending_start {
                    next = Some(HistoryReplayPhase::Frame { index: *index });
                } else if this.reservation.as_ref().is_none_or(|owner| owner.entries.len() >= HISTORY_REPLAY_MAX_ENTRIES) {
                    fault = Some(DbError::LimitExceeded("history entry item credit"));
                } else {
                    let count = operation_end - this.pending_start;
                    let start = u16::try_from(this.pending_start);
                    let count = u16::try_from(count);
                    match (start, count, this.reservation.as_mut()) {
                        (Ok(operation_start), Ok(operation_count), Some(reservation)) => {
                            reservation.entries.push(ArtifactHistoryEntry { operation_start, operation_count, head_seq: *head_seq, commit_seq: *commit_seq, chain_hash: *chain_hash, epoch: *epoch });
                            this.pending_start = operation_end;
                            next = Some(HistoryReplayPhase::Frame { index: *index });
                        }
                        _ => fault = Some(DbError::LimitExceeded("history entry range")),
                    }
                }
                if fault.is_none() {
                    if let Err(error) = this.authenticated.as_mut().ok_or(DbError::Closed).and_then(|source| source.finish_transaction()) {
                        fault = Some(error);
                    }
                }
            }
            HistoryReplayPhase::Retire => {
                if this.page_count != 0 {
                    this.page_count -= 1;
                    drop(this.pages.pages[this.page_count].take());
                } else {
                    this.pages.len = 0;
                    this.segment_ordinal += 1;
                    next = Some(HistoryReplayPhase::Probe);
                }
            }
            HistoryReplayPhase::InventoryClose => {
                if let Some(segments) = this.segments.as_mut() {
                    segments.close_step();
                    if segments.terminal_is_empty() {
                        this.segments = None;
                    }
                } else {
                    next = Some(HistoryReplayPhase::FinalizeSuccess);
                }
            }
            HistoryReplayPhase::FinalizeSuccess => {
                if this.reservation.as_mut().and_then(|owner| owner.scratch.take()).is_some() {
                } else if !this.pages.pages.is_empty() {
                    drop(std::mem::take(&mut this.pages.pages));
                } else {
                    finalize = true;
                }
            }
        }
        if std::mem::take(&mut this.panic_before_transition_commit) {
            panic!("history replay transition panic fixture");
        }
        if let Some(error) = fault {
            if this.terminal_error.is_none() {
                this.terminal_error = Some(error);
            }
            this.transition = HistoryReplayTransition::FaultRetire;
        } else if finalize {
            match this.finish_view() {
                Ok(view) => {
                    this.phase = None;
                    this.transition = HistoryReplayTransition::Complete;
                    return std::task::Poll::Ready(Ok(view));
                }
                Err(error) => {
                    this.terminal_error.get_or_insert(error);
                    this.transition = HistoryReplayTransition::FaultRetire;
                }
            }
        } else if let Some(next) = next {
            this.phase = Some(next);
        }
        context.waker().wake_by_ref();
        std::task::Poll::Pending
    }
}

impl Future for HistoryReplayFuture {
    type Output = Result<ArtifactHistoryView, DbError>;

    fn poll(self: Pin<&mut Self>, context: &mut std::task::Context<'_>) -> std::task::Poll<Self::Output> {
        self.next(context)
    }
}

impl Drop for HistoryReplayFuture {
    fn drop(&mut self) {
        assert!(self.terminal_is_empty(), "history replay reached Drop before retained source/result/page retirement");
    }
}
//#endregion 🔖️HistoryReplay

//#region 🔖️Actor
/// 📨️ A `Send` message crossing `ArtifactAuthority`'s bounded mailbox.
pub enum ArtifactMessage {
    AppendDurableGroupDecision {
        record: store::durable_group::DurableOwnedGroupJournalRecordV1,
        cancelled: Arc<std::sync::atomic::AtomicBool>,
        now_ms: u64,
        reply: db_actor::ReplySender<Result<ArtifactDurableGroupJournalAppendV1, DbError>>,
    },
    RecoverDurableGroupDecisions {
        driver: ArtifactDurableGroupRecoveryDriverV1,
        reply: db_actor::ReplySender<Result<(), DbError>>,
    },
    Submit {
        batch: CommandBatch,
        options: SubmitOptions,
        now_ms: u64,
        reply: db_actor::ReplySender<Result<CommandReceipt, DbError>>,
    },
    Query {
        path: String,
        reply: db_actor::ReplySender<Result<Option<db_query::QueryBytes>, DbError>>,
    },
    Frontier {
        reply: db_actor::ReplySender<Frontier>,
    },
    CheckpointPublicationSnapshot {
        reply: db_actor::ReplySender<CheckpointPublicationSnapshot>,
    },
    /// 🔎️ Additive this revision — `db_engine`'s current `ArtifactHandle::query` goes
    /// through `Query { path, .. }` above and never constructs this variant, so adding it is safe.
    RunQuery {
        query: db_query::Query,
        consistency: db_query::Consistency,
        reply: db_actor::ReplySender<Result<db_query::QueryResult, DbError>>,
    },
    SnapshotNow {
        now_ms: u64,
        reply: db_actor::ReplySender<Result<u64, DbError>>,
    },
    History {
        operation_generation: u64,
        cancelled: Arc<std::sync::atomic::AtomicBool>,
        reservation: HistoryReplayReservation,
        reply: db_actor::ReplySender<Result<ArtifactHistoryView, DbError>>,
    },
    Compact {
        holder: db_storage::DbIoText,
        consolidate_snapshots: bool,
        budget: db_compact::CompactionBudget,
        now_ms: u64,
        cancelled: Arc<std::sync::atomic::AtomicBool>,
        reply: db_actor::ReplySender<Result<db_compact::CompactionReport, DbError>>,
    },
}

/// 🎭️ A live handle to one document's authority actor. Each admitted mailbox message wakes
/// one finite `WorkerPool` turn; no job waits for the next message and no authority owns an OS
/// thread. `db_state::PMap` uses `Arc`-shared HAMT nodes, making the engine movable between turns
/// without sharing mutable actor state or weakening its single-consumer mailbox semantics.
#[cfg(not(target_arch = "wasm32"))]
pub struct ArtifactAuthority {
    address: db_actor::Address<ArtifactMessage>,
    cancel: Arc<dyn Fn() + Send + Sync>,
    handoff: Arc<ArtifactRunnerHandoff>,
    retirement: Option<ArtifactRunnerRetirementReservation>,
    retirement_close: Option<Arc<dyn Fn() -> bool + Send + Sync>>,
    _pool_use: Arc<semio_framework_async::WorkerPoolUse>,
    done: std::sync::Mutex<Option<db_actor::ReplyReceiver<()>>>,
}

#[cfg(not(target_arch = "wasm32"))]
struct ArtifactDurableGroupJournalSinkV1 {
    address: db_actor::Address<ArtifactMessage>,
    now_ms: u64,
}

#[cfg(not(target_arch = "wasm32"))]
enum ArtifactDurableGroupJournalCommitStateV1 {
    NotSubmitted { decision_pack: Vec<u8>, decision_sha256: String },
    Awaiting(Pin<Box<db_actor::AskFuture<ArtifactMessage, Result<ArtifactDurableGroupJournalAppendV1, DbError>>>>),
    Rejected(String),
    Failed(String),
    Absent,
    Committed(store::durable_group::DurableOwnedGroupJournalReceiptV1),
    Empty,
}

#[cfg(not(target_arch = "wasm32"))]
struct ArtifactDurableGroupJournalCommitV1 {
    address: db_actor::Address<ArtifactMessage>,
    now_ms: u64,
    cancelled: Arc<std::sync::atomic::AtomicBool>,
    close_started: bool,
    state: ArtifactDurableGroupJournalCommitStateV1,
}

#[cfg(not(target_arch = "wasm32"))]
impl store::durable_group::DurableOwnedGroupJournalSinkV1 for ArtifactDurableGroupJournalSinkV1 {
    fn begin_commit(&mut self, decision_pack: Vec<u8>, decision_sha256: String) -> Box<dyn store::durable_group::DurableOwnedGroupJournalCommitV1> {
        Box::new(ArtifactDurableGroupJournalCommitV1 {
            address: self.address.clone(),
            now_ms: self.now_ms,
            cancelled: Arc::new(std::sync::atomic::AtomicBool::new(false)),
            close_started: false,
            state: ArtifactDurableGroupJournalCommitStateV1::NotSubmitted { decision_pack, decision_sha256 },
        })
    }
}

#[cfg(not(target_arch = "wasm32"))]
impl store::durable_group::DurableOwnedGroupJournalCommitV1 for ArtifactDurableGroupJournalCommitV1 {
    fn advance(&mut self, grant: store::ArtifactStoreOneItemGrant) -> Result<store::durable_group::DurableOwnedGroupJournalAdvanceV1, String> {
        use store::durable_group::DurableOwnedGroupJournalAdvanceV1;
        if !grant.permits_one() {
            return Ok(DurableOwnedGroupJournalAdvanceV1::Pending);
        }
        if matches!(self.state, ArtifactDurableGroupJournalCommitStateV1::NotSubmitted { .. }) {
            let state = std::mem::replace(&mut self.state, ArtifactDurableGroupJournalCommitStateV1::Empty);
            let ArtifactDurableGroupJournalCommitStateV1::NotSubmitted { decision_pack, decision_sha256 } = state else { unreachable!() };
            if self.cancelled.load(std::sync::atomic::Ordering::Acquire) {
                self.state = ArtifactDurableGroupJournalCommitStateV1::Absent;
            } else if grant.maximum_bytes < decision_pack.len() {
                self.state = ArtifactDurableGroupJournalCommitStateV1::Rejected("durable group journal grant is smaller than the canonical decision".to_string());
            } else {
                match store::durable_group::DurableOwnedGroupJournalRecordV1::admit(decision_pack, &decision_sha256) {
                    Ok(record) => {
                        let cancelled = self.cancelled.clone();
                        let future = self.address.ask(Priority::Command, |reply| ArtifactMessage::AppendDurableGroupDecision { record, cancelled, now_ms: self.now_ms, reply });
                        self.state = ArtifactDurableGroupJournalCommitStateV1::Awaiting(Box::pin(future));
                    }
                    Err(error) => self.state = ArtifactDurableGroupJournalCommitStateV1::Rejected(error.to_string()),
                }
            }
        }
        if let ArtifactDurableGroupJournalCommitStateV1::Awaiting(future) = &mut self.state {
            let polled = future.as_mut().poll(&mut std::task::Context::from_waker(std::task::Waker::noop()));
            if let std::task::Poll::Ready(result) = polled {
                self.state = match result {
                    Ok(Ok(ArtifactDurableGroupJournalAppendV1::Absent)) => ArtifactDurableGroupJournalCommitStateV1::Absent,
                    Ok(Ok(ArtifactDurableGroupJournalAppendV1::Rejected(error))) => ArtifactDurableGroupJournalCommitStateV1::Rejected(error.to_string()),
                    Ok(Ok(ArtifactDurableGroupJournalAppendV1::Committed(receipt))) => ArtifactDurableGroupJournalCommitStateV1::Committed(receipt),
                    Ok(Err(error)) | Err(error) => ArtifactDurableGroupJournalCommitStateV1::Failed(error.to_string()),
                };
            }
        }
        match &self.state {
            ArtifactDurableGroupJournalCommitStateV1::NotSubmitted { .. } | ArtifactDurableGroupJournalCommitStateV1::Awaiting(_) => Ok(DurableOwnedGroupJournalAdvanceV1::Pending),
            ArtifactDurableGroupJournalCommitStateV1::Rejected(reason) => Ok(DurableOwnedGroupJournalAdvanceV1::Rejected(reason.clone())),
            ArtifactDurableGroupJournalCommitStateV1::Failed(reason) => Err(reason.clone()),
            ArtifactDurableGroupJournalCommitStateV1::Absent => Ok(DurableOwnedGroupJournalAdvanceV1::Absent),
            ArtifactDurableGroupJournalCommitStateV1::Committed(receipt) => Ok(DurableOwnedGroupJournalAdvanceV1::Committed(receipt.clone())),
            ArtifactDurableGroupJournalCommitStateV1::Empty => Err("durable group journal owner is closed".to_string()),
        }
    }

    fn cancel(&mut self) {
        self.cancelled.store(true, std::sync::atomic::Ordering::Release);
    }

    fn begin_close(&mut self) {
        self.close_started = true;
    }

    fn close_step(&mut self, grant: store::ArtifactStoreOneItemGrant) -> Result<store::SnapshotRetirementStep, String> {
        use store::SnapshotRetirementStep;
        if matches!(self.state, ArtifactDurableGroupJournalCommitStateV1::Empty) {
            return Ok(SnapshotRetirementStep::Complete);
        }
        if !self.close_started || !grant.permits_one() {
            return Ok(SnapshotRetirementStep::Blocked);
        }
        if matches!(self.state, ArtifactDurableGroupJournalCommitStateV1::Awaiting(_) | ArtifactDurableGroupJournalCommitStateV1::Failed(_)) {
            return Ok(SnapshotRetirementStep::Blocked);
        }
        self.state = ArtifactDurableGroupJournalCommitStateV1::Empty;
        Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 })
    }

    fn terminal_is_empty(&self) -> bool {
        matches!(self.state, ArtifactDurableGroupJournalCommitStateV1::Empty)
    }
}

/// 🧳️ The runner owns its engine **boxed**, and every future it drives yields the box, never the
/// engine itself. `ArtifactEngine` measured ~529 KB by value (read off the
/// two `catch_unwind` shim frames of ticket 26/09/18 slice HS1's crash reports), and `run_turn`
/// carries each turn's result out through `std::panic::catch_unwind` → `do_call` → its own frame. A
/// debug build gives every one of those moves its own stack slot, so a by-value engine priced
/// `run_turn` at 3,598,608 B and the whole document-mount chain at 8,506,832 B — on pool workers
/// that own 2 MiB. Moving a pointer instead is what keeps the hub's first document socket from
/// aborting the process; see `📓️hs1-hub-pool-worker-stack-overflow.md`.
#[cfg(not(target_arch = "wasm32"))]
type ArtifactBuildFuture = Pin<Box<dyn Future<Output = Result<Box<ArtifactEngine>, ArtifactEngineOpenRejected>> + Send + 'static>>;

#[cfg(not(target_arch = "wasm32"))]
type ArtifactTurnFuture = Pin<Box<dyn Future<Output = Box<ArtifactEngine>> + Send + 'static>>;

#[cfg(not(target_arch = "wasm32"))]
enum ArtifactTurn {
    Future(ArtifactTurnFuture),
    CloseFlush(ArtifactTurnFuture),
    History { engine: Option<Box<ArtifactEngine>>, replay: HistoryReplayFuture, reply: Option<db_actor::ReplySender<Result<ArtifactHistoryView, DbError>>> },
}

#[cfg(not(target_arch = "wasm32"))]
const ARTIFACT_RUNNER_RETRY_MS: u64 = 1;
/// 🔁️ Automatic re-polls a faulted artifact-engine close receives before it waits for an explicit
/// re-admission (`ArtifactAuthority::readmit_close_retry`, `Database::shutdown`).
pub const ARTIFACT_CLOSE_RETRY_LIMIT: u8 = 8;
#[cfg(not(target_arch = "wasm32"))]
const ARTIFACT_CLOSE_RETRY_BASE_MS: u64 = 2;
#[cfg(not(target_arch = "wasm32"))]
const ARTIFACT_CLOSE_RETRY_CAP_MS: u64 = 512;

/// 🧭️ Where the bounded retry owner of a faulted artifact-engine close stands.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ArtifactCloseRetryState {
    Clear,
    Scheduled,
    Admitted,
    Exhausted,
    Cancelled,
}

/// 📈️ Progress of one faulted close: `attempts` counts automatic re-polls armed so far out of `limit`.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ArtifactCloseRetryProgress {
    pub state: ArtifactCloseRetryState,
    pub attempts: u8,
    pub limit: u8,
}

impl ArtifactCloseRetryProgress {
    /// 🧱️ True once no automatic retry remains: only an explicit re-admission can re-poll the close.
    pub fn is_blocked(&self) -> bool {
        matches!(self.state, ArtifactCloseRetryState::Exhausted | ArtifactCloseRetryState::Cancelled)
    }
}

#[cfg(not(target_arch = "wasm32"))]
struct ArtifactCloseRetry {
    state: ArtifactCloseRetryState,
    attempts: u8,
    generation: u64,
}

#[cfg(not(target_arch = "wasm32"))]
impl ArtifactCloseRetry {
    const fn clear() -> Self {
        Self { state: ArtifactCloseRetryState::Clear, attempts: 0, generation: 0 }
    }
}
#[cfg(not(target_arch = "wasm32"))]
const ARTIFACT_RUNNER_RETRY_LIMIT: u8 = 8;

#[cfg(not(target_arch = "wasm32"))]
#[repr(u8)]
#[derive(Clone, Copy, Eq, PartialEq)]
enum ArtifactRunnerDriver {
    RunnableIdle,
    Queued,
    Polling,
    PollingWake,
    Parked,
    ClosingReady,
    ClosingPolling,
    ClosingPollingWake,
    ClosingParked,
    Terminal,
}

#[cfg(not(target_arch = "wasm32"))]
struct ArtifactRunnerHandoff {
    pool: Arc<semio_framework_async::WorkerPool>,
    pool_use: std::sync::Mutex<Option<Arc<semio_framework_async::WorkerPoolUse>>>,
    terminal_job: std::sync::Mutex<Option<(semio_framework_async::WorkerSubmitErrorKind, semio_framework_async::Job)>>,
    close_runner: std::sync::Mutex<Option<Arc<dyn Fn() -> bool + Send + Sync>>>,
    retirement_maintenance: std::sync::Mutex<Option<(Arc<semio_framework_async::WorkerPool>, semio_framework_async::WorkerMaintenanceTicket)>>,
    close_error: std::sync::Mutex<Option<DbError>>,
    close_retry: std::sync::Mutex<ArtifactCloseRetry>,
    #[cfg(test)]
    close_faults: std::sync::atomic::AtomicUsize,
    #[cfg(test)]
    close_polls: std::sync::atomic::AtomicUsize,
    #[cfg(test)]
    retirement_turns: std::sync::atomic::AtomicUsize,
    active_history: std::sync::atomic::AtomicBool,
    driver: std::sync::atomic::AtomicU8,
    terminal: std::sync::atomic::AtomicBool,
}

#[cfg(not(target_arch = "wasm32"))]
impl Drop for ArtifactRunnerHandoff {
    fn drop(&mut self) {
        if self.pool_use.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take().is_some() {
            ARTIFACT_RUNNER_HANDOFF_POOL_USES.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
        }
    }
}

#[cfg(not(target_arch = "wasm32"))]
impl ArtifactRunnerHandoff {
    /// ⏲️ Arms the next bounded-backoff re-poll of a faulted close on the pool timer wheel. The
    /// timer admits exactly one re-poll through the retirement hook; stray wakes and coalesced
    /// maintenance requests never re-poll a faulted close.
    fn arm_close_retry(self: &Arc<Self>) {
        let mut retry = self.close_retry.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if !matches!(retry.state, ArtifactCloseRetryState::Clear | ArtifactCloseRetryState::Admitted) {
            return;
        }
        if retry.attempts >= ARTIFACT_CLOSE_RETRY_LIMIT {
            retry.state = ArtifactCloseRetryState::Exhausted;
            return;
        }
        let delay = ARTIFACT_CLOSE_RETRY_BASE_MS.checked_shl(u32::from(retry.attempts)).unwrap_or(ARTIFACT_CLOSE_RETRY_CAP_MS).min(ARTIFACT_CLOSE_RETRY_CAP_MS);
        let Some(deadline) = self.pool.now_ms().checked_add(delay) else {
            retry.state = ArtifactCloseRetryState::Exhausted;
            return;
        };
        retry.attempts += 1;
        retry.generation = retry.generation.wrapping_add(1);
        retry.state = ArtifactCloseRetryState::Scheduled;
        let generation = retry.generation;
        drop(retry);
        let handoff = Arc::downgrade(self);
        self.pool.callback_at(deadline, move || {
            if let Some(handoff) = handoff.upgrade() {
                handoff.admit_close_retry(generation);
            }
        });
    }

    fn admit_close_retry(&self, generation: u64) {
        let mut retry = self.close_retry.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if retry.state != ArtifactCloseRetryState::Scheduled || retry.generation != generation {
            return;
        }
        retry.state = ArtifactCloseRetryState::Admitted;
        drop(retry);
        self.request_retirement_maintenance();
    }

    fn clear_close_retry(&self) {
        *self.close_retry.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = ArtifactCloseRetry::clear();
    }

    /// 🚦️ A healthy close always polls; a faulted one polls only under its admitted retry.
    fn close_poll_admitted(&self) -> bool {
        let faulted = self.close_error.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_some();
        !faulted || self.close_retry.lock().unwrap_or_else(std::sync::PoisonError::into_inner).state == ArtifactCloseRetryState::Admitted
    }

    fn close_retry_progress(&self) -> Option<ArtifactCloseRetryProgress> {
        if self.close_error.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none() {
            return None;
        }
        let retry = self.close_retry.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        Some(ArtifactCloseRetryProgress { state: retry.state, attempts: retry.attempts, limit: ARTIFACT_CLOSE_RETRY_LIMIT })
    }

    /// 🔂️ Grants an exhausted or cancelled faulted close a fresh retry budget and admits one re-poll now.
    fn readmit_close_retry(&self) -> bool {
        if self.close_error.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none() {
            return false;
        }
        let mut retry = self.close_retry.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if !matches!(retry.state, ArtifactCloseRetryState::Exhausted | ArtifactCloseRetryState::Cancelled) {
            return false;
        }
        retry.attempts = 0;
        retry.generation = retry.generation.wrapping_add(1);
        retry.state = ArtifactCloseRetryState::Admitted;
        drop(retry);
        self.request_retirement_maintenance();
        true
    }

    /// 🛑️ Stops automatic re-polls of a faulted close; the exact runner stays retained for re-admission.
    fn cancel_close_retry(&self) -> bool {
        let mut retry = self.close_retry.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if !matches!(retry.state, ArtifactCloseRetryState::Scheduled | ArtifactCloseRetryState::Admitted) {
            return false;
        }
        retry.generation = retry.generation.wrapping_add(1);
        retry.state = ArtifactCloseRetryState::Cancelled;
        true
    }

    /// 🏁️ The runner's terminal transition: surrenders the handoff's pool use, publishes `Terminal`, then wakes a committed
    /// retirement cursor. Its last turn may have found the runner still closing and gone idle, and a terminal runner makes
    /// no further progress that would wake it — a stranded cursor keeps its `WorkerPoolUse` and a database shutdown waits in
    /// its `PoolUse` phase until the deadline.
    fn enter_terminal(&self) {
        if self.pool_use.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take().is_some() {
            ARTIFACT_RUNNER_HANDOFF_POOL_USES.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
        }
        self.driver.store(ArtifactRunnerDriver::Terminal as u8, std::sync::atomic::Ordering::Release);
        self.terminal.store(true, std::sync::atomic::Ordering::Release);
        self.request_retirement_maintenance();
    }

    fn request_retirement_maintenance(&self) {
        let owner = self.retirement_maintenance.lock().unwrap_or_else(std::sync::PoisonError::into_inner).clone();
        if let Some((pool, ticket)) = owner {
            let _ = pool.request_maintenance(ticket);
        }
    }
}

/// 📏️ Live document authorities one process holds at once: each reserves a retirement slot when it spawns, so dropping
/// it can always hand its runner to a retirement cursor. A slot is a fixed cell, never a pool maintenance hook — the pool
/// has a few dozen of those in all, and every authority used to take one, which capped a hub at about 60 open documents.
#[cfg(not(target_arch = "wasm32"))]
const ARTIFACT_RUNNER_RETIREMENT_SLOTS: usize = 4_096;

/// 🪝️ Worker pools that retire artifact runners at once: each gets ONE maintenance hook, shared by every retirement slot
/// reserved on it, installed with its first reservation and retired with its last.
#[cfg(not(target_arch = "wasm32"))]
const ARTIFACT_RUNNER_RETIREMENT_POOLS: usize = 256;

/// 🔑️ One pool's shared retirement hook: its row, the row's generation and the pool's maintenance ticket.
#[cfg(not(target_arch = "wasm32"))]
#[derive(Clone, Copy)]
struct ArtifactRunnerRetirementHookKey {
    row: usize,
    generation: u64,
    ticket: semio_framework_async::WorkerMaintenanceTicket,
}

#[cfg(not(target_arch = "wasm32"))]
struct ArtifactRunnerRetirementHook {
    generation: u64,
    pool: Arc<semio_framework_async::WorkerPool>,
    ticket: semio_framework_async::WorkerMaintenanceTicket,
    slots: usize,
}

#[cfg(not(target_arch = "wasm32"))]
static ARTIFACT_RUNNER_RETIREMENT_HOOKS: std::sync::Mutex<[Option<ArtifactRunnerRetirementHook>; ARTIFACT_RUNNER_RETIREMENT_POOLS]> = std::sync::Mutex::new([const { None }; ARTIFACT_RUNNER_RETIREMENT_POOLS]);

#[cfg(not(target_arch = "wasm32"))]
struct ArtifactRunnerRetirementCursor {
    generation: u64,
    close: Arc<dyn Fn() -> bool + Send + Sync>,
    handoff: Arc<ArtifactRunnerHandoff>,
    pool: Arc<semio_framework_async::WorkerPool>,
    _pool_use: Arc<semio_framework_async::WorkerPoolUse>,
    hook: ArtifactRunnerRetirementHookKey,
}

#[cfg(not(target_arch = "wasm32"))]
static ARTIFACT_RUNNER_RETIREMENTS: [std::sync::Mutex<Option<ArtifactRunnerRetirementCursor>>; ARTIFACT_RUNNER_RETIREMENT_SLOTS] = [const { std::sync::Mutex::new(None) }; ARTIFACT_RUNNER_RETIREMENT_SLOTS];
/// 🔬️ How many retained artifact-runner retirement cursors still hold the `WorkerPoolUse` clone a
/// non-terminal `ArtifactAuthority::drop` handed them. A database shutdown stuck in its `PoolUse`
/// phase with every other registry empty is blocked by exactly these.
#[cfg(not(target_arch = "wasm32"))]
pub fn artifact_runner_retirement_live_slots() -> usize {
    ARTIFACT_RUNNER_RETIREMENTS.iter().filter(|slot| slot.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_some()).count()
}

/// 📈️ The most advanced faulted-close retry among the dropped authorities retiring on `pool`: a blocked
/// (exhausted or cancelled) owner wins over one still retrying, so a shutdown can report exactly why
/// its pool use is still retained.
#[cfg(not(target_arch = "wasm32"))]
pub fn artifact_close_retry_progress(pool: &Arc<semio_framework_async::WorkerPool>) -> Option<ArtifactCloseRetryProgress> {
    ARTIFACT_RUNNER_RETIREMENTS
        .iter()
        .filter_map(|slot| slot.lock().unwrap_or_else(std::sync::PoisonError::into_inner).as_ref().filter(|owner| Arc::ptr_eq(&owner.pool, pool)).map(|owner| owner.handoff.clone()))
        .filter_map(|handoff| handoff.close_retry_progress())
        .max_by_key(|progress| (progress.is_blocked(), progress.attempts))
}

/// 🔂️ Re-admits every exhausted or cancelled faulted close retiring on `pool`; returns how many were re-admitted.
#[cfg(not(target_arch = "wasm32"))]
pub fn artifact_close_retry_readmit(pool: &Arc<semio_framework_async::WorkerPool>) -> usize {
    artifact_close_retry_handoffs(pool).into_iter().filter(|handoff| handoff.readmit_close_retry()).count()
}

/// 🛑️ Cancels every scheduled faulted-close retry retiring on `pool`; returns how many were cancelled.
#[cfg(not(target_arch = "wasm32"))]
pub fn artifact_close_retry_cancel(pool: &Arc<semio_framework_async::WorkerPool>) -> usize {
    artifact_close_retry_handoffs(pool).into_iter().filter(|handoff| handoff.cancel_close_retry()).count()
}

#[cfg(not(target_arch = "wasm32"))]
fn artifact_close_retry_handoffs(pool: &Arc<semio_framework_async::WorkerPool>) -> Vec<Arc<ArtifactRunnerHandoff>> {
    ARTIFACT_RUNNER_RETIREMENTS.iter().filter_map(|slot| slot.lock().unwrap_or_else(std::sync::PoisonError::into_inner).as_ref().filter(|owner| Arc::ptr_eq(&owner.pool, pool)).map(|owner| owner.handoff.clone())).collect()
}

#[cfg(not(target_arch = "wasm32"))]
static ARTIFACT_AUTHORITY_POOL_USES: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// 🔬️ How many LIVE `ArtifactAuthority` owners still hold the `WorkerPoolUse` clone
/// `spawn_with_pool_use` stored in `_pool_use`. A handoff surrenders its own clone at the runner's
/// terminal transition, so `artifact_runner_handoff_pool_use_live_slots() == 0` does NOT exclude a
/// live authority: the authority outlives its runner's terminal transition and keeps a second
/// clone until the authority itself is dropped.
#[cfg(not(target_arch = "wasm32"))]
pub fn artifact_authority_live_pool_uses() -> usize {
    ARTIFACT_AUTHORITY_POOL_USES.load(std::sync::atomic::Ordering::Acquire)
}

#[cfg(not(target_arch = "wasm32"))]
static ARTIFACT_RUNNER_HANDOFF_POOL_USES: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// 🔬️ How many LIVE artifact-runner handoffs still park the `WorkerPoolUse` clone
/// `spawn_with_pool_use` gave them. A handoff surrenders it only at the runner's terminal
/// transition, so an authority already gone from `open_artifacts` — and holding no retirement
/// cursor — can still pin the database's pool use through a runner that never went terminal. This
/// is the family no registry census can see, because handoffs live in their runner, not in a slot
/// table.
#[cfg(not(target_arch = "wasm32"))]
pub fn artifact_runner_handoff_pool_use_live_slots() -> usize {
    ARTIFACT_RUNNER_HANDOFF_POOL_USES.load(std::sync::atomic::Ordering::Acquire)
}

#[cfg(not(target_arch = "wasm32"))]
static ARTIFACT_RUNNER_RETIREMENT_GENERATIONS: [std::sync::atomic::AtomicU64; ARTIFACT_RUNNER_RETIREMENT_SLOTS] = [const { std::sync::atomic::AtomicU64::new(0) }; ARTIFACT_RUNNER_RETIREMENT_SLOTS];
#[cfg(not(target_arch = "wasm32"))]
static ARTIFACT_RUNNER_RETIREMENT_NEXT_GENERATION: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);

#[cfg(not(target_arch = "wasm32"))]
struct ArtifactRunnerRetirementReservation {
    index: usize,
    generation: u64,
    pool: Arc<semio_framework_async::WorkerPool>,
    hook: Option<ArtifactRunnerRetirementHookKey>,
}

/// 🪝️ Joins `pool`'s shared retirement hook, installing it for the pool's first reservation.
#[cfg(not(target_arch = "wasm32"))]
fn artifact_runner_retirement_hook_join(pool: &Arc<semio_framework_async::WorkerPool>, generation: u64) -> Result<ArtifactRunnerRetirementHookKey, DbError> {
    let mut hooks = ARTIFACT_RUNNER_RETIREMENT_HOOKS.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
    if let Some((row, hook)) = hooks.iter_mut().enumerate().find_map(|(row, hook)| hook.as_mut().filter(|hook| Arc::ptr_eq(&hook.pool, pool)).map(|hook| (row, hook))) {
        hook.slots += 1;
        return Ok(ArtifactRunnerRetirementHookKey { row, generation: hook.generation, ticket: hook.ticket });
    }
    let row = hooks.iter().position(Option::is_none).ok_or_else(|| DbError::Unavailable("artifact runner retirement pool capacity exhausted".to_string()))?;
    let ticket = pool
        .install_maintenance_hook(semio_framework_async::Lane::UserVisible, artifact_runner_retirement_step, [row as u64, generation])
        .map_err(|error| DbError::Unavailable(format!("artifact runner retirement maintenance admission: {error:?}")))?;
    hooks[row] = Some(ArtifactRunnerRetirementHook { generation, pool: pool.clone(), ticket, slots: 1 });
    Ok(ArtifactRunnerRetirementHookKey { row, generation, ticket })
}

/// 🪝️ One retirement slot of the hook's pool was released: the pool's last one removes the hook's row (the hook itself
/// retires on its next turn, or at once when it is not running).
#[cfg(not(target_arch = "wasm32"))]
fn artifact_runner_retirement_hook_leave(key: ArtifactRunnerRetirementHookKey) {
    let mut hooks = ARTIFACT_RUNNER_RETIREMENT_HOOKS.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
    let Some(hook) = hooks[key.row].as_mut().filter(|hook| hook.generation == key.generation) else { return };
    hook.slots -= 1;
    if hook.slots != 0 {
        return;
    }
    let retired = hooks[key.row].take().expect("checked artifact runner retirement hook");
    drop(hooks);
    let _ = retired.pool.remove_maintenance_hook(retired.ticket);
}

/// 🚥️ How one retirement slot's turn ended.
#[cfg(not(target_arch = "wasm32"))]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ArtifactRunnerRetirementTurn {
    Absent,
    Waiting,
    Faulted,
    Retired,
}

/// 🧹️ One turn of a pool's shared retirement hook: every slot of that pool whose authority was dropped before its runner
/// went terminal advances one close step. A reservation whose cursor is not committed yet is skipped — its commit requests
/// the hook again — so an early turn can never strand a cursor; the hook retires once its pool's last slot is released.
#[cfg(not(target_arch = "wasm32"))]
fn artifact_runner_retirement_step([row, generation]: [u64; 2]) -> semio_framework_async::WorkerMaintenanceStep {
    let Ok(row) = usize::try_from(row) else { return semio_framework_async::WorkerMaintenanceStep::Retire };
    let pool = {
        let hooks = ARTIFACT_RUNNER_RETIREMENT_HOOKS.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        match hooks.get(row).and_then(Option::as_ref) {
            Some(hook) if hook.generation == generation => hook.pool.clone(),
            _ => return semio_framework_async::WorkerMaintenanceStep::Retire,
        }
    };
    let mut faulted = false;
    for index in 0..ARTIFACT_RUNNER_RETIREMENT_SLOTS {
        if ARTIFACT_RUNNER_RETIREMENT_GENERATIONS[index].load(std::sync::atomic::Ordering::Acquire) == 0 {
            continue;
        }
        faulted |= artifact_runner_retirement_slot_turn(index, &pool) == ArtifactRunnerRetirementTurn::Faulted;
    }
    let hooks = ARTIFACT_RUNNER_RETIREMENT_HOOKS.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
    match hooks.get(row).and_then(Option::as_ref) {
        Some(hook) if hook.generation == generation && faulted => semio_framework_async::WorkerMaintenanceStep::Fault,
        Some(hook) if hook.generation == generation => semio_framework_async::WorkerMaintenanceStep::Idle,
        _ => semio_framework_async::WorkerMaintenanceStep::Retire,
    }
}

/// 🧹️ One close step of the cursor in slot `index` when it retires on `pool`: `Absent` for a free, uncommitted or
/// foreign slot, `Waiting` while the runner still closes, `Faulted` for a panicking or blocked close (the exact cursor
/// stays), `Retired` once terminal — the slot and its share of the pool's hook are released.
#[cfg(not(target_arch = "wasm32"))]
fn artifact_runner_retirement_slot_turn(index: usize, pool: &Arc<semio_framework_async::WorkerPool>) -> ArtifactRunnerRetirementTurn {
    let slot = &ARTIFACT_RUNNER_RETIREMENTS[index];
    let mut row = slot.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
    if !row.as_ref().is_some_and(|owner| Arc::ptr_eq(&owner.pool, pool)) {
        return ArtifactRunnerRetirementTurn::Absent;
    }
    let mut cursor = row.take();
    drop(row);
    let owner = cursor.as_mut().expect("checked artifact runner retirement owner");
    #[cfg(test)]
    owner.handoff.retirement_turns.fetch_add(1, std::sync::atomic::Ordering::AcqRel);
    let terminal = match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| (owner.close)())) {
        Ok(terminal) => terminal,
        Err(_) => {
            *slot.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = cursor;
            return ArtifactRunnerRetirementTurn::Faulted;
        }
    };
    if !terminal {
        let blocked = owner.handoff.close_retry_progress().is_some_and(|progress| progress.is_blocked());
        *slot.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = cursor;
        return if blocked { ArtifactRunnerRetirementTurn::Faulted } else { ArtifactRunnerRetirementTurn::Waiting };
    }
    owner.handoff.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
    owner.handoff.retirement_maintenance.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
    let hook = owner.hook;
    drop(cursor);
    ARTIFACT_RUNNER_RETIREMENT_GENERATIONS[index].store(0, std::sync::atomic::Ordering::Release);
    artifact_runner_retirement_hook_leave(hook);
    ArtifactRunnerRetirementTurn::Retired
}

#[cfg(not(target_arch = "wasm32"))]
impl ArtifactRunnerRetirementReservation {
    fn try_reserve(pool: Arc<semio_framework_async::WorkerPool>) -> Result<Self, DbError> {
        let generation = ARTIFACT_RUNNER_RETIREMENT_NEXT_GENERATION
            .try_update(std::sync::atomic::Ordering::AcqRel, std::sync::atomic::Ordering::Acquire, |generation| generation.checked_add(1).filter(|next| *next != 0))
            .map_err(|_| DbError::LimitExceeded("artifact runner retirement generation"))?;
        for (index, slot) in ARTIFACT_RUNNER_RETIREMENT_GENERATIONS.iter().enumerate() {
            if slot.compare_exchange(0, generation, std::sync::atomic::Ordering::AcqRel, std::sync::atomic::Ordering::Acquire).is_err() {
                continue;
            }
            let hook = match artifact_runner_retirement_hook_join(&pool, generation) {
                Ok(hook) => hook,
                Err(error) => {
                    slot.store(0, std::sync::atomic::Ordering::Release);
                    return Err(error);
                }
            };
            return Ok(Self { index, generation, pool, hook: Some(hook) });
        }
        Err(DbError::Unavailable("artifact runner retirement capacity exhausted".to_string()))
    }

    fn commit(mut self, close: Arc<dyn Fn() -> bool + Send + Sync>, handoff: Arc<ArtifactRunnerHandoff>, pool_use: Arc<semio_framework_async::WorkerPoolUse>) {
        let hook = self.hook.take().expect("artifact runner retirement reservation lost its hook");
        *ARTIFACT_RUNNER_RETIREMENTS[self.index].lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(ArtifactRunnerRetirementCursor { generation: self.generation, close, handoff: handoff.clone(), pool: self.pool.clone(), _pool_use: pool_use, hook });
        *handoff.retirement_maintenance.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some((self.pool.clone(), hook.ticket));
        let _ = self.pool.request_maintenance(hook.ticket);
    }
}

#[cfg(not(target_arch = "wasm32"))]
impl Drop for ArtifactRunnerRetirementReservation {
    fn drop(&mut self) {
        let Some(hook) = self.hook.take() else { return };
        ARTIFACT_RUNNER_RETIREMENT_GENERATIONS[self.index].store(0, std::sync::atomic::Ordering::Release);
        artifact_runner_retirement_hook_leave(hook);
    }
}

#[cfg(not(target_arch = "wasm32"))]
struct ArtifactRunnerClosePoll {
    handoff: Arc<ArtifactRunnerHandoff>,
}

#[cfg(not(target_arch = "wasm32"))]
impl Drop for ArtifactRunnerClosePoll {
    fn drop(&mut self) {
        use std::sync::atomic::Ordering;
        let faulted = self.handoff.close_error.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_some();
        loop {
            let driver = self.handoff.driver.load(Ordering::Acquire);
            if driver != ArtifactRunnerDriver::ClosingPolling as u8 && driver != ArtifactRunnerDriver::ClosingPollingWake as u8 {
                return;
            }
            let next = if driver == ArtifactRunnerDriver::ClosingPollingWake as u8 && !faulted { ArtifactRunnerDriver::ClosingReady } else { ArtifactRunnerDriver::ClosingParked };
            if self.handoff.driver.compare_exchange(driver, next as u8, Ordering::AcqRel, Ordering::Acquire).is_ok() {
                if next == ArtifactRunnerDriver::ClosingReady {
                    self.handoff.request_retirement_maintenance();
                }
                return;
            }
        }
    }
}

#[cfg(not(target_arch = "wasm32"))]
#[must_use = "terminal artifact runner jobs retain the only retry or close authority"]
pub struct ArtifactRunnerTerminalJob {
    handoff: Arc<ArtifactRunnerHandoff>,
    owner: Option<(semio_framework_async::WorkerSubmitErrorKind, semio_framework_async::Job)>,
}

#[cfg(not(target_arch = "wasm32"))]
struct ArtifactRunner {
    pool: Arc<semio_framework_async::WorkerPool>,
    address: db_actor::Address<ArtifactMessage>,
    receiver: db_actor::Receiver<ArtifactMessage>,
    generation: u64,
    builder: std::sync::Mutex<Option<ArtifactBuildFuture>>,
    engine: std::sync::Mutex<Option<Box<ArtifactEngine>>>,
    turn: std::sync::Mutex<Option<ArtifactTurn>>,
    ready: std::sync::Mutex<Option<db_actor::ReplySender<Result<(), ArtifactEngineOpenRejected>>>>,
    done: std::sync::Mutex<Option<db_actor::ReplySender<()>>>,
    handoff: Arc<ArtifactRunnerHandoff>,
    retry_job: std::sync::Mutex<Option<(semio_framework_async::Job, u8)>>,
    retry_armed: std::sync::atomic::AtomicBool,
    retry_generation: std::sync::atomic::AtomicU64,
    cancelled: std::sync::atomic::AtomicBool,
    close_driving: std::sync::atomic::AtomicBool,
    terminal: std::sync::atomic::AtomicBool,
}

/// ⏱️ How long one worker turn of a document authority keeps re-polling a self-woken turn
/// future before it hands the worker back to the pool.
#[cfg(not(target_arch = "wasm32"))]
const ARTIFACT_RUNNER_TURN_MICROS: u64 = 2_000;

#[cfg(not(target_arch = "wasm32"))]
struct ArtifactRunnerPoll {
    runner: Arc<ArtifactRunner>,
}

#[cfg(not(target_arch = "wasm32"))]
impl Drop for ArtifactRunnerPoll {
    fn drop(&mut self) {
        use std::sync::atomic::Ordering;
        loop {
            let driver = self.runner.handoff.driver.load(Ordering::Acquire);
            let cancelled = self.runner.cancelled.load(Ordering::Acquire);
            let faulted = self.runner.handoff.close_error.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_some();
            let next = match (driver, cancelled) {
                (value, true) if faulted && (value == ArtifactRunnerDriver::Polling as u8 || value == ArtifactRunnerDriver::PollingWake as u8) => ArtifactRunnerDriver::ClosingParked,
                (value, true) if value == ArtifactRunnerDriver::Polling as u8 || value == ArtifactRunnerDriver::PollingWake as u8 => ArtifactRunnerDriver::ClosingReady,
                (value, false) if value == ArtifactRunnerDriver::Polling as u8 => ArtifactRunnerDriver::RunnableIdle,
                (value, false) if value == ArtifactRunnerDriver::PollingWake as u8 => ArtifactRunnerDriver::Queued,
                _ => return,
            };
            if self.runner.handoff.driver.compare_exchange(driver, next as u8, Ordering::AcqRel, Ordering::Acquire).is_ok() {
                if next == ArtifactRunnerDriver::Queued {
                    self.runner.submit_scheduled();
                } else if next == ArtifactRunnerDriver::ClosingReady {
                    self.runner.handoff.request_retirement_maintenance();
                }
                return;
            }
        }
    }
}

#[cfg(not(target_arch = "wasm32"))]
struct ArtifactRunnerWake {
    runner: std::sync::Weak<ArtifactRunner>,
    generation: u64,
}

#[cfg(not(target_arch = "wasm32"))]
impl std::task::Wake for ArtifactRunnerWake {
    fn wake(self: Arc<Self>) {
        self.wake_by_ref();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        if let Some(runner) = self.runner.upgrade() {
            if self.generation == runner.generation {
                runner.schedule();
            }
        }
    }
}

#[cfg(not(target_arch = "wasm32"))]
impl ArtifactRunner {
    fn close_one(self: &Arc<Self>) -> bool {
        use std::sync::atomic::Ordering;
        self.cancelled.store(true, Ordering::Release);
        if !self.handoff.close_poll_admitted() {
            return self.terminal.load(Ordering::Acquire);
        }
        self.close_driving.store(true, Ordering::Release);
        loop {
            let driver = self.handoff.driver.load(Ordering::Acquire);
            if driver == ArtifactRunnerDriver::Terminal as u8
                || driver == ArtifactRunnerDriver::Polling as u8
                || driver == ArtifactRunnerDriver::PollingWake as u8
                || driver == ArtifactRunnerDriver::ClosingReady as u8
                || driver == ArtifactRunnerDriver::ClosingPolling as u8
                || driver == ArtifactRunnerDriver::ClosingPollingWake as u8
            {
                break;
            }
            if self.handoff.driver.compare_exchange(driver, ArtifactRunnerDriver::ClosingReady as u8, Ordering::AcqRel, Ordering::Acquire).is_ok() {
                break;
            }
        }
        let generation = self.generation;
        let witness = self.clone();
        self.clone().run_turn(generation, true);
        let closed = witness.terminal.load(Ordering::Acquire);
        witness.close_driving.store(false, Ordering::Release);
        closed
    }

    fn retained_terminal_job(self: &Arc<Self>, kind: semio_framework_async::WorkerSubmitErrorKind) -> (semio_framework_async::WorkerSubmitErrorKind, semio_framework_async::Job) {
        let runner = self.clone();
        let generation = self.generation;
        (kind, Box::new(move || runner.run_turn(generation, false)))
    }

    fn park_terminal_job(self: &Arc<Self>, kind: semio_framework_async::WorkerSubmitErrorKind) {
        use std::sync::atomic::Ordering;
        let mut terminal = self.handoff.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if terminal.is_some() {
            return;
        }
        loop {
            let driver = self.handoff.driver.load(Ordering::Acquire);
            if driver != ArtifactRunnerDriver::RunnableIdle as u8 && driver != ArtifactRunnerDriver::Queued as u8 {
                return;
            }
            if self.handoff.driver.compare_exchange(driver, ArtifactRunnerDriver::Parked as u8, Ordering::AcqRel, Ordering::Acquire).is_ok() {
                *terminal = Some(self.retained_terminal_job(kind));
                return;
            }
        }
    }

    fn schedule(self: &Arc<Self>) {
        use std::sync::atomic::Ordering;
        loop {
            let driver = self.handoff.driver.load(Ordering::Acquire);
            if driver == ArtifactRunnerDriver::RunnableIdle as u8 {
                if self.handoff.driver.compare_exchange(driver, ArtifactRunnerDriver::Queued as u8, Ordering::AcqRel, Ordering::Acquire).is_ok() {
                    self.submit_scheduled();
                    return;
                }
            } else if driver == ArtifactRunnerDriver::Polling as u8 {
                if self.handoff.driver.compare_exchange(driver, ArtifactRunnerDriver::PollingWake as u8, Ordering::AcqRel, Ordering::Acquire).is_ok() {
                    return;
                }
            } else if driver == ArtifactRunnerDriver::ClosingPolling as u8 {
                if self.handoff.driver.compare_exchange(driver, ArtifactRunnerDriver::ClosingPollingWake as u8, Ordering::AcqRel, Ordering::Acquire).is_ok() {
                    return;
                }
            } else if driver == ArtifactRunnerDriver::ClosingParked as u8 {
                if self.handoff.close_error.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_some() {
                    return;
                }
                if self.handoff.driver.compare_exchange(driver, ArtifactRunnerDriver::ClosingReady as u8, Ordering::AcqRel, Ordering::Acquire).is_ok() {
                    self.handoff.request_retirement_maintenance();
                    return;
                }
            } else {
                return;
            }
        }
    }

    fn submit_scheduled(self: &Arc<Self>) {
        let runner = Arc::downgrade(self);
        let generation = self.generation;
        self.submit_exact(
            Box::new(move || {
                if let Some(runner) = runner.upgrade() {
                    if runner.generation == generation {
                        runner.run_turn(generation, false);
                    }
                }
            }),
            0,
        );
    }

    fn submit_exact(self: &Arc<Self>, job: semio_framework_async::Job, attempt: u8) {
        match self.pool.try_submit(semio_framework_async::Lane::UserVisible, job) {
            Ok(()) => {}
            Err(error) => match worker_submit_retry_attempt(error.kind(), attempt, ARTIFACT_RUNNER_RETRY_LIMIT) {
                Some(next) => {
                    *self.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some((error.into_job(), next));
                    self.arm_retry();
                }
                None => {
                    let kind = error.kind();
                    let job = error.into_job();
                    if let Some(ready) = self.ready.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
                        drop(job);
                        ready.send(Err(ArtifactEngineOpenRejected::BeforeWal(DbError::Unavailable(format!("artifact authority WorkerPool submission failed: {kind:?}")))));
                        self.finish();
                    } else {
                        drop(job);
                        self.park_terminal_job(kind);
                    }
                }
            },
        }
    }

    fn arm_retry(self: &Arc<Self>) {
        use std::sync::atomic::Ordering;
        if self.retry_armed.compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return;
        }
        let generation = match self.retry_generation.try_update(Ordering::AcqRel, Ordering::Acquire, |generation| generation.checked_add(1).filter(|next| *next != 0)) {
            Ok(previous) => match previous.checked_add(1) {
                Some(generation) => generation,
                None => {
                    self.terminalize_retry_authority("artifact runner retry generation exhausted");
                    return;
                }
            },
            Err(_) => {
                self.terminalize_retry_authority("artifact runner retry generation exhausted");
                return;
            }
        };
        let Some(deadline) = self.pool.now_ms().checked_add(ARTIFACT_RUNNER_RETRY_MS) else {
            self.terminalize_retry_authority("artifact runner retry deadline exhausted");
            return;
        };
        let runner = self.clone();
        self.pool.callback_at(deadline, move || {
            if generation != runner.retry_generation.load(Ordering::Acquire) {
                return;
            }
            runner.retry_armed.store(false, Ordering::Release);
            let retry = runner.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
            if let Some((job, attempt)) = retry {
                if runner.cancelled.load(Ordering::Acquire) {
                    drop(job);
                    runner.park_terminal_job(semio_framework_async::WorkerSubmitErrorKind::Saturated);
                } else {
                    runner.submit_exact(job, attempt);
                }
            }
        });
    }

    fn terminalize_retry_authority(self: &Arc<Self>, detail: &'static str) {
        self.retry_armed.store(false, std::sync::atomic::Ordering::Release);
        let retained = self.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
        if let Some((job, attempt)) = retained {
            if self.handoff.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none() {
                drop(job);
                self.park_terminal_job(semio_framework_async::WorkerSubmitErrorKind::Saturated);
            } else {
                *self.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some((job, attempt));
            }
        }
        if let Some(ready) = self.ready.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
            ready.send(Err(ArtifactEngineOpenRejected::BeforeWal(DbError::Unavailable(detail.to_string()))));
            self.finish();
        }
    }

    fn cancel(self: &Arc<Self>) {
        self.cancelled.store(true, std::sync::atomic::Ordering::Release);
        self.schedule();
    }

    fn finish(self: &Arc<Self>) {
        if self.turn.lock().unwrap_or_else(std::sync::PoisonError::into_inner).as_ref().is_some_and(|turn| matches!(turn, ArtifactTurn::History { replay, .. } if !replay.terminal_is_empty())) {
            return;
        }
        {
            let mut engine = self.engine.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            if engine.as_ref().is_some_and(|owner| owner.close_flush_pending()) {
                let mut turn = self.turn.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
                if turn.is_none() {
                    let mut owner = engine.take().expect("checked artifact engine close-flush owner");
                    drop(engine);
                    *turn = Some(ArtifactTurn::CloseFlush(Box::pin(async move {
                        let _ = owner.close_flush().await;
                        owner
                    })));
                    drop(turn);
                    self.schedule();
                    return;
                }
            }
            if let Some(owner) = engine.as_mut() {
                #[cfg(test)]
                {
                    self.handoff.close_polls.fetch_add(1, std::sync::atomic::Ordering::AcqRel);
                    if self.handoff.close_faults.try_update(std::sync::atomic::Ordering::AcqRel, std::sync::atomic::Ordering::Acquire, |faults| faults.checked_sub(1)).is_ok() {
                        drop(engine);
                        self.record_close_fault(DbError::Io("injected artifact engine close fault".to_string()));
                        return;
                    }
                }
                let waker = std::task::Waker::from(Arc::new(ArtifactRunnerWake { runner: Arc::downgrade(self), generation: self.generation }));
                match owner.poll_close(&mut std::task::Context::from_waker(&waker)) {
                    std::task::Poll::Pending => {
                        drop(engine);
                        self.clear_close_fault();
                        return;
                    }
                    std::task::Poll::Ready(Ok(())) => {
                        engine.take();
                        self.clear_close_fault();
                    }
                    std::task::Poll::Ready(Err(error)) => {
                        drop(engine);
                        self.record_close_fault(error);
                        return;
                    }
                }
            }
        }
        if !self.terminal.swap(true, std::sync::atomic::Ordering::AcqRel) {
            let builder = self.builder.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
            if builder.is_none() {
                let turn = self.turn.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
                drop(turn);
            }
            self.handoff.enter_terminal();
            if let Some(done) = self.done.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
                done.send(());
            }
        }
    }

    fn record_close_fault(self: &Arc<Self>, error: DbError) {
        *self.handoff.close_error.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(error);
        self.handoff.arm_close_retry();
    }

    fn clear_close_fault(&self) {
        if self.handoff.close_error.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take().is_some() {
            self.handoff.clear_close_retry();
        }
    }

    fn start_turn(engine: Box<ArtifactEngine>, message: ArtifactMessage) -> ArtifactTurn {
        match message {
            ArtifactMessage::History { operation_generation, cancelled, reservation, reply } => {
                let replay = engine.history_replay(operation_generation, cancelled, reservation);
                ArtifactTurn::History { engine: Some(engine), replay, reply: Some(reply) }
            }
            // 🪜️ One boxed coroutine PER message kind, never one coroutine with a ten-arm `match`
            // inside it. A coroutine's frame is the SUM of its suspend points' live locals, and a
            // debug build overlaps nothing: with all ten engine methods awaited inside a single
            // async block, `start_turn::{closure}` reserved **10,711,040 B** and the runner entered
            // it twice, which is 20.4 MiB of the 21,520,944 B that aborted three hub laws
            // (ticket 26/09/18 slice HS1, `🐍️hs1-frame-sizes.py` over the nextest crash reports).
            // Splitting the match OUT of the async block turns that sum into a max: each arm's
            // coroutine holds exactly one engine-method future, and `ArtifactTurnFuture` erases them
            // all to the same type, so nothing downstream changes.
            ArtifactMessage::AppendDurableGroupDecision { record, cancelled, now_ms, reply } => ArtifactTurn::Future(Box::pin(async move {
                let mut engine = engine;
                reply.send(engine.append_durable_group_decision(record, cancelled, now_ms).await);
                engine
            })),
            ArtifactMessage::RecoverDurableGroupDecisions { driver, reply } => ArtifactTurn::Future(Box::pin(async move {
                let mut engine = engine;
                reply.send(engine.recover_durable_group_decisions(driver).await);
                engine
            })),
            ArtifactMessage::Submit { batch, options, now_ms, reply } => ArtifactTurn::Future(Box::pin(async move {
                let mut engine = engine;
                reply.send(engine.submit(batch, options, now_ms).await);
                engine.park_writer();
                let _ = engine.maintain_index().await;
                engine
            })),
            ArtifactMessage::Query { path, reply } => ArtifactTurn::Future(Box::pin(async move {
                reply.send(engine.get(&path).await);
                engine
            })),
            ArtifactMessage::Frontier { reply } => ArtifactTurn::Future(Box::pin(async move {
                reply.send(engine.frontier().await);
                engine
            })),
            ArtifactMessage::CheckpointPublicationSnapshot { reply } => ArtifactTurn::Future(Box::pin(async move {
                reply.send(engine.checkpoint_publication_snapshot().await);
                engine
            })),
            ArtifactMessage::RunQuery { query, consistency, reply } => ArtifactTurn::Future(Box::pin(async move {
                reply.send(engine.query(query, consistency).await);
                engine
            })),
            ArtifactMessage::SnapshotNow { now_ms, reply } => ArtifactTurn::Future(Box::pin(async move {
                reply.send(engine.snapshot_now(now_ms).await);
                engine
            })),
            ArtifactMessage::Compact { holder, consolidate_snapshots, budget, now_ms, cancelled, reply } => ArtifactTurn::Future(Box::pin(async move {
                let mut engine = engine;
                reply.send(engine.compact_retained(holder, consolidate_snapshots, budget, now_ms, cancelled).await);
                engine
            })),
        }
    }

    /// 🔁️ Keeps polling in this worker turn when the future woke itself while it was being
    /// polled (a cooperative yield, a storage step that completed inline) and the turn budget
    /// remains: every such wake used to cost a full worker-pool round trip.
    fn repoll_within_turn(&self, turn_ends: std::time::Instant) -> bool {
        use std::sync::atomic::Ordering;
        std::time::Instant::now() < turn_ends
            && !self.cancelled.load(Ordering::Acquire)
            && self.handoff.driver.compare_exchange(ArtifactRunnerDriver::PollingWake as u8, ArtifactRunnerDriver::Polling as u8, Ordering::AcqRel, Ordering::Acquire).is_ok()
    }

    fn run_turn(self: Arc<Self>, generation: u64, direct_close: bool) {
        use std::panic::AssertUnwindSafe;
        use std::sync::atomic::Ordering;

        if generation != self.generation || self.terminal.load(Ordering::Acquire) {
            return;
        }
        let (_close_poll, _poll) = if direct_close {
            if self.handoff.driver.compare_exchange(ArtifactRunnerDriver::ClosingReady as u8, ArtifactRunnerDriver::ClosingPolling as u8, Ordering::AcqRel, Ordering::Acquire).is_err() {
                return;
            }
            (Some(ArtifactRunnerClosePoll { handoff: self.handoff.clone() }), None)
        } else if self.handoff.driver.compare_exchange(ArtifactRunnerDriver::Queued as u8, ArtifactRunnerDriver::Polling as u8, Ordering::AcqRel, Ordering::Acquire).is_ok() {
            (None, Some(ArtifactRunnerPoll { runner: self.clone() }))
        } else {
            return;
        };
        if self.cancelled.load(Ordering::Acquire) {
            let mut turn = self.turn.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            match turn.as_mut() {
                Some(ArtifactTurn::History { replay, .. }) => replay.request_close(DbError::Closed),
                Some(ArtifactTurn::CloseFlush(_)) => {}
                _ => {
                    drop(turn);
                    self.finish();
                    return;
                }
            }
        }

        let waker = std::task::Waker::from(Arc::new(ArtifactRunnerWake { runner: Arc::downgrade(&self), generation }));
        let mut context = std::task::Context::from_waker(&waker);
        let turn_ends = std::time::Instant::now() + std::time::Duration::from_micros(ARTIFACT_RUNNER_TURN_MICROS);

        let mut builder = self.builder.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if let Some(future) = builder.as_mut() {
            let polled = loop {
                let polled = std::panic::catch_unwind(AssertUnwindSafe(|| future.as_mut().poll(&mut context)));
                if !matches!(polled, Ok(std::task::Poll::Pending)) || !self.repoll_within_turn(turn_ends) {
                    break polled;
                }
            };
            match polled {
                Ok(std::task::Poll::Pending) => return,
                Ok(std::task::Poll::Ready(Ok(engine))) => {
                    builder.take();
                    drop(builder);
                    engine.park_writer();
                    *self.engine.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(engine);
                    if let Some(ready) = self.ready.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
                        ready.send(Ok(()));
                    }
                    if self.address.has_messages() {
                        self.schedule();
                    }
                    return;
                }
                Ok(std::task::Poll::Ready(Err(error))) => {
                    builder.take();
                    drop(builder);
                    if let Some(ready) = self.ready.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
                        ready.send(Err(error));
                    }
                    self.finish();
                    return;
                }
                Err(_) => {
                    builder.take();
                    drop(builder);
                    if let Some(ready) = self.ready.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
                        ready.send(Err(ArtifactEngineOpenRejected::BeforeWal(DbError::Internal("document authority construction panicked".to_string()))));
                    }
                    self.finish();
                    return;
                }
            }
        }
        drop(builder);

        let mut turn = self.turn.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if let Some(active) = turn.as_mut() {
            match active {
                ArtifactTurn::Future(future) => match loop {
                    let polled = std::panic::catch_unwind(AssertUnwindSafe(|| future.as_mut().poll(&mut context)));
                    if !matches!(polled, Ok(std::task::Poll::Pending)) || !self.repoll_within_turn(turn_ends) {
                        break polled;
                    }
                } {
                    Ok(std::task::Poll::Pending) => return,
                    Ok(std::task::Poll::Ready(engine)) => {
                        turn.take();
                        drop(turn);
                        engine.park_writer();
                        *self.engine.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(engine);
                        if self.cancelled.load(Ordering::Acquire) || self.address.is_idle_and_closed() {
                            self.finish();
                        } else if self.address.has_messages() {
                            self.schedule();
                        }
                        return;
                    }
                    Err(_) => {
                        turn.take();
                        drop(turn);
                        self.address.close();
                        self.finish();
                        return;
                    }
                },
                ArtifactTurn::CloseFlush(future) => match std::panic::catch_unwind(AssertUnwindSafe(|| future.as_mut().poll(&mut context))) {
                    Ok(std::task::Poll::Pending) => return,
                    Ok(std::task::Poll::Ready(engine)) => {
                        turn.take();
                        drop(turn);
                        *self.engine.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(engine);
                        self.finish();
                        return;
                    }
                    Err(_) => {
                        turn.take();
                        drop(turn);
                        self.address.close();
                        self.finish();
                        return;
                    }
                },
                ArtifactTurn::History { engine, replay, reply } => {
                    if self.cancelled.load(Ordering::Acquire) || self.address.is_idle_and_closed() {
                        replay.request_close(DbError::Closed);
                    }
                    match loop {
                        let polled = std::panic::catch_unwind(AssertUnwindSafe(|| Pin::new(&mut *replay).poll(&mut context)));
                        if !matches!(polled, Ok(std::task::Poll::Pending)) || !self.repoll_within_turn(turn_ends) {
                            break polled;
                        }
                    } {
                        Ok(std::task::Poll::Pending) => return,
                        Ok(std::task::Poll::Ready(result)) => {
                            let engine = engine.take();
                            if let Some(reply) = reply.take() {
                                reply.send(result);
                            }
                            let replay_empty = replay.terminal_is_empty();
                            if replay_empty {
                                self.handoff.active_history.store(false, Ordering::Release);
                                turn.take();
                            }
                            drop(turn);
                            if let Some(engine) = engine {
                                *self.engine.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(engine);
                            }
                            if !replay_empty {
                                self.schedule();
                            } else if self.cancelled.load(Ordering::Acquire) || self.address.is_idle_and_closed() {
                                self.finish();
                            } else if self.address.has_messages() {
                                self.schedule();
                            }
                            return;
                        }
                        Err(_) => {
                            replay.request_close(DbError::Internal("history replay cursor panicked".to_string()));
                            drop(turn);
                            self.address.close();
                            self.schedule();
                            return;
                        }
                    }
                }
            }
        }
        drop(turn);

        if let Some(envelope) = self.receiver.try_recv() {
            let engine = self.engine.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
            if let Some(engine) = engine {
                let turn = Self::start_turn(engine, envelope.payload);
                self.handoff.active_history.store(matches!(&turn, ArtifactTurn::History { .. }), Ordering::Release);
                *self.turn.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(turn);
                self.schedule();
            } else {
                self.address.close();
                self.finish();
            }
            return;
        }
        if self.cancelled.load(Ordering::Acquire) || self.address.is_idle_and_closed() {
            self.finish();
        }
    }
}

#[cfg(not(target_arch = "wasm32"))]
impl ArtifactAuthority {
    /// 🚀️ Builds the engine on the injected pool and resolves only after construction, so
    /// a caller never receives an authority whose engine failed to open.
    pub async fn spawn<F: Future<Output = Result<Box<ArtifactEngine>, ArtifactEngineOpenRejected>> + Send + 'static>(
        pool: Arc<semio_framework_async::WorkerPool>,
        build: impl FnOnce() -> F + Send + 'static,
        capacities: MailboxCapacities,
    ) -> Result<ArtifactAuthority, ArtifactEngineOpenRejected> {
        let pool_use = pool.acquire_use().map_err(|error| ArtifactEngineOpenRejected::BeforeWal(DbError::Unavailable(format!("artifact authority WorkerPool use rejected: {error:?}"))))?;
        Self::spawn_with_pool_use(pool, pool_use, build, capacities).await
    }

    /// 🧵️ Mounts an authority under an already-retained process-pool use. Database document
    /// mounts pass their exact use cell through this boundary, so no second lifecycle admission
    /// can conflict after the catalog transaction has begun.
    pub(crate) async fn spawn_with_pool_use<F: Future<Output = Result<Box<ArtifactEngine>, ArtifactEngineOpenRejected>> + Send + 'static>(
        pool: Arc<semio_framework_async::WorkerPool>,
        pool_use: Arc<semio_framework_async::WorkerPoolUse>,
        build: impl FnOnce() -> F + Send + 'static,
        capacities: MailboxCapacities,
    ) -> Result<ArtifactAuthority, ArtifactEngineOpenRejected> {
        let retirement = ArtifactRunnerRetirementReservation::try_reserve(pool.clone()).map_err(ArtifactEngineOpenRejected::BeforeWal)?;
        let (address, receiver) = db_actor::mailbox::<ArtifactMessage>(capacities);
        let (ready_tx, ready_rx) = db_actor::oneshot::<Result<(), ArtifactEngineOpenRejected>>();
        let (done_tx, done_rx) = db_actor::oneshot();
        ARTIFACT_RUNNER_HANDOFF_POOL_USES.fetch_add(1, std::sync::atomic::Ordering::AcqRel);
        let handoff = Arc::new(ArtifactRunnerHandoff {
            pool: pool.clone(),
            pool_use: std::sync::Mutex::new(Some(pool_use.clone())),
            terminal_job: std::sync::Mutex::new(None),
            close_runner: std::sync::Mutex::new(None),
            retirement_maintenance: std::sync::Mutex::new(None),
            close_error: std::sync::Mutex::new(None),
            close_retry: std::sync::Mutex::new(ArtifactCloseRetry::clear()),
            #[cfg(test)]
            close_faults: std::sync::atomic::AtomicUsize::new(0),
            #[cfg(test)]
            close_polls: std::sync::atomic::AtomicUsize::new(0),
            #[cfg(test)]
            retirement_turns: std::sync::atomic::AtomicUsize::new(0),
            active_history: std::sync::atomic::AtomicBool::new(false),
            driver: std::sync::atomic::AtomicU8::new(ArtifactRunnerDriver::RunnableIdle as u8),
            terminal: std::sync::atomic::AtomicBool::new(false),
        });
        let runner = Arc::new(ArtifactRunner {
            pool,
            address: address.clone(),
            receiver,
            generation: address.generation().0,
            builder: std::sync::Mutex::new(Some(Box::pin(build()))),
            engine: std::sync::Mutex::new(None),
            turn: std::sync::Mutex::new(None),
            ready: std::sync::Mutex::new(Some(ready_tx)),
            done: std::sync::Mutex::new(Some(done_tx)),
            handoff: handoff.clone(),
            retry_job: std::sync::Mutex::new(None),
            retry_armed: std::sync::atomic::AtomicBool::new(false),
            retry_generation: std::sync::atomic::AtomicU64::new(1),
            cancelled: std::sync::atomic::AtomicBool::new(false),
            close_driving: std::sync::atomic::AtomicBool::new(false),
            terminal: std::sync::atomic::AtomicBool::new(false),
        });
        let weak = Arc::downgrade(&runner);
        address.set_consumer_wake(Arc::new(move || {
            if let Some(runner) = weak.upgrade() {
                runner.schedule();
            }
        }));
        let weak = Arc::downgrade(&runner);
        *handoff.close_runner.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Arc::new(move || -> bool { weak.upgrade().is_none_or(|runner| runner.close_one()) }));
        let retirement_runner = runner.clone();
        let retirement_close: Arc<dyn Fn() -> bool + Send + Sync> = Arc::new(move || retirement_runner.close_one());
        let runner_for_cancel = runner.clone();
        let cancel: Arc<dyn Fn() + Send + Sync> = Arc::new(move || runner_for_cancel.cancel());
        runner.schedule();

        match ready_rx.await {
            Ok(Ok(())) => {
                ARTIFACT_AUTHORITY_POOL_USES.fetch_add(1, std::sync::atomic::Ordering::AcqRel);
                Ok(ArtifactAuthority { address, cancel, handoff, retirement: Some(retirement), retirement_close: Some(retirement_close), _pool_use: pool_use, done: std::sync::Mutex::new(Some(done_rx)) })
            }
            Ok(Err(err)) => Err(err),
            Err(_) => Err(ArtifactEngineOpenRejected::BeforeWal(DbError::Closed)),
        }
    }

    /// 📓️ Nonblocking retained fixed-three decision append through this authority's
    /// existing WAL owner. The opaque record can only be constructed by Store admission.
    pub fn append_durable_group_decision_retained(
        &self,
        record: store::durable_group::DurableOwnedGroupJournalRecordV1,
        cancelled: Arc<std::sync::atomic::AtomicBool>,
        now_ms: u64,
    ) -> db_actor::AskFuture<ArtifactMessage, Result<ArtifactDurableGroupJournalAppendV1, DbError>> {
        self.address.ask(Priority::Command, |reply| ArtifactMessage::AppendDurableGroupDecision { record, cancelled, now_ms, reply })
    }

    /// 🔐️ Builds the Store journal port over this authority's clone-cheap mailbox address;
    /// it never acquires or opens another WAL writer.
    pub fn durable_group_journal_sink(&self, now_ms: u64) -> Box<dyn store::durable_group::DurableOwnedGroupJournalSinkV1> {
        Box::new(ArtifactDurableGroupJournalSinkV1 { address: self.address.clone(), now_ms })
    }

    /// 🧭 Starts one actor-serialized committed-Event replay while the returned owner retains
    /// every exact Store across caller cancellation.
    pub fn durable_group_recovery_retained<ParentP, ParentMutation, DrawingP, DrawingMutation, ValueP, ValueMutation>(
        &self,
        document: ArtifactId,
        admission: store::durable_group::DurableOwnedMapRecoveryAdmissionV1<ParentP, ParentMutation, DrawingP, DrawingMutation, ValueP, ValueMutation>,
    ) -> ArtifactDurableGroupRecoveryOwnerV1<ParentP, ParentMutation, DrawingP, DrawingMutation, ValueP, ValueMutation>
    where
        ParentP: store::ArtifactPack + Clone + store::ToValue + store::FromValue + Send + Sync + 'static,
        ParentMutation: store::Mutation<ParentP> + Clone + store::ToValue + store::FromValue + Send + 'static,
        DrawingP: store::ArtifactPack + Clone + store::ToValue + store::FromValue + Send + Sync + 'static,
        DrawingMutation: store::Mutation<DrawingP> + Clone + store::ToValue + store::FromValue + Send + 'static,
        ValueP: store::ArtifactPack + Clone + store::ToValue + store::FromValue + Send + Sync + 'static,
        ValueMutation: store::Mutation<ValueP> + Clone + store::ToValue + store::FromValue + Send + 'static,
    {
        let (mut owner, driver) = ArtifactDurableGroupRecoveryOwnerV1::new(document, admission);
        owner.request = Some(Box::pin(self.address.ask(Priority::Command, |reply| ArtifactMessage::RecoverDurableGroupDecisions { driver, reply })));
        owner
    }

    pub fn resume_durable_group_recovery<ParentP, ParentMutation, DrawingP, DrawingMutation, ValueP, ValueMutation>(
        &self,
        owner: &mut ArtifactDurableGroupRecoveryOwnerV1<ParentP, ParentMutation, DrawingP, DrawingMutation, ValueP, ValueMutation>,
    ) -> Result<(), DbError>
    where
        ParentP: store::ArtifactPack + Clone + store::ToValue + store::FromValue + Send + Sync + 'static,
        ParentMutation: store::Mutation<ParentP> + Clone + store::ToValue + store::FromValue + Send + 'static,
        DrawingP: store::ArtifactPack + Clone + store::ToValue + store::FromValue + Send + Sync + 'static,
        DrawingMutation: store::Mutation<DrawingP> + Clone + store::ToValue + store::FromValue + Send + 'static,
        ValueP: store::ArtifactPack + Clone + store::ToValue + store::FromValue + Send + Sync + 'static,
        ValueMutation: store::Mutation<ValueP> + Clone + store::ToValue + store::FromValue + Send + 'static,
    {
        if owner.request.is_some() || owner.shared.scan_complete.load(std::sync::atomic::Ordering::Acquire) {
            return Err(DbError::Conflict("durable group recovery scan is already active or complete".to_string()));
        }
        let driver = owner.driver();
        owner.request = Some(Box::pin(self.address.ask(Priority::Command, |reply| ArtifactMessage::RecoverDurableGroupDecisions { driver, reply })));
        Ok(())
    }

    /// 📨️ Nonblocking retained submit cursor used by `db_engine::SubmitFuture`.
    pub fn submit_retained(&self, batch: CommandBatch, options: SubmitOptions, now_ms: u64) -> db_actor::AskFuture<ArtifactMessage, Result<CommandReceipt, DbError>> {
        self.address.ask(Priority::Command, |reply| ArtifactMessage::Submit { batch, options, now_ms, reply })
    }

    pub fn history_retained(&self, operation_generation: u64, cancelled: Arc<std::sync::atomic::AtomicBool>, reservation: HistoryReplayReservation) -> db_actor::AskFuture<ArtifactMessage, Result<ArtifactHistoryView, DbError>> {
        self.address.ask(Priority::Query, |reply| ArtifactMessage::History { operation_generation, cancelled, reservation, reply })
    }

    pub fn compact_retained(
        &self,
        holder: db_storage::DbIoText,
        consolidate_snapshots: bool,
        budget: db_compact::CompactionBudget,
        now_ms: u64,
        cancelled: Arc<std::sync::atomic::AtomicBool>,
    ) -> db_actor::AskFuture<ArtifactMessage, Result<db_compact::CompactionReport, DbError>> {
        self.address.ask(Priority::Command, |reply| ArtifactMessage::Compact { holder, consolidate_snapshots, budget, now_ms, cancelled, reply })
    }

    pub fn generation(&self) -> GenerationId {
        self.address.generation()
    }

    pub fn take_terminal_job(&self) -> Option<ArtifactRunnerTerminalJob> {
        if self.handoff.driver.load(std::sync::atomic::Ordering::Acquire) != ArtifactRunnerDriver::Parked as u8 {
            return None;
        }
        self.handoff.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take().map(|owner| ArtifactRunnerTerminalJob { handoff: self.handoff.clone(), owner: Some(owner) })
    }

    pub fn close_step(&self) -> bool {
        let active = self.handoff.active_history.load(std::sync::atomic::Ordering::Acquire);
        let driver = self.handoff.driver.load(std::sync::atomic::Ordering::Acquire);
        if !active
            && driver != ArtifactRunnerDriver::Parked as u8
            && driver != ArtifactRunnerDriver::ClosingReady as u8
            && driver != ArtifactRunnerDriver::ClosingPolling as u8
            && driver != ArtifactRunnerDriver::ClosingPollingWake as u8
            && driver != ArtifactRunnerDriver::ClosingParked as u8
            && self.handoff.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
        {
            return false;
        }
        let close = self.handoff.close_runner.lock().unwrap_or_else(std::sync::PoisonError::into_inner).clone();
        let closed = close.as_ref().is_none_or(|close| close());
        let mut terminal = self.handoff.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if terminal.is_none() {
            return active;
        }
        if closed {
            let owner = terminal.take();
            drop(owner);
        }
        true
    }

    /// 📈️ Progress of this authority's faulted close retry, `None` while its close is healthy.
    pub fn close_retry_progress(&self) -> Option<ArtifactCloseRetryProgress> {
        self.handoff.close_retry_progress()
    }

    /// 🔂️ Grants an exhausted or cancelled faulted close a fresh bounded retry budget.
    pub fn readmit_close_retry(&self) -> bool {
        self.handoff.readmit_close_retry()
    }

    /// 🛑️ Stops the automatic retries of a faulted close; the runner stays retained for re-admission.
    pub fn cancel_close_retry(&self) -> bool {
        self.handoff.cancel_close_retry()
    }

    pub fn terminal_is_empty(&self) -> bool {
        let driver = self.handoff.driver.load(std::sync::atomic::Ordering::Acquire);
        driver != ArtifactRunnerDriver::Parked as u8
            && driver != ArtifactRunnerDriver::ClosingReady as u8
            && driver != ArtifactRunnerDriver::ClosingPolling as u8
            && driver != ArtifactRunnerDriver::ClosingPollingWake as u8
            && driver != ArtifactRunnerDriver::ClosingParked as u8
            && self.handoff.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
            && !self.handoff.active_history.load(std::sync::atomic::Ordering::Acquire)
    }

    pub async fn submit(&self, batch: CommandBatch, options: SubmitOptions, now_ms: u64) -> Result<CommandReceipt, DbError> {
        self.address.ask(Priority::Command, |reply| ArtifactMessage::Submit { batch, options, now_ms, reply }).await?
    }

    pub async fn query(&self, path: &str) -> Result<Option<db_query::QueryBytes>, DbError> {
        let path = path.to_string();
        self.address.ask(Priority::Query, |reply| ArtifactMessage::Query { path, reply }).await?
    }

    pub async fn frontier(&self) -> Result<Frontier, DbError> {
        self.address.ask(Priority::Query, |reply| ArtifactMessage::Frontier { reply }).await
    }

    /// 📍️ Captures one checkpoint-publication snapshot through the document actor.
    pub async fn checkpoint_publication_snapshot(&self) -> Result<CheckpointPublicationSnapshot, DbError> {
        self.address.ask(Priority::Query, |reply| ArtifactMessage::CheckpointPublicationSnapshot { reply }).await
    }

    pub async fn run_query(&self, query: db_query::Query, consistency: db_query::Consistency) -> Result<db_query::QueryResult, DbError> {
        self.address.ask(Priority::Query, |reply| ArtifactMessage::RunQuery { query, consistency, reply }).await?
    }

    pub async fn snapshot_now(&self, now_ms: u64) -> Result<u64, DbError> {
        self.address.ask(Priority::Command, |reply| ArtifactMessage::SnapshotNow { now_ms, reply }).await?
    }

    pub async fn compact(&self, holder: db_storage::DbIoText, consolidate_snapshots: bool, budget: db_compact::CompactionBudget, now_ms: u64, cancelled: Arc<std::sync::atomic::AtomicBool>) -> Result<db_compact::CompactionReport, DbError> {
        self.compact_retained(holder, consolidate_snapshots, budget, now_ms, cancelled).await?
    }

    /// 🚪️ Requests closure and advances one finite retained runner turn. The authority remains
    /// caller-owned until the returned terminal acknowledgement is `true`.
    /// 🏁️ Takes the one signal that resolves once this authority's runner is terminal — its WAL
    /// closed and its writer released — so a successor mount of the same document can wait for it.
    pub fn take_terminal_signal(&self) -> Option<db_actor::ReplyReceiver<()>> {
        self.done.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take()
    }

    pub fn shutdown_step(&self) -> bool {
        self.address.close();
        (self.cancel)();
        self.close_step();
        self.handoff.terminal.load(std::sync::atomic::Ordering::Acquire)
    }

    #[cfg(test)]
    pub(crate) fn shutdown_debug_witness(&self) -> String {
        let close_error = self.handoff.close_error.lock().unwrap_or_else(std::sync::PoisonError::into_inner).clone();
        let close_retry = self.handoff.close_retry_progress();
        format!(
            "driver={} terminal={} active_history={} terminal_job={} retirement_maintenance={} runner_pool_use={} close_error={:?} close_retry={:?}",
            self.handoff.driver.load(std::sync::atomic::Ordering::Acquire),
            self.handoff.terminal.load(std::sync::atomic::Ordering::Acquire),
            self.handoff.active_history.load(std::sync::atomic::Ordering::Acquire),
            self.handoff.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_some(),
            self.handoff.retirement_maintenance.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_some(),
            self.handoff.pool_use.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_some(),
            close_error,
            close_retry,
        )
    }
}

#[cfg(not(target_arch = "wasm32"))]
impl Drop for ArtifactAuthority {
    fn drop(&mut self) {
        ARTIFACT_AUTHORITY_POOL_USES.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
        if self.handoff.terminal.load(std::sync::atomic::Ordering::Acquire) {
            return;
        }
        self.address.close();
        (self.cancel)();
        let Some(retirement) = self.retirement.take() else { return };
        let Some(close) = self.retirement_close.take() else { return };
        retirement.commit(close, self.handoff.clone(), self._pool_use.clone());
    }
}

#[cfg(not(target_arch = "wasm32"))]
impl ArtifactRunnerTerminalJob {
    pub fn reason(&self) -> semio_framework_async::WorkerSubmitErrorKind {
        self.owner.as_ref().expect("terminal artifact runner job already resolved").0
    }

    pub fn resume(mut self) -> Result<(), Self> {
        let owner = self.owner.take().expect("terminal artifact runner job already resolved");
        if self.handoff.driver.compare_exchange(ArtifactRunnerDriver::Parked as u8, ArtifactRunnerDriver::Queued as u8, std::sync::atomic::Ordering::AcqRel, std::sync::atomic::Ordering::Acquire).is_err() {
            if self.handoff.driver.load(std::sync::atomic::Ordering::Acquire) == ArtifactRunnerDriver::Terminal as u8 {
                return Ok(());
            }
            self.owner = Some(owner);
            return Err(self);
        }
        match self.handoff.pool.try_submit(semio_framework_async::Lane::UserVisible, owner.1) {
            Ok(()) => Ok(()),
            Err(error) => {
                self.handoff.driver.store(ArtifactRunnerDriver::Parked as u8, std::sync::atomic::Ordering::Release);
                self.owner = Some((error.kind(), error.into_job()));
                Err(self)
            }
        }
    }

    pub fn close(mut self) -> Result<(), Self> {
        let owner = self.owner.take().expect("terminal artifact runner job already resolved");
        let driver = self.handoff.driver.load(std::sync::atomic::Ordering::Acquire);
        if driver == ArtifactRunnerDriver::Parked as u8 {
            if self.handoff.driver.compare_exchange(ArtifactRunnerDriver::Parked as u8, ArtifactRunnerDriver::ClosingReady as u8, std::sync::atomic::Ordering::AcqRel, std::sync::atomic::Ordering::Acquire).is_err() {
                self.owner = Some(owner);
                return Err(self);
            }
        } else if driver == ArtifactRunnerDriver::Terminal as u8 {
            return Ok(());
        } else if driver != ArtifactRunnerDriver::ClosingReady as u8 {
            self.owner = Some(owner);
            return Err(self);
        }
        let close = self.handoff.close_runner.lock().unwrap_or_else(std::sync::PoisonError::into_inner).clone();
        let closed = close.as_ref().is_none_or(|close| close());
        if closed {
            self.handoff.driver.store(ArtifactRunnerDriver::Terminal as u8, std::sync::atomic::Ordering::Release);
            Ok(())
        } else {
            self.owner = Some(owner);
            Err(self)
        }
    }
}

#[cfg(not(target_arch = "wasm32"))]
impl Drop for ArtifactRunnerTerminalJob {
    fn drop(&mut self) {
        if let Some(owner) = self.owner.take() {
            if self.handoff.driver.load(std::sync::atomic::Ordering::Acquire) != ArtifactRunnerDriver::Terminal as u8 {
                *self.handoff.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(owner);
            }
        }
    }
}
