    }
    fn body(&mut self,spec:&RecordSpec,record:&RecordValue,output:&mut Output)->Result<(),String>{output.varint(self.symbols.entries.len()as u64,self.control)?;for symbol in &self.symbols.entries{self.control.checkpoint()?;output.varint(symbol.text.len()as u64,self.control)?;output.bytes(symbol.text.as_bytes(),self.control)?;}self.fields(Some(spec),record,0,output)}
}

pub(super) fn record_body(spec:&RecordSpec,record:&RecordValue,options:&EncodeOptions,control:&mut NativeEncodeControl<'_>)->Result<Vec<u8>,PackError>{
    let maximum=usize::try_from(options.limits.max_total_alloc).unwrap_or(usize::MAX).min(control.maximum_bytes());if control.owned_bytes()>maximum{return Err(PackError::LimitExceeded("Pack output admission exceeds max_total_alloc"))}
    control.scoped_maximum(maximum,|control|control.scoped_stage(|control|{control.begin_stage(0)?;let mut symbols=Symbols{entries:Vec::new()};symbols.record(Some(spec),record,0,options.limits.max_depth,control)?;symbols.finish(control)?;let mut encoder=Encoder{symbols:&symbols,options,control,writer:None,chunking:false,next_chunk:0};let mut measure=Output::measure();encoder.body(spec,record,&mut measure)?;if measure.length>maximum.saturating_sub(encoder.control.owned_bytes()){return Err("Pack output exceeds caller allocation allowance".into())}let mut output=Output::allocated(measure.length,encoder.control)?;encoder.body(spec,record,&mut output)?;if output.length!=measure.length{return Err("Pack output length changed between admission and emission".into())}Ok(output.bytes.unwrap())})).map_err(PackError::Schema)
}


pub(super) fn document(spec:&RecordSpec,record:&RecordValue,options:&EncodeOptions,control:&mut NativeEncodeControl<'_>)->Result<Vec<u8>,PackError>{
    let maximum=usize::try_from(options.limits.max_total_alloc).unwrap_or(usize::MAX).min(control.maximum_bytes());
    control.scoped_maximum(maximum,|control|control.scoped_stage(|control|{
        control.begin_stage(0)?;let mut symbols=Symbols{entries:Vec::new()};symbols.record(Some(spec),record,0,options.limits.max_depth,control)?;symbols.finish(control)?;
        let symbol_bytes=|output:&mut Output,control:&mut NativeEncodeControl<'_>|->Result<(),String>{output.varint(symbols.entries.len()as u64,control)?;for symbol in &symbols.entries{control.checkpoint()?;output.varint(symbol.text.len()as u64,control)?;output.bytes(symbol.text.as_bytes(),control)?;}Ok(())};
        let write=crate::os_pack::format::WriteOptions{required_flags:0,optional_flags:if options.canonical{crate::os_pack::format::OPTIONAL_CANONICAL}else{0},codec:options.codec};let mut writer=crate::os_pack::format::ControlledPackWriter::begin(&write,&options.limits,control).map_err(|error|error.to_string())?;
        let mut measure=Output::measure();symbol_bytes(&mut measure,control)?;let mut payload=Output::allocated(measure.length,control)?;symbol_bytes(&mut payload,control)?;writer.symbols(&payload.bytes.unwrap(),symbols.entries.len()as u64,control).map_err(|error|error.to_string())?;
        let mut measure=Output::measure();{let mut encoder=Encoder{symbols:&symbols,options,control,writer:None,chunking:true,next_chunk:0};encoder.fields(Some(spec),record,0,&mut measure)?;}
        let mut payload=Output::allocated(measure.length,control)?;{let mut encoder=Encoder{symbols:&symbols,options,control,writer:Some(&mut writer),chunking:true,next_chunk:0};encoder.fields(Some(spec),record,0,&mut payload)?;}
        if payload.length!=measure.length{return Err("Pack document size changed after admission".into())}let bytes=payload.bytes.unwrap();let start=writer.position();let size=usize::try_from(options.frame_size.max(1)).map_err(|_|"Pack frame size exceeds address space")?;let frames=bytes.len().div_ceil(size);control.scoped_stage(|control|{control.begin_stage(frames)?;for frame in bytes.chunks(size){writer.segment(crate::KIND_DOCUMENT,frame,control).map_err(|error|error.to_string())?;control.step()?;}Ok::<_,String>(())})?;let end=writer.position();let hash=super::schema_hash_controlled(spec,control).map_err(|error|error.to_string())?;
        let manifest=crate::os_pack::format::Manifest{schema_name:String::new(),schema_hash:hash,doc_span:crate::os_pack::ByteRange{offset:start,len:end-start},doc_frame_count:frames as u64,symbols_span:crate::os_pack::ByteRange{offset:0,len:0},chunk_table_span:crate::os_pack::ByteRange{offset:0,len:0},field_index_span:crate::os_pack::ByteRange{offset:0,len:0},uncompressed_body_len:bytes.len()as u64,field_count:record.fields.values().filter(|value|!matches!(value,FieldValue::Absent)).count()as u64,chunk_count:0,symbol_count:symbols.entries.len()as u64};writer.finish(&manifest,control).map_err(|error|error.to_string())
    })).map_err(PackError::Schema)
