impl store::ArtifactDsl for SvgSnapshot {
    const EXTENSION: &'static str = "svg";
    fn envelope_id() -> &'static str {
        "stdio.svg"
    }

    /// 📥️ Two real inputs, told apart by the envelope: text that CARRIES a semio preamble is this
    /// artifact's own snapshot DSL (`encode_snapshot`'s structured body), and text that does not is
    /// the document's own `.svg` markup, which [`SvgSnapshot::import_utf8`] parses losslessly. Same
    /// two-branch shape the sibling `📰️xml` artifact's `parse_dsl` uses, and for the same reason:
    /// `from_text` (this subset's `DerivedConstruction`, and `📚️examples`' own raw markup) hands raw
    /// SVG straight in, and refusing it made every such caller fail on the preamble check alone.
    fn parse_dsl(text: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        match store::semio_format::split_text_preamble(text) {
            Ok((_, body)) => crate::schema::mutation_support::decode_snapshot(body.trim()).map_err(|e| semio_framework_diagnostic::TextError::new(format!("svg state parse: {e}"), semio_framework_diagnostic::TextSpan::at(1, 1))),
            Err(_) => Self::import_utf8(text.as_bytes()).map_err(|e| semio_framework_diagnostic::TextError::new(format!("svg parse: {e}"), semio_framework_diagnostic::TextSpan::at(1, 1))),
        }
    }
    fn print_dsl(&self) -> String {
        let body = crate::schema::mutation_support::encode_snapshot(self);
        let envelope = store::semio_format::SemioEnvelope::from_envelope_id(<Self as store::ArtifactDsl>::envelope_id(), store::semio_format::Component::Dsl, 1).expect("valid envelope_id");
        store::semio_format::wrap_text(&envelope, &body)
    }
}

/// 🧪️ P2-FG3: `stdio.svg` is TEXT-NATIVE (per the W0 census row) — there is no "binary SVG"; the
/// pack container is the SEMIO envelope wrapping the artifact's own REAL wire text
/// (`write_svg_xml`/`parse_svg_xml`, themselves `xml_document_to_text`/`xml_document_from_text`)
/// verbatim, same treatment `📰️xml`'s own `ArtifactPack` gives its restated XML text
/// (`📰️xml/…/📸️snapshot/🦀️.rs`'s own P2-FG1 fix). Replaces the previous
/// generic object-serialization placeholder, which satisfied the trait but did not describe the
/// structured SVG state frame.
impl store::ArtifactPack for SvgSnapshot {
    /// 🪶️ Publishes this owner's actual relational snapshot capability.
    fn sqlite_snapshot_codec() -> Option<store::ArtifactSqliteSnapshotCodec> {
        Some(<Self as store::ArtifactSqliteSnapshot>::sqlite_codec())
    }

    fn encode_pack_with(&self, options: &store::PackEncodeOptions) -> Result<Vec<u8>, store::PackError> {
        let _ = options;
        let mut raw = vec![1];
        crate::schema::mutation_support::encode_snapshot_binary(self, &mut raw);
        let envelope = store::semio_format::SemioEnvelope::from_envelope_id(<Self as store::ArtifactDsl>::envelope_id(), store::semio_format::Component::Pack, 1).map_err(|e| store::PackError::Schema(e.to_string()))?;
        Ok(store::semio_format::wrap_binary(&envelope, &raw))
    }
    fn decode_pack_with(bytes: &[u8], options: &store::PackDecodeOptions) -> Result<Self, store::PackError> {
        let (envelope, inner) = store::semio_format::unwrap_binary(bytes).map_err(|e| store::PackError::Schema(e.to_string()))?;
        if !envelope.matches_identity(<Self as store::ArtifactDsl>::envelope_id(), store::semio_format::Component::Pack, 1) {
            return Err(store::PackError::Schema(format!("pack envelope mismatch: expected {}.pack v1, got {}", <Self as store::ArtifactDsl>::envelope_id(), envelope.binary_token())));
        }
        let _ = options;
        let mut reader = store::ByteReader::new(&inner);
        let version = reader.read_u8().map_err(|e| store::PackError::Schema(e.to_string()))?;
        if version != 1 {
            return Err(store::PackError::Schema(format!("unsupported svg snapshot state version {version}")));
        }
        crate::schema::mutation_support::decode_snapshot_binary(&mut reader).map_err(store::PackError::Schema)
    }
}
