macro_rules! config_mutation {
    ($mutation:ident, $state:ty, $display:literal, $schema:literal) => {
        #[derive(Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue)]
        pub enum $mutation { Snapshot { config: $state } }
