    match tag {
        "I" => Ok(PngTransparency::Indexed { alpha: hex_decode(inner)? }),
        "G" => Ok(PngTransparency::Grayscale { gray: parse_u16(inner)? }),
        "R" => {
            let parts = split_top_level(inner, ',');
