pub(crate) fn dec_chunk(s: &str) -> Result<PngChunk, String> {
    let parts = split_top_level(strip_brackets(s)?, ',');
    let [kind, data] = parts.as_slice() else { return Err(format!("chunk: expected 2 fields, got {}", parts.len())) };
