    match t {
        PngTransparency::Indexed { alpha } => {
            w.write_u8(0);
            write_bin_blob(w, alpha);
        }
        PngTransparency::Grayscale { gray } => {
            w.write_u8(1);
            w.write_u16_le(*gray);
        }
        PngTransparency::Rgb { r, g, b } => {
            w.write_u8(2);
            w.write_u16_le(*r);
            w.write_u16_le(*g);
            w.write_u16_le(*b);
        }
    }
}
