                ("frame", "dcm") => 3.9,
                ("frame", _) => 1.5,
                ("wall", "dch") => 4.4,
                ("wall", "dcm") => 3.0,
                ("wall", _) => 1.5,
                ("dual", "dch") => 5.2,
                ("dual", "dcm") => 3.6,
                ("dual", _) => 1.5,
                _ => 1.5,
            },
            "steel" => match (st.as_str(), dc.as_str()) {
                ("frame", "dch") => 6.5,
                ("frame", "dcm") => 4.0,
                ("frame", _) => 1.5,
                ("wall" | "dual", "dch") => 5.0,
                ("wall" | "dual", "dcm") => 4.0,
                _ => 1.5,
            },
            "composite" => match dc.as_str() {
                "dch" => 6.0,
                "dcm" => 4.0,
                _ => 1.5,
            },
            "timber" => match dc.as_str() {
                "dch" => 5.0,
                "dcm" => 2.5,
                _ => 1.5,
            },
            "masonry" => match dc.as_str() {
                "dcm" | "dch" => 2.5,
                _ => 1.5,
            },
            _ => 1.5,
        }
    }

    /// 🧱 RC column min b [m] for DCM/DCH (§5.4.3.2.1 / §5.5.3.2.1 simplified).
    pub fn rc_column_min_b_m(ductility: &str) -> f64 {
