//! 💾️ Direct change-gamma binary codec.
use super::*;
use crate::schema::mutations::binary::Entry;
pub const BINARY_TAG: u8 = dsl::protocol_record::tag_u8(include_str!("../../💾️binary/📡️.protocol.semio"), "change-gamma");
pub const CODEC: Entry = Entry { tag: BINARY_TAG, encode, decode };

pub fn encode(value: &PngMutation) -> Option<Result<Vec<u8>, protocol::ProtocolError>> {
    let PngMutation::ChangeGamma(payload) = value else { return None };
    Some(encode_payload(payload))
}
pub fn encode_payload(payload: &ChangeGammaMutation) -> Result<Vec<u8>, protocol::ProtocolError> {
    let ChangeGammaMutation { gama } = payload;
    let mut w = dsl::ByteWriter::new();
    write_bin_option(&mut w, gama, |w, v: &u32| w.write_u32_le(*v));
    Ok(w.into_bytes())
}
fn op_pack_err(error: &dsl::PackError) -> protocol::ProtocolError {
    protocol::ProtocolError::Malformed { what: "change-gamma", offset: 0, detail: error.to_string() }
}
pub fn decode(bytes: &[u8]) -> Result<PngMutation, protocol::ProtocolError> {
    let mut r = dsl::ByteReader::new(bytes);
    let result: Result<PngMutation, protocol::ProtocolError> = Ok(PngMutation::ChangeGamma(ChangeGammaMutation { gama: read_bin_option(&mut r, |r| r.read_u32_le()).map_err(|error| op_pack_err(&error))? }));
    let position = r.position();
    if position != bytes.len() {
        return Err(protocol::ProtocolError::Malformed { what: "change-gamma", offset: position as u64, detail: "trailing payload bytes".into() });
    }
    result
}

//! 💾️ Direct insert-unknown-chunk binary codec.
use super::*;
use crate::schema::mutations::binary::Entry;
pub const BINARY_TAG: u8 = dsl::protocol_record::tag_u8(include_str!("../../💾️binary/📡️.protocol.semio"), "insert-unknown-chunk");
pub const CODEC: Entry = Entry { tag: BINARY_TAG, encode, decode };

pub fn encode(value: &PngMutation) -> Option<Result<Vec<u8>, protocol::ProtocolError>> {
    let PngMutation::InsertUnknownChunk(payload) = value else { return None };
    Some(encode_payload(payload))
}
pub fn encode_payload(payload: &InsertUnknownChunkMutation) -> Result<Vec<u8>, protocol::ProtocolError> {
    let InsertUnknownChunkMutation { index, chunk } = payload;
    let mut w = dsl::ByteWriter::new();
    w.write_varint_u64(*index as u64);
    write_bin_chunk(&mut w, chunk);
    Ok(w.into_bytes())
}
fn op_pack_err(error: &dsl::PackError) -> protocol::ProtocolError {
    protocol::ProtocolError::Malformed { what: "insert-unknown-chunk", offset: 0, detail: error.to_string() }
}
pub fn decode(bytes: &[u8]) -> Result<PngMutation, protocol::ProtocolError> {
    let mut r = dsl::ByteReader::new(bytes);
    let result: Result<PngMutation, protocol::ProtocolError> = Ok({
        let index = r.read_varint_u64().map_err(|error| op_pack_err(&error))? as usize;
        let chunk = read_bin_chunk(&mut r).map_err(|error| op_pack_err(&error))?;
        PngMutation::InsertUnknownChunk(InsertUnknownChunkMutation { index, chunk })
    });
    let position = r.position();
    if position != bytes.len() {
        return Err(protocol::ProtocolError::Malformed { what: "insert-unknown-chunk", offset: position as u64, detail: "trailing payload bytes".into() });
    }
    result
}

