}

impl Default for Puzzle3dPatchInspectorWork {
    fn default() -> Self {
        Self {
            stage: Puzzle3dPatchInspectorStage::Selection,
            selection_cursor: 0,
            item_cursor: 0,
            child_cursor: 0,
