/// 🧪️ F6: `dsl::DslScalar` — a plain unit-variant-only enum binds as `DslField` directly (§3a of
/// `f6-recon-report.md`: `DslScalar` is one of the two derive sources for `DslField`, unit
/// variants only), letting `Option<LineEnding>`/`LineEnding` fields embed in `TxtDiff`/
/// `TxtSnapshot`/`TxtMutation` below without hand-rolling.
#[derive(Clone, Copy, Debug, PartialEq, Eq, value_derive::ToValue, value_derive::FromValue, Default, dsl::DslScalar)]
#[value(rename_all = "camelCase")]
pub enum LineEnding {
    #[default]
    Lf,
    CrLf,
}

impl LineEnding {
    /// 🔤️ The literal byte sequence this line ending prints as.
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    pub fn as_str(self) -> &'static str {
        match self {
            LineEnding::Lf => "\n",
            LineEnding::CrLf => "\r\n",
        }
    }
}
//#endregion 🔖️LineEnding

//#region 🔖️Snapshot
/// 📸️ Persisted `stdio.txt` snapshot — complete per the "a text file is a sequence of lines"
/// spec: line content, whether the last line is newline-terminated, and which newline style
/// the document uses (spec covers exactly `Lf`/`CrLf`, never a mixed per-line style).
///
/// 🧪️ F6: `dsl::DslRecord` added alongside the existing hand-rolled `store::ArtifactDsl`/
/// `store::ArtifactPack` below — NOT a replacement. `DslRecord` only gives this type `DslField`
/// (so it can be carried by direct mutation payloads and storage surfaces), it
/// does not touch the artifact's own honest line-joined-by-line-ending envelope format.
#[derive(Clone, Debug, PartialEq, value_derive::ToValue, value_derive::FromValue, ArtifactSchema, dsl::DslRecord)]
#[value(rename_all = "camelCase")]
#[artifact_schema(id = "s.stdio.txt")]
pub struct TxtSnapshot {
    #[state(artifact)]
    pub schema: String,
    #[state(artifact)]
    #[value(default)]
    pub lines: Vec<String>,
    #[state(artifact)]
    #[value(default)]
    pub trailing_newline: bool,
    #[state(artifact)]
    #[value(default)]
    pub line_ending: LineEnding,
}

impl Default for TxtSnapshot {
    fn default() -> Self {
        Self { schema: STDIO_TXT_DOCUMENT_SCHEMA.into(), lines: Vec::new(), trailing_newline: false, line_ending: LineEnding::Lf }
    }
}

impl TxtSnapshot {
    /// 🧵️ Reconstructs the full text body (lines joined by `line_ending`, with the trailing
    /// newline appended iff `trailing_newline`). Inverse of [`Self::from_body`].
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    pub fn to_body(&self) -> String {
        let sep = self.line_ending.as_str();
        let mut out = self.lines.join(sep);
        if self.trailing_newline {
            out.push_str(sep);
        }
        out
    }

    /// 🔍️ Splits a raw text body into `(lines, trailing_newline, line_ending)`. An empty body
    /// is zero lines (not one empty line) — the only case that needs special-casing, since
    /// `"".split(sep)` would otherwise yield a single empty-string element.
    // 🚫️async: E1 pure inherent-impl helper (file verified I/O-free, consumed via opaque-type-hostile call site) — see R9
    pub fn from_body(body: &str) -> Self {
        if body.is_empty() {
            return Self { schema: STDIO_TXT_DOCUMENT_SCHEMA.into(), lines: Vec::new(), trailing_newline: false, line_ending: LineEnding::Lf };
        }
        let line_ending = if body.contains("\r\n") { LineEnding::CrLf } else { LineEnding::Lf };
        let sep = line_ending.as_str();
        let trailing_newline = body.ends_with(sep);
        let content = if trailing_newline { &body[..body.len() - sep.len()] } else { body };
        let lines: Vec<String> = content.split(sep).map(String::from).collect();
        Self { schema: STDIO_TXT_DOCUMENT_SCHEMA.into(), lines, trailing_newline, line_ending }
    }
}
//#endregion 🔖️Snapshot

//#region 🔖️HandcraftedArtifactCodecs
/// 🧬️ CARRIER LAW (ticket 26/08/17/CLEAN-ARTIFACT-STANDARD-SUBSET-MECHANISM design.md §3):
/// `s.stdio.txt@utf-8/*` is `CARRIER_TEXT` — its native `Text` `IoPayload` IS the raw external
/// file text, verbatim. The previous impl prepended a `semio stdio.txt.dsl v1` preamble line
/// (`wrap_text`) and stripped it back off on parse, which made every exported `.txt` file carry
/// a foreign header line instead of the honest raw text. Fixed here (the codec, not the test):
/// `parse_dsl`/`print_dsl` are now `TxtSnapshot::from_body`/`to_body` directly, no preamble.
/// Proven by `carrier_native_is_raw` in `🚪️io/🦀️.rs`.
impl store::ArtifactDsl for TxtSnapshot {
    const EXTENSION: &'static str = "txt";
    fn envelope_id() -> &'static str {
        "stdio.txt"
    }

    fn parse_dsl(text: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        Ok(Self::from_body(text))
    }
    fn print_dsl(&self) -> String {
        self.to_body()
    }
}

impl store::ArtifactPack for TxtSnapshot {
    /// 🪶️ Publishes this owner's actual relational snapshot capability.
    fn sqlite_snapshot_codec() -> Option<store::ArtifactSqliteSnapshotCodec> {
        Some(<Self as store::ArtifactSqliteSnapshot>::sqlite_codec())
    }

    fn encode_pack_with(&self, options: &store::PackEncodeOptions) -> Result<Vec<u8>, store::PackError> {
        let _ = options;

        let raw = self.to_body();
        let envelope = store::semio_format::SemioEnvelope::from_envelope_id(<Self as store::ArtifactDsl>::envelope_id(), store::semio_format::Component::Pack, 1).map_err(|e| store::PackError::Schema(e.to_string()))?;
        Ok(store::semio_format::wrap_binary(&envelope, raw.as_bytes()))
    }
    fn decode_pack_with(bytes: &[u8], options: &store::PackDecodeOptions) -> Result<Self, store::PackError> {
        let (envelope, inner) = store::semio_format::unwrap_binary(bytes).map_err(|e| store::PackError::Schema(e.to_string()))?;
        if !envelope.matches_identity(<Self as store::ArtifactDsl>::envelope_id(), store::semio_format::Component::Pack, 1) {
            return Err(store::PackError::Schema(format!("pack envelope mismatch: expected {}.pack v1, got {}", <Self as store::ArtifactDsl>::envelope_id(), envelope.binary_token())));
        }
        let _ = options;
        let body = String::from_utf8(inner).map_err(|e| store::PackError::Schema(e.to_string()))?;
        Ok(Self::from_body(&body))
    }
    /// 🧬️ The structural fingerprint `ArtifactCodec::pack_schema_hash` and the hub's trusted
    /// catalog pin this kind by. The `dsl::DslRecord` derive above already generates the spec —
    /// the same one `register_schema_spec("stdio.txt", TxtSnapshot::__dsl_spec)` publishes to the
    /// DSL registry — but a HAND-ROLLED `ArtifactPack` never picks up the derive's `record_spec`
    /// override the way `DslArtifact` does, so this kind silently answered the trait's `None`
    /// opt-out. That opt-out is what `codec.pack-schema-hash(stdio.txt)` reported as
    /// `artifact codec schema has no structural record specification`, and what the catalog
    /// builder refuses as the zero fingerprint (ticket 26/09/18 slice TC4). The body's raw
    /// line-joined pack encoding is unaffected: this hash fingerprints the SNAPSHOT RECORD's
    /// fields, not the pack container.
    fn record_spec() -> Option<dsl::RecordSpec> {
        Some(Self::__dsl_spec())
    }
}
//#endregion 🔖️HandcraftedArtifactCodecs

